INSERT INTO Spell (id_spell, name, description, casting_time, range_distance, duration, damage, is_verbal, is_somatic, is_material, spellLevel, school) VALUES
(2, 'Acalmar Emoções', 'Você tenta suprimir emoções fortes em um grupo de criaturas. Cada humanoide dentro de uma esfera de 6 metros de raio centrada em um ponto dentro do alcance da magia deve fazer uma salvaguarda de Carisma; uma criatura pode escolher falhar nesta salvaguarda, caso deseje. Se uma criatura falhar na salvaguarda, escolha um dos dois efeitos: suprimir qualquer efeito que cause a ela as condições enfeitiçado ou amedrontado (o efeito suprimido retorna quando a magia terminar, caso a duração não tenha expirado); ou tornar o alvo indiferente em relação a criaturas ou coisas que você escolher.', '1 ação', 18, 'Concentração, até 1 minuto', NULL, TRUE, TRUE, FALSE, 2, 'Encantamento'),
(3, 'Adivinhação', 'Sua magia e uma oferenda colocam você em contato com um deus ou servo divino. Você faz uma única pergunta a respeito de um objetivo, evento ou atividade específico que irá ocorrer dentro de 7 dias. O Mestre oferece uma resposta confiável. A resposta deve ser uma frase curta, uma rima enigmática ou um presságio. A magia não leva em consideração qualquer possível circunstância que possa mudar o que está por vir, como a conjuração de magias adicionais ou a perda ou ganho de um companheiro. Se você conjurar a magia duas ou mais vezes antes de completar seu próximo descanso longo, existe uma chance cumulativa de 25 por cento de cada conjuração, depois da primeira que você fez, ter um resultado aleatório. O Mestre faz essa jogada secretamente.', '1 ação', 0, 'Instantânea', NULL, TRUE, TRUE, TRUE, 4, 'Adivinhação'),
(4, 'Ajuda', 'Sua magia inspira seus aliados com vigor e determinação. Escolha até três criaturas dentro do alcance. O máximo de pontos de vida e os pontos de vida atuais de cada alvo aumentam em 5, pela duração. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 3° nível ou superior, os pontos de vida dos alvos aumentam em 5 pontos adicionais para cada nível do espaço acima do o 2°.', '1 ação', 9, '8 horas', NULL, TRUE, TRUE, TRUE, 2, 'Abjuração'),
(5, 'Alarme', 'Você coloca um alarme para intrusos desavisados. Escolha uma porta, uma janela ou uma área dentro do alcance que não seja maior que 6 metros cúbicos. Até a magia acabar, um alarme alerta você sempre que uma criatura Miúda ou maior tocarem ou entrarem na área protegida. Quando você conjura a magia, você pode designar as criaturas que não ativarão o alarme. Você também escolhe se o alarme será mental ou audível. Um alarme mental alerta você com um silvo na sua mente, se você estiver a até de 1,5 quilômetro da área protegida. Esse silvo acordará você se você estiver dormindo. Um alarme audível produz o som de um sino de mão por 10 minutos num raio de 18 metros.', '1 minuto', 9, '8 horas', NULL, TRUE, TRUE, TRUE, 1, 'Abjuração'),
(6, 'Aliado Planar', 'Você suplica a uma entidade transcendental por ajuda. O ser deve ser conhecido por você: seu deus, um primordial, um príncipe demônio ou algum outro ser de poder cósmico. Essa entidade envia um celestial, um corruptor ou um elemental leal a ela para ajudar você, fazendo a criatura aparecer em um espaço desocupado dentro do alcance. Se você conhecer o nome de uma criatura especifica, você pode falar o nome quando conjurar essa magia para requisitar essa criatura, do contrário, você pode receber uma criatura diferente de qualquer forma (à escolha do Mestre). Quando a criatura aparecer, ela não está sob nenhuma compulsão para se comportar de um modo em particular. Você pode pedir a criatura que realize um serviço em troca de um pagamento, mas ela não é obrigada a fazê-lo. A tarefa solicitada pode variar de simples (carregue-nos voando para o outro lado do abismo ou nos ajude a lutar essa batalha) a complexa (espione nossos inimigos ou nos proteja durante nossa incursão na masmorra). Você deve ser capaz de se comunicar com a criatura para barganhar os serviços dela. O pagamento pode ser feito de várias formas. Um celestial pode requerer uma generosa doação de ouro ou itens mágicos para um templo aliado, enquanto que um corruptor pode exigir um sacrifício vivo ou uma parte dos espólios. Algumas criaturas podem trocar seus serviços por uma missão feita por você. Como regra geral, uma tarefa que possa ser medida em minutos, exigirá um pagamento de 100 po por minuto. Uma tarefa medida em horas exigirá 1.000 po por hora. E uma tarefa medida em dias (até 10 dias) exigirá 10.000 po por dia. O Mestre pode ajustar esses pagamentos baseado nas circunstâncias pelas quais a magia foi conjurada. Se a tarefa estiver de acordo com o caráter da criatura, o pagamento pode ser reduzido à metade, ou mesmo dispensado. Tarefas que não proporcionem perigo, tipicamente requerem apenas metade do pagamento sugerido, enquanto que tarefas especialmente perigosas podem exigir um grande presente. As criaturas raramente aceitarão tarefas que pareçam suicidas. Após a criatura completar a tarefa ou quando a duração acordada para o serviço expirar, a criatura retornará para seu plano natal depois de relatar sua partida a você, se apropriado para a tarefa e se possível. Se você não for capaz de acertar um preço para os serviços da criatura, ela imediatamente voltará para o seu plano natal. Uma criatura convidada para se juntar ao seu grupo, conta como um membro dele, recebendo sua parte total na premiação de pontos de experiência.', '10 minutos', 18, 'Instantânea', NULL, TRUE, TRUE, FALSE, 6, 'Conjuração'),
(7, 'Aljava Veloz', 'Você transmuta sua aljava para que ela produza um suprimento interminável de munições não-mágicas, que parecem saltar na sua mão quando você tenta pega-las. Em cada um dos seus turnos, até a magia acabar, você pode usar uma ação bônus para realizar dois ataques com uma arma que use munição de uma aljava. Cada vez que você fizer tais ataques à distância, sua aljava, magicamente, repõe a munição que você usou com uma munição não-mágica similar. Qualquer munição criada por essa magia se desintegra quando a magia acaba. Se a aljava não estiver mais com você, a magia acaba.', '1 ação bônus', 1, 'Concentração, até 1 minuto', NULL, TRUE, TRUE, TRUE, 5, 'Transmutação'),
(8, 'Alterar Forma', 'Você assume a forma de uma criatura diferente, pela duração. A nova forma pode ser qualquer criatura com um nível de desafio igual ao seu nível ou menor. A criatura não pode ser nem um constructo nem um morto vivo e você deve ter visto esse tipo de criatura pelo menos uma vez. Você se transforma num exemplar médio da criatura, um sem quaisquer níveis de classe nem característica Conjuração. Suas estatísticas de jogo são substituídas pelas estatísticas da forma escolhida, no entanto, você mantem sua tendência e valores de Inteligência, Sabedoria e Carisma. Você também mantem suas proficiências em testes de resistência, além de ganhar as da nova criatura. Se a criatura tiver a mesma proficiência que você e o bônus listado nas estatísticas dela for maior que o seu, use os bônus da criatura no lugar do seu. Você não pode usar qualquer ação lendária ou de covil da nova forma. Você assume os pontos de vida e Dados de Vida da sua nova forma. Quando você reverter a sua forma normal, você retorna à quantidade de pontos de vida que tinha antes da transformação. Se você reverter como resultado de ter caído a 0 pontos de vida, qualquer dano excedente é recebido pela sua forma normal. Contanto que o dano excedente não reduza os pontos de vida da sua forma normal a 0, você não cairá inconsciente. Você mantem os benefícios de qualquer característica da sua classe, raça ou outra fonte e pode usa-las, considerando que sua nova forma é fisicamente capaz de fazê-lo. Você não pode usar quaisquer sentidos especiais que você possua (por exemplo, visão no escuro) a não ser que a nova forma também possua o sentido. Você só poderá falar se a nova forma, normalmente, puder falar. Quando você se transforma, você pode escolher se o seu equipamento cai no chão, é assimilado a sua nova forma ou é usado por ela. Equipamentos vestidos e carregados funcionam normalmente. O Mestre decide qual equipamento é viável para a nova forma vestir ou usar, baseado na forma e tamanho da criatura. O seu equipamento não muda de forma ou tamanho para se adaptar à nova forma e, qualquer equipamento que a nova forma não possa vestir deve, ou cair no chão ou ser assimilado por ela. Equipamentos assimilados não terão efeito nesse estado. Pela duração da magia, você pode usar sua ação para assumir uma forma diferente, seguindo as mesmas restrições e regras da forma anterior, com uma exceção: se sua nova forma tiver mais pontos de vida que sua forma atual, seus pontos de vida mantem o valor atual.', '1 ação', 0, 'Concentração, até 1 hora', NULL, TRUE, TRUE, TRUE, 9, 'Transmutação'),
(9, 'Alterar-se', 'Você assume uma forma diferente. Quando conjurar a magia, escolha uma das opções a seguir, cujos efeitos persistem enquanto a magia durar. Dentro desse período, você pode usar uma ação para finalizar uma das opções escolhidas e obter os benefícios de outra. Adaptação Aquática: você adapta seu corpo para o ambiente aquático, com guelras crescendo e membranas nascendo entre seus dedos — você pode respirar debaixo d''água e ganha deslocamento de natação com valor igual ao seu deslocamento de caminhada.', '1 ação', 0, 'Concentração, até 1 hora', '1d6', TRUE, TRUE, FALSE, 2, 'Transmutação'),
(10, 'Amizade', 'Enquanto a magia durar, você tem vantagem em todos os testes de Carisma dirigidos a uma criatura, à sua escolha e que não seja hostil a você. Ao término da magia, a criatura percebe que você usou magia para influenciar o humor dela, tornando-se hostil a você. Uma criatura propensa à violência pode lhe atacar. Criaturas não violentas podem buscar outras formas de retaliação (a critério do DM), dependendo da natureza da sua interação com ela.', '1 ação', 0, 'Concentração, até 1 minuto', NULL, FALSE, TRUE, TRUE, 0, 'Encantamento'),
(11, 'Amizade Animal', 'Essa magia deixa você convencer uma besta que você não quer prejudicar. Escolha uma besta que você possa ver dentro do alcance. Ela deve ver e ouvir você. Se a Inteligência da besta for 4 ou maior, a magia falha. Do contrário, a besta deve ser bem sucedida num teste de resistência de Sabedoria ou ficará enfeitiçada por você pela duração da magia. Se você ou um dos seus companheiros ferir o alvo, a magia termina. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 2° nível ou superior, você pode afetar uma besta adicional para cada nível do espaço acima do 1°.', '1 ação', 9, '24 horas', NULL, TRUE, TRUE, TRUE, 1, 'Encantamento'),
(12, 'Ampliar Plantas', 'Esta magia canaliza vitalidade para as plantas dentro de uma área específica, com dois usos possíveis: benefícios imediatos ou de longa duração. Se você conjurar esta magia usando 1 ação, escolha um ponto dentro do alcance. Todas as plantas normais em um raio de 30 metros centradas neste ponto tornam-se espessas e super desenvolvidas. Uma criatura se movendo através da área deve gastar 6 metros de movimento para cada 1,5 metro que se mover. Você pode excluir uma ou mais áreas de qualquer tamanho dentro da área da magia a ser afetada.', '1 ação ou 8 horas', 45, 'Instantânea', NULL, TRUE, TRUE, FALSE, 3, 'Transmutação'),
(13, 'Âncora Planar', 'Com essa magia, você tenta obrigar um celestial, corruptor, elemental ou fada a servi-lo. A criatura deve estar dentro do alcance durante toda a conjuração da magia. (Tipicamente, a criatura, primeiramente, é invocada dentro de um círculo mágico invertido para mantê-la presa enquanto a magia é conjurada.) Ao completar a conjuração, o alvo deve realizar um teste de resistência de Carisma. Se falhar na resistência, ela é obrigada a servir você pela duração. Se a criatura foi invocada ou criada por outra magia, a duração da magia é estendida para se equiparar a dessa magia. Uma criatura obrigada deve seguir suas instruções da melhor forma que puder. Você poderia comandar a criatura a acompanhar você em uma aventura, a guardar um local ou a enviar uma mensagem. A criatura obedece ao pé da letra suas instruções, mas se a criatura for hostil a você, ela se esforçará para distorcer suas palavras para atingir seus próprios objetivos. Se a criatura atender suas instruções completamente antes da magia acabar, ela viajará até você para relatar esse fato se você estiver no mesmo plano de existência. Se você estiver em um plano de existência diferente, ela retornará para o lugar onde você a contatou e permanecerá lá até a magia acabar. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de nível superior, a duração aumenta para 10 dias com um espaço de 6° nível, para 30 dias com um espaço de 7° nível, para 180 dias com um espaço de 8° nível e para um ano com um espaço de magia de 9° nível.', '1 hora', 18, '24 horas', NULL, TRUE, TRUE, TRUE, 5, 'Abjuração'),
(14, 'Andar na Água', 'Esta magia concede a capacidade de deslocamento sobre qualquer superfície líquida — como água, ácido, lama, neve, areia movediça ou lava — como se fosse terra firme.', '1 ação', 9, '1 hora', NULL, TRUE, TRUE, TRUE, 3, 'Transmutação'),
(15, 'Animar Mortos', 'Essa magia cria um servo morto-vivo. Escolha uma pilha de ossos ou um corpo de um humanoide Médio ou Pequeno dentro do alcance. Sua magia imbui o alvo com uma imitação corrompida de vida, erguendo-o como uma criatura morta-viva. O alvo se torna um esqueleto, se você escolheu ossos, ou um zumbi, se você escolheu um corpo (o Mestre tem as estatísticas de jogo da criatura). Em cada um dos seus turnos, você pode usar uma ação bônus para comandar mentalmente qualquer criatura que você criou com essa magia, se a criatura estiver a até 18 metros de você (se você controla diversas criaturas, você pode comandar qualquer uma ou todas elas ao mesmo tempo, emitindo o mesmo comando para cada uma). Você decide qual ação a criatura irá fazer e para onde ela irá se mover durante o próximo turno dela, ou você pode emitir um comando geral, como para guardar uma câmara ou corredor especifico. Se você não der nenhum comando, as criaturas apenas se defenderão contra criaturas hostis. Uma vez que receba uma ordem, a criatura continuará a segui-la até a tarefa estar concluída. A criatura fica sob seu controle por 24 horas, depois disso ela para de obedecer aos seus comandos. Para manter o controle da criatura por mais 24 horas, você deve conjurar essa magia na criatura novamente, antes das 24 horas atuais terminarem. Esse uso da magia recupera seu controle sobre até quatro criaturas que você tenha animado com essa magia, ao invés de animar uma nova. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 4° nível ou superior, você pode animar ou recuperar o controle de duas criaturas mortas-vivas para cada nível do espaço acima do 3°. Cada uma dessas criaturas deve vir de um corpo ou pilha de ossos diferente.', '1 minuto', 3, 'Instantânea', NULL, TRUE, TRUE, TRUE, 3, 'Necromancia'),
(16, 'Animar Objetos', 'Objetos ganham vida ao seu comando. Escolha até dez objetos não-mágicos dentro do alcance, que não estejam sendo vestidos ou carregados. Alvos Médios contam como dois objetos, alvos Grandes contam como quatro objetos e alvos Enormes contam como oito objetos. Você não pode animar um objeto maior que Enorme. Cada alvo se anima e torna-se uma criatura sob seu controle até o final da magia ou até ser reduzido a 0 pontos de vida. Com uma ação bônus, você pode comandar mentalmente qualquer criatura que você criar com essa magia se a criatura estiver a até 150 metros de você (se você controla várias criaturas, você pode comandar qualquer ou todas elas ao mesmo tempo, emitindo o mesmo comando para cada uma). Você decide qual ação a criatura irá fazer e para onde ela irá se mover durante o próximo turno dela, ou você pode emitir um comando geral, como para guardar uma câmara ou corredor especifico. Se você não der nenhum comando, as criaturas apenas se defenderão contra criaturas hostis. Uma vez que receba uma ordem, a criatura continuará a segui-la até a tarefa estar concluída. ESTATÍSTICAS DE OBJETO ANIMADO Tamanho PV CA Ataque For Des Miúdo +8 para atingir, 1d4 + 4 dano Pequeno 25 16 +6 para atingir, 1d8 + 2 dano 6 14 Médio +5 para atingir, 2d6 + 1 dano Grande 50 10 +6 para atingir, 2d10 + 2 dano 14 10 Enorme +8 para atingir, 2d12 + 4 dano Um objeto animado é um constructo com CA, pontos de vida, ataques, Força e Destreza determinados pelo seu tamanho. Sua Constituição é 10 e sua Inteligência e Sabedoria são 3 e seu Carisma é 1. Seu deslocamento é 9 metros; se o objeto não tiver pernas ou outros apêndices que ele possa usar para locomoção, ao invés, ele terá deslocamento de voo 9 metros e poderá planar. Se o objeto estiver firmemente preso a uma superfície ou objeto maior, como uma corrente presa a uma parede, seu deslocamento será 0. Ele tem percepção às cegas num raio de 9 metros e é cego além dessa distância. Quando o objeto animado cair a 0 pontos de vida, ele reverte a sua forma normal de objeto e qualquer dano restante é transferido para sua forma de objeto original. Se você ordenar a um objeto que ataque, ele pode realizar um único ataque corpo-a-corpo contra uma criatura a até 1,5 metro dele. Ele realiza um ataque de pancada com um bônus de ataque e dano de concussão determinado pelo seu tamanho. O Mestre pode definir que um objeto especifico inflige dano cortante ou perfurante, baseado na forma dele. Em Níveis Superiores. Se você conjurar essa magia usando um espaço de magia de 6° nível ou superior, você pode animar dois objetos adicionais para cada nível do espaço acima do 5°.', '1 ação', 36, 'Concentração, até 1 minuto', '1d4+4', TRUE, TRUE, FALSE, 5, 'Transmutação'),
(17, 'Antipatia/Simpatia', 'Essa magia atrai ou repele as criaturas de sua escolha. Você escolhe um alvo dentro do alcance, tanto um objeto ou criatura Enorme ou menor ou uma área que não seja maior que 60 metros cúbicos. Então, especifica um tipo de criatura inteligente, como dragões vermelhos, goblins ou vampiros. Você envolve o alvo com uma aura que pode atrair ou repelir as criaturas especificas pela duração. Escolha antipatia ou simpatia como efeito da aura. Antipatia. O encantamento faz com que criaturas do tipo designado por você sintam-se fortemente impelidos em deixar a área e evitar o alvo. Quando uma dessas criaturas puder ver o alvo ou ficar a 18 metros dele, a criatura deve ser bem sucedida num teste de resistência de Sabedoria ou ficará amedrontada. A criatura continuará amedrontada enquanto puder ver o alvo ou permanecer a 18 metros dele. Enquanto estiver amedrontada pelo alvo, a criatura deve usar seu deslocamento para se mover para o local seguro mais próximo o qual ela não possa ver o alvo. Se a criatura se mover para mais de 18 metros do alvo e não puder vê-lo, a criatura não estará mais amedrontada, mas ela ficará amedrontada novamente se voltar a ver o alvo ou ficar a 18 metros dele. Simpatia. O encantamento faz com que as criaturas especificadas sintam-se fortemente impelidos a se aproximar do alvo enquanto estiverem a 18 metros dele ou puderem vê-lo. Quando uma dessas criaturas puder ver o alvo ou ficar a 18 metros dele, a criatura deve ser bem sucedida num teste de resistência de Vontade ou usará seu deslocamento em cada um dos seus turnos para entrar na área ou se mover até o alcance do alvo. Quando a criatura tiver feito isso, ela não poderá se afastar do alvo voluntariamente. Se o alvo causar dano ou ferir a criatura afetada de alguma forma, a criatura afetada pode realizar um novo teste de resistência de Sabedoria para terminar o efeito, como descrito abaixo. Terminando o Efeito. Se uma criatura afetada terminar se turno enquanto não estiver a até 18 metros do alvo ou não for capaz de vê-lo, a criatura faz um teste de resistência de Sabedoria. Em um sucesso, a criatura não estará mais afetada pelo alvo e reconhecerá o sentimento de repugnância ou atração como mágico. Além disso, uma criatura afetada pela magia tem direito a outro teste de resistência de Sabedoria a cada 24 horas enquanto a magia durar. Uma criatura que obtenha sucesso na resistência contra esse efeito ficará imune a ele por 1 minuto, depois desse tempo, ela pode ser afetada novamente.', '1 hora', 18, '10 dias', NULL, TRUE, TRUE, TRUE, 8, 'Encantamento'),
(18, 'Aprimorar Habilidade', 'Você toca uma criatura e a agracia com aprimoramento mágico. Escolha um dos efeitos a seguir; o alvo ganha esse efeito até o fim da magia. Agilidade do Gato. O alvo tem vantagem em testes de Destreza. Ele também não sofre dano ao cair de 6 metros ou menos, se não estiver incapacitado. Esperteza da Raposa. O alvo tem vantagem em testes de Inteligência. Esplendor da Águia. O alvo tem vantagem em testes de Carisma. Força do Touro. O alvo tem vantagem em testes de Força e sua capacidade de carga é dobrada. Sabedoria da Coruja. O alvo tem vantagem em testes de Sabedoria. Vigor do Urso. O alvo tem vantagem em testes de Constituição. Ele também recebe 2d6 pontos de vida temporários, que são perdidos quando a magia termina. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 3° nível ou superior, você pode afetar uma criatura adicional para cada nível do espaço acima do 2°.', '1 ação', 1, 'Concentração, até 1 hora', NULL, TRUE, TRUE, TRUE, 2, 'Transmutação'),
(19, 'Aprisionamento', 'Você cria um impedimento mágico para imobilizar uma criatura que você possa ver, dentro do alcance. O alvo deve ser bem sucedido num teste de resistência de Sabedoria ou será vinculado à magia; se ele for bem sucedido, ele será imune a essa magia se você conjura-la novamente. Enquanto estiver sob efeito dessa magia, a criatura não precisará respirar, comer ou beber e não envelhece. Magias de adivinhação não podem localizar ou perceber o alvo. Quando você conjura essa magia, você escolhe uma das seguintes formas de aprisionamento. Enterrar. O alvo é sepultado bem fundo na terra em uma esfera de energia mágica que é grande o suficiente para conter o alvo. Nada pode atravessar a esfera e nenhuma criatura pode se teletransportar ou usar viagem plantar para entrar ou sair dela. O componente especial para essa versão da magia é um pequeno globo de mitral. Acorrentar. Pesadas correntes, firmemente presas ao solo, matem o alvo no lugar. O alvo está impedido até a magia acabar e ele não pode se mover ou ser movido por nenhum meio, até lá. O componente especial para essa versão da magia é uma fina corrente de metal precioso. Prisão Cercada. A magia transporta o alvo para dentro de um pequeno semiplano que é protegido contra teletransporte e viagem planar. O semiplano pode ser um labirinto, uma jaula, uma torre ou qualquer estrutura ou área confinada similar, à sua escolha. O componente material especial para essa versão da magia é uma representação em miniatura da prisão, feita de jade. Contenção Reduzida. O alvo é reduzido até o tamanho de 30 centímetros e é aprisionado dentro de uma gema ou objeto similar. A luz pode passar através da gema normalmente (permitindo que o alvo veja o exterior e outras criaturas vejam o interior), mas nada mais pode atravessa-la, mesmo por meios de teletransporte ou viagem planar. A gema não pode ser partida ou quebrada enquanto a magia estiver efetiva. O componente especial para essa versão da magia é uma gema transparente grande, como um coríndon, diamante ou rubi. Torpor. O alvo cai no sono e não pode ser acordado. O componente especial para essa versão da magia consiste em ervas soporíferas raras. Terminando a Magia. Durante a conjuração da magia, em quaisquer das versões, você pode especificar uma condição que irá fazer a magia terminar e libertará o alvo. A condição pode ser o quão especifica ou elaborada quanto você quiser, mas o Mestre deve concordar que a condição é razoável e tem uma probabilidade de acontecer. As condições podem ser baseadas no nome, identidade ou divindade da criatura mas, no mais, devem ser baseadas em ações ou qualidades observáveis e não em valores intangíveis tais como nível, classe e pontos de vida. A magia dissipar magia pode terminar a magia apenas se for conjurada como uma magia de 9° nível, tendo como alvo ou a prisão ou o componente especial usado para cria-la. Você pode usar um componente especial em particular para criar apenas uma prisão por vez. Se você conjurar essa magia novamente usando o mesmo componente, o alvo da primeira conjuração é, imediatamente, liberado do vínculo.', '1 minuto', 9, 'Até ser dissipada', NULL, TRUE, TRUE, TRUE, 9, 'Abjuração'),
(20, 'Arca Secreta de Leomund', 'Você esconde uma arca e todo o conteúdo dela no Plano Etéreo. É necessário que você toque a arca e a réplica em miniatura que serve como componente material para a magia. Ela pode armazenar até 340 litros de matéria não viva.', '1 ação', 1, 'Instantânea', NULL, TRUE, TRUE, TRUE, 4, 'Conjuração'),
(21, 'Área Escorregadia', 'Uma graxa escorregadia recobre uma área de 3 metros quadrados de chão em um ponto dentro do alcance da magia, tornando-o terreno difícil enquanto esta durar. Quando a graxa aparece, cada criatura parada na área precisa ser bem-sucedida em uma salvaguarda de Destreza ou é considerada caída.', '1 ação', 18, '1 minuto', NULL, TRUE, TRUE, TRUE, 1, 'Conjuração'),
(22, 'Arma Elemental', 'Uma arma não-mágica que você tocar se torna uma arma mágica. Escolha um dos tipos de dano a seguir: ácido, elétrico, frio, fogo ou trovejante. Pela duração, a arma tem +1 de bônus nas jogadas de ataque e causa 1d4 de dano extra, do tipo de elemento escolhido, ao atingir. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 5° ou 6° nível, o bônus nas jogadas de ataque aumenta pra +2 e o dano extra aumenta para 2d4. Quando você usar um espaço de magia de 7° nível ou superior, o bônus aumenta para +3 e o dano extra aumenta para 3d4.', '1 ação', 1, 'Concentração, até 1 hora', '1d4', TRUE, TRUE, FALSE, 3, 'Transmutação'),
(23, 'Arma Espiritual', 'Você cria uma arma espectral flutuante, dentro do alcance, que permanece pela duração ou até você conjurar essa magia novamente. Quando você conjura essa magia, você pode realizar um ataque corpo-a-corpo com magia contra uma criatura a 1,5 metro da arma. Se atingir, o alvo sofre dano de energia igual a 1d8 + seu modificador de habilidade de conjuração. Com uma ação bônus, no seu turno, você pode mover a arma até 6 metros e repetir o ataque contra uma criatura a 1,5 metro dela. A arma pode ter a forma que você desejar. Clérigos de divindades associadas com uma arma em particular (como St. Cuthbert é conhecido por sua maça ou Thor por seu martelo) fazem o efeito dessa magia se assemelhar a essa arma. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 3° nível ou superior, o dano aumenta em 1d8 para cada dois níveis do espaço acima do 2°.', '1 ação bônus', 18, '1 minuto', '1d8', TRUE, TRUE, FALSE, 2, 'Evocação'),
(24, 'Arma Mágica', 'Você toca uma arma não-mágica. Até a magia acabar, a arma se torna uma arma mágica com +1 de bônus nas jogadas de ataque e jogadas de dano. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 4° nível ou superior, o bônus aumenta para +2. Quando você usar um espaço de magia de 6° nível ou superior, o bônus aumenta para +3.', '1 ação bônus', 1, 'Concentração, até 1 hora', NULL, TRUE, TRUE, FALSE, 2, 'Transmutação'),
(25, 'Armadura Arcana', 'Você toca uma criatura voluntária que não esteja usando armadura. Uma força mágica protetora circunda-a enquanto a magia durar. A CA base do alvo se torna 13 + o modificador de Destreza dele. A magia termina se o alvo vestir uma armadura ou se você a dispensar com uma ação.', '1 ação', 1, '8 horas', NULL, TRUE, TRUE, TRUE, 1, 'Abjuração'),
(26, 'Armadura de Agathys', 'Uma força magica protetora envolve você, manifestando se como um frio espectral que cobre você e seu equipamento. Você ganha 5 pontos de vida temporários pela duração. Se uma criatura atingir você com um ataque corpo-a-corpo enquanto estiver com esses pontos de vida, a criatura sofrerá 5 de dano de frio. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 2° nível ou superior, tanto os pontos de vida temporários quanto o dano de frio aumentam em 5 para cada nível do espaço acima do 1°.', '1 ação', 0, '1 hora', '5', TRUE, TRUE, TRUE, 1, 'Abjuração'),
(27, 'ArromBAR', 'Escolha um objeto à sua vista e no alcance da magia. O objeto pode ser uma porta, uma caixa, um baú, um par de algemas, um cadeado ou outro objeto que contenha um meio mundano ou mágico que impeça o acesso. Um alvo que seja mantido fechado por uma fechadura mundana ou que esteja emperrado ou obstruído torna-se destrancado, desemperrado ou desobstruído. Se o objeto possui várias fechaduras, apenas uma delas é destrancada. Ao conjurar a magia, um estrondo, audível a até 90 metros, emana do objeto escolhido como alvo.', '1 ação', 18, 'Instantânea', NULL, TRUE, FALSE, FALSE, 2, 'Transmutação'),
(28, 'Assassino Fantasmagórico', 'Você mexe com os pesadelos de uma criatura que você possa ver, dentro do alcance, e cria uma manifestação ilusória dos seus medos mais profundos, visível apenas para a criatura. O alvo deve realizar um teste de resistência de Sabedoria. Se falhar na resistência, ele ficará amedrontado pela duração. No final de cada turno do alvo, antes da magia acabar, ele deve ser bem sucedido num teste de resistência de Sabedoria ou sofrerá 4d10 de dano psíquico. Se passar na resistência, a magia acaba. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 5° nível ou superior, o dano aumenta em 1d10 para cada nível do espaço acima do 4°.', '1 ação', 36, 'Concentração, até 1 minuto', '4d10', TRUE, TRUE, FALSE, 4, 'Ilusão'),
(29, 'Ataque Certeiro', 'Você aponta o seu dedo para um alvo no alcance. Sua magia garante uma leve intuição das defesas do alvo. Em seu próximo turno, você ganha vantagem em sua primeira jogada de ataque contra o alvo, desde que a magia não tenha terminado.', '1 ação', 9, 'Concentração, até 1 rodada', NULL, FALSE, TRUE, FALSE, 0, 'Adivinhação'),
(30, 'Ataque Visual', 'Pela duração da magia, seus olhos tornam-se manchas vazias imbuídas com poder terrível. Uma criatura, à sua escolha, a até de 18 metros de você que você puder ver, deve ser bem sucedida num teste de resistência de Sabedoria ou será afetada por um dos efeitos a seguir, à sua escolha, pela duração. A cada um dos seus turnos, até a magia acabar, você pode usar sua ação para afetar outra criatura, mas não pode afetar uma criatura novamente se ela tiver sido bem sucedida no teste de resistência contra essa conjuração de ataque visual. Adormecer. O alvo cai inconsciente. Ele acorda se sofrer qualquer dano ou se outra criatura usar sua ação para sacudir o adormecido até acordá-lo. Apavorar. O alvo está amedrontado. Em cada um dos turnos dele, a criatura amedrontada deve realizar a ação de Disparada e se mover para longe de você pela rota segura mais curta disponível, a não ser que não haja lugar para se mover. Se o alvo se mover para um local a, pelo menos, 18 metros de distância de você onde ela não possa mais te ver, esse efeito termina. Adoecer. O alvo tem desvantagem nas jogadas de ataque e testes de habilidade. No final de cada um dos turnos dele, ele pode realizar outro teste de resistência de Sabedoria. Se for bem sucedido, o efeito termina.', '1 ação', 0, 'Concentração, até 1 minuto', NULL, TRUE, TRUE, FALSE, 6, 'Necromancia'),
(31, 'Augúrio', 'Ao lançar varetas incrustadas com pedras preciosas, jogar ossos de dragão, dispor cartas ornamentadas ou empregar alguma outra ferramenta de adivinhação, você recebe um presságio de uma entidade de outro mundo sobre os resultados de um determinado curso de ação que você planeja tomar dentro dos próximos 30 minutos. O DM escolhe entre os seguintes presságios possíveis: Prosperidade, para bons resultados; Infortúnio, para maus resultados; Prosperidade e Infortúnio, para resultados bons e maus; ou Nada, para resultados que não são especialmente bons ou maus.', '1 minuto', 0, 'Instantânea', NULL, TRUE, TRUE, TRUE, 2, 'Adivinhação'),
(32, 'Aumentar/Reduzir', 'Você faz com que uma criatura ou um objeto, à sua vista e dentro do alcance da magia, fique maior ou menor enquanto a magia durar. Escolha uma criatura ou um objeto que não esteja sendo usado ou carregado. Se o alvo não for voluntário, ele pode fazer uma salvaguarda de Constituição — em caso de sucesso, a magia não surte efeito. Se o alvo for uma criatura, tudo o que estiver usando e carregando muda de tamanho junto com ela.', '1 ação', 9, 'Concentração, até 1 minuto', '1d4', TRUE, TRUE, TRUE, 2, 'Transmutação'),
(33, 'Aura de Pureza', 'Uma aura de energia purificante se irradia de você em um raio de 9 metros. Enquanto a magia durar, a aura, centrada em você, move-se para onde quer que você vá. Cada criatura não hostil na área (incluindo você) não pode ficar doente, tem resistência a dano venenoso e ganha vantagem em salvaguardas contra as condições amedrontado, atordoado, cego, enfeitiçado, envenenado, paralisado e surdo.', '1 ação', 0, 'Concentração, até 10 minutos', NULL, TRUE, FALSE, FALSE, 4, 'Abjuração'),
(34, 'Aura de Vida', 'Energia de prevenção vital irradia de você em uma aura com 9 metros de raio. Até a magia acabar, a aura se move mantendo-se centrada em você. Todas as criaturas não hostis na aura (incluindo você) tem resistência a dano necrótico e seu máximo de pontos de vida não pode ser reduzido. Além disso, uma criatura viva não-hostil, recupera 1 ponto de vida quando começa seu turno na aura com 0 pontos de vida.', '1 ação', 0, 'Concentração, até 10 minutos', NULL, TRUE, FALSE, FALSE, 4, 'Abjuração'),
(35, 'Aura de Vitalidade', 'Uma aura de energia curativa se irradia de você em um raio de 9 metros. Enquanto a magia durar, a aura, centrada em você, move-se para onde quer que você vá. Você pode usar uma ação bônus para fazer com que uma criatura dentro da aura (incluindo você) recupere 2d6 pontos de vida.', '1 ação', 0, 'Concentração, até 1 minuto', NULL, TRUE, FALSE, FALSE, 3, 'Evocação'),
(36, 'Aura Mágica de Nystul', 'Você toca uma criatura ou objeto, criando uma ilusão sobre o alvo e fazendo com que magias de adivinhação revelem informações falsas sobre ele.', '1 ação', 1, '24 horas', NULL, TRUE, TRUE, TRUE, 2, 'Ilusão'),
(37, 'Aura Sagrada', 'Luz divina emana de você e adere em uma aureola suave num raio de 9 metros, em volta de você. As criaturas de sua escolha, no raio, quando você conjurar essa magia, emitem penumbra num raio de 1,5 metro e tem vantagem em todos os testes de resistência e as outras criaturas tem desvantagem nas jogadas de ataque contra elas, até a magia acabar. Além disso, quando um corruptor ou morto-vivo atingir uma criatura afetada com um ataque corpo-a-corpo, a aura lampeja com luz plena. O atacante deve ser bem sucedido num teste de resistência de Constituição ou ficara cego até a magia acabar.', '1 ação', 0, 'Concentração, até 1 minuto', NULL, TRUE, TRUE, TRUE, 8, 'Abjuração'),
(38, 'Auxílio Divino', 'Sua oração o fortalece com o resplendor divino. Enquanto a magia durar, seus ataques com armas causam 1d4 pontos de dano radiante adicional em caso de acerto.', '1 ação bônus', 0, 'Concentração, até 1 minuto', '1d4', TRUE, TRUE, FALSE, 1, 'Evocação'),
(39, 'Banimento', 'Você tenta enviar uma criatura que você pode ver dentro do alcance, para outro plano de existência. O alvo deve ser bem sucedido num teste de resistência de Carisma ou será banido. Se o alvo for nativo do plano de existência que você está, você bane o alvo para um semiplano inofensivo. Enquanto estiver lá, a criatura estará incapacitada. Ela permanece lá até a magia acabar, a partir desse ponto, o alvo reaparece no espaço em que ela deixou ou no espaço desocupado mais próximo, se o espaço dela estiver ocupado. Se o alvo for nativo de um plano de existência diferente do que você está, o alvo é banido em um lampejo sutil, retornando para o seu plano natal. Se a magia acabar antes de 1 minuto se passar, o alvo reaparece no lugar em que estava ou no espaço desocupado mais próximo, se o espaço dela estiver ocupado. Do contrário, o alvo não retorna. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 5° nível ou superior, você pode afetar uma criatura adicional para cada nível do espaço acima do 4°.', '1 ação', 9, 'Concentração, até 1 minuto', NULL, TRUE, TRUE, TRUE, 4, 'Abjuração'),
(40, 'Banquete de Heróis', 'Você faz surgir um grande banquete, incluindo comida e bebida magníficas. O banquete leva 1 hora para ser consumido e desaparece no final desse tempo; os efeitos benéficos não aparecem até que essa hora se passe. Até doze outras criaturas podem partilhar o banquete. Uma criatura que partilhe do banquete é curada de todas as doenças e envenenamentos, torna-se imune a veneno e a ficar amedrontada, e faz todas as salvaguardas de Sabedoria com vantagem. O valor dos pontos de vida máximos dela também aumenta em 2d10, ganhando esse mesmo número em pontos de vida. Estes benefícios duram 24 horas.', '10 minutos', 9, 'Instantânea', NULL, TRUE, TRUE, TRUE, 6, 'Conjuração'),
(41, 'Barreira de Lâminas', 'Você cria uma barreira vertical de lâminas rodopiantes e afiadas feitas de energia mágica. A barreira aparece dentro do alcance da magia e permanece enquanto a magia durar. Você pode fazer uma barreira reta de até 30 metros de comprimento, 6 metros de altura e 1,5 metro de espessura, ou uma barreira circular de até 18 metros de diâmetro, 6 metros de altura e 1,5 metro de espessura. A barreira impede uma criatura afetada por ela de ultrapassá-la completa ou parcialmente, embora seja possível conjurar magias ou atacar através dela com armas de alcance estendido.', '1 ação', 24, 'Concentração, até 10 minutos', '6d10', TRUE, TRUE, FALSE, 6, 'Evocação'),
(42, 'Bênção', 'Você abençoa até três criaturas, à sua escolha, dentro do alcance. Sempre que um alvo realizar uma jogada de ataque ou teste de resistência antes da magia acabar, o alvo pode jogar um d4 e adicionar o valor jogado ao ataque ou teste de resistência. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 2° nível ou superior, você pode afetar uma criatura adicional para cada nível do espaço acima do 1°.', '1 ação', 9, 'Concentração, até 1 minuto', NULL, TRUE, TRUE, TRUE, 1, 'Encantamento'),
(43, 'Boca Encantada', 'Você implanta uma mensagem em um objeto que esteja no alcance da magia. Essa mensagem é revelada quando uma circunstância de disparo ocorrer. Escolha um objeto à sua vista e que não esteja sendo usado ou carregado por outra criatura. Fale, então, a mensagem, que deve ter 25 palavras ou menos, embora ela possa ser emitida ao longo de um período de até 10 minutos. Quando a circunstância de disparo ocorrer, uma boca encantada aparece no objeto e recita a mensagem com a sua voz e no mesmo volume que você falou.', '1 minuto', 9, 'Até ser dissipada', NULL, TRUE, TRUE, TRUE, 2, 'Ilusão'),
(44, 'Bola de Fogo', 'Um veio brilhante lampeja na ponta do seu dedo em direção a um ponto que você escolher, dentro do alcance, e então eclode com um estampido baixo, explodindo em chamas. Cada criatura em uma esfera de 6 metros de raio, centrada no ponto, deve realizar um teste de resistência de Destreza. Um alvo sofre 8d6 de dano de fogo se falhar na resistência, ou metade desse dano se obtiver sucesso. O fogo se espalha, dobrando esquinas. Ele incendeia objetos inflamáveis na área que não estejam sendo vestidos ou carregados. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 4° nível ou superior, o dano aumenta em 1d6 para cada nível do espaço acima do 3°.', '1 ação', 45, 'Instantânea', '8d6', TRUE, TRUE, TRUE, 3, 'Evocação'),
(45, 'Bola de Fogo Controlável', 'Um feixe de luz amarelada é disparado da ponta do seu dedo, então se condensa e aguarda no ponto escolhido, dentro do alcance, como uma conta brilhante, pela duração. Quando a magia termina, seja por sua concentração ter sido interrompida ou por você ter decidido termina-la, a conta eclode com um estampido baixo, explodindo em chamas que se espalhando, dobrando esquinas. Cada criatura numa esfera, com 6 metros de raio, centrada na conta, deve realizar um teste de resistência de Destreza. Uma criatura sofre dano igual ao total de dano acumulado se falhar na resistência, ou metade do total se obtiver sucesso. O dano base da magia é 12d6. Se até o final do seu turno, a conta ainda não tiver sido detonada, o dano aumenta em 1d6. Se a conta brilhante for tocada antes do intervalo expirar, a criatura que a tocou deve realizar um teste de resistência de Destreza. Se falhar na resistência, a magia termina imediatamente, fazendo a conta explodir em chamas. Se obtiver sucesso na resistência, a criatura pode arremessar a conta a até 12 metros. Quando ela atinge uma criatura ou objeto solido, a magia termina e a conta explode. O fogo danifica objetos na área e incendeia objetos inflamáveis que não estejam sendo vestidos ou carregados. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 8° nível ou superior, o dano base aumenta e 1d6 para cada nível do espaço acima do 7°.', '1 ação', 45, 'Concentração, até 1 minuto', '12d6', TRUE, TRUE, TRUE, 7, 'Evocação'),
(46, 'Bom Fruto', 'Até dez frutos aparecem na sua mão, tornando-se magicamente infundidos. Uma criatura pode usar uma ação para comer um fruto. Comer um fruto restaura 1 ponto de vida, além de fornecer nutrição suficiente para sustentar uma criatura por um dia. Os frutos perdem sua potência se não tiverem sido consumidos após 24 horas da conjuração desta magia.', '1 ação', 1, 'Instantânea', NULL, TRUE, TRUE, TRUE, 1, 'Transmutação'),
(47, 'Bordão Místico', 'A madeira de uma clava ou cajado que você está segurando é imbuída com o poder da natureza. Enquanto a magia durar, seu atributo de conjuração pode ser usado no lugar da Força para as jogadas de ataque e dano usando aquela arma, e o dado de dano passa a ser 1d8. A arma também se torna mágica, se já não o for. A magia termina se for conjurada novamente ou se você se desfizer da arma.', '1 ação bônus', 1, '1 minuto', '1d8', TRUE, TRUE, TRUE, 0, 'Transmutação'),
(48, 'Braços de Hadar', 'Você invoca o poder de Hadar, o Faminto Sombrio. Tentáculos de energia negra brotam de você e golpeiam todas as criaturas a até 3 metros de você. Cada criatura na área deve realizar um teste de resistência de Força. Se falhar, o alvo sofre 2d6 de dano necrótico e não pode fazer reações até o próximo turno dela. Em um sucesso, uma criatura sofre metade do dano e não sofre qualquer outro efeito. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 2° nível ou superior, o dano aumenta em 1d6 para cada nível do espaço acima do 1°.', '1 ação', 0, 'Instantânea', '2d6', TRUE, TRUE, FALSE, 1, 'Conjuração'),
(49, 'Bruxaria', 'Você coloca uma maldição em uma criatura que você possa ver, dentro do alcance. Até a magia acabar, você causa 1d6 de dano necrótico extra no alvo sempre que atingi-lo com um ataque. Além disso, escolha uma habilidade quando você conjurar a magia. O alvo tem desvantagem em testes de habilidade feitos com a habilidade escolhida. Se o alvo cair a 0 pontos de vida antes da magia acabar, você pode usar uma ação bônus, em um turno subsequente, para amaldiçoar outra criatura. Uma magia remover maldição conjurada no alvo acaba com a magia prematuramente. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 3° ou 4° nível, você poderá manter sua concentração na magia por até 8 horas. Quando você usar um espaço de magia de 5° nível ou superior, você poderá manter sua concentração na magia por até 24 horas.', '1 ação bônus', 18, 'Concentração, até 1 hora', '1d6', TRUE, TRUE, TRUE, 1, 'Encantamento'),
(50, 'Caminhar em Árvores', 'Você adquire a habilidade de entrar em uma árvore e se mover de dentro dela para dentro de outra árvore de mesmo tipo à até 150 metros. Ambas as árvores devem estar vivas e ter, pelo menos, o mesmo tamanho que você. Você deve usar 1,5 metro de deslocamento para entrar numa árvore. Você, instantaneamente, sabe a localização de todas as outras árvores de mesmo tipo à 150 metros e, como parte do movimento usado para entrar na árvore, pode tanto passar por uma dessas árvores quanto sair da árvore em que você está. Você aparece no espaço que você quiser a 1,5 metro da árvore destino, usando outro movimento de 1,5 metro. Se você não tiver movimento restante, você aparece a 1,5 metro da árvore que você terminou seu movimento. Você pode usar esse habilidade de transporte uma vez por rodada pela duração. Você deve terminar cada turno fora da árvore.', '1 ação', 0, 'Concentração, até 1 minuto', NULL, TRUE, TRUE, FALSE, 5, 'Conjuração'),
(51, 'Caminhar no Vento', 'Você e até dez criaturas voluntária que você possa ver, dentro do alcance, assumem uma forma gasosa pela duração, parecidas com pedaços de nuvem. Enquanto estiver na forma de nuvem, uma criatura tem deslocamento de voo de 90 metros e tem resistência a dano de concussão, cortante e perfurante de ataques não mágicos. As únicas ações que uma criatura pode realizar nessa forma são a ação de Disparada ou para reverter a sua forma normal. Reverter leva 1 minuto, período pelo qual a criatura estará incapacitada e não poderá se mover. Até a magia acabar, uma criatura pode reverter para a forma de nuvem, o que também requer a transformação de 1 minuto. Se uma criatura estiver na forma de nuvem e voando quando o efeito acabar, a criatura descerá a 18 metros por rodada por 1 minuto, até aterrissar na solo, o que é feito com segurança. Se ela não puder aterrissar em 1 minuto, a criatura cairá a distância restante.', '1 minuto', 9, '8 horas', NULL, TRUE, TRUE, TRUE, 6, 'Transmutação'),
(52, 'Campo Antimagia', 'Uma esfera invisível, de 3 metros de raio, de antimagia envolve você. Essa área é separada da energia mágica que se espalha pelo multiverso. Dentro da esfera, magias não podem ser conjuradas, criaturas invocadas desaparecem e, até mesmo itens mágicos, se tornam mundanos. Até o fim da magia, a esfera se move com você, centrada em você. Magias e outros efeitos mágicos, exceto os criados por artefatos ou divindades, são suprimidos na esfera e não podem adentra-la. Um espaço gasto para conjurar uma magia suprimida é consumido. Enquanto o efeito estiver suprimido, ela não funciona, mas o tempo que ela permanecer suprimida é descontado da sua duração. Efeitos de Alvo. Magias e outros efeitos mágicos, como mísseis mágicos e enfeitiçar pessoa, que forem usados em uma criatura ou objeto dentro da esfera, não surtem efeito no alvo. Áreas de Magia. A área de outra magia ou efeito mágico, como uma bola de fogo, não se estende para dentro da esfera. Se a esfera sobrepor um área mágica, a parte da área que for coberta pela espera é suprimida. Por exemplo, as chás criadas por uma muralha de fogo serão suprimidas dentro da esfera, criando um abertura na muralha se a sobreposição por grande o suficiente. Magias. Qualquer magia ativa ou outro efeito mágico em uma criatura ou objeto dentro da esfera é suprimido enquanto a criatura ou objeto permanecer dentro dela. Itens Mágicos. As propriedades e poderes de itens mágicos são suprimidas dentro da esfera. Por exemplo, uma espada longa +1 dentro da esfera funciona como uma espada não-mágica. As propriedades e poderes de uma arma mágica são suprimidos se ela for usada contra um alvo dentro da esfera ou empunhada por um atacante dentro da esfera. Se uma arma mágica ou munição mágica deixar a esfera completamente (por exemplo, se você disparar uma flecha mágica ou arremessar uma lança mágica e um alvo fora da esfera), a magia do item deixa de ser suprimida tão logo ele deixe a esfera. Viagem Mágica. Teletransporte e viagem planar não funciona dentro da esfera, tanto se a esfera for o destino quando o ponto de partida para tais viagens mágicas. Um portal para outro lugar, mundo ou plano de existência, assim como um espaço extradimensional aberto, como o criado pela magia truque de corda, é temporariamente fechado enquanto estiver dentro da esfera. Criaturas e Objetos. Uma criatura ou objeto invocado ou criado através de magia, temporariamente desaparece da existência dentro da esfera. Tais criaturas reaparecem instantaneamente quando o espaço ocupado pela criatura não estiver mais dentro da esfera. Dissipar Magia. Magias e efeitos mágicos como dissipar magia, não surtem efeito sob esfera. Da mesma forma, esferas criadas por magias de campo antimagia diferentes não se anulam.', '1 ação', 0, 'Concentração, até 1 hora', NULL, TRUE, TRUE, TRUE, 8, 'Abjuração'),
(53, 'Cão Fiel de Mordenkainen', 'Você conjura um cão de guarda fantasma em um espaço desocupado à sua vista, no alcance da magia, onde ele permanece enquanto a magia durar, até você dispensá-lo com uma ação, ou até você se mover a mais de 30 metros dele. O cão é invisível para todas as criaturas, exceto para você, e não pode ser ferido. Quando uma criatura Pequena ou maior se aproximar a até 9 metros do cão, sem primeiro dizer a senha que você especifica ao conjurar a magia, ele começa a latir alto. No início de cada um de seus turnos, o cão tenta morder uma criatura hostil a você que esteja a até 1,5 metro dele. Se acertar, ele causa 4d8 pontos de dano perfurante.', '1 ação', 9, '8 horas', '4d8', TRUE, TRUE, TRUE, 4, 'Conjuração'),
(54, 'Cativar', 'Você dita uma sequência de palavras dispersivas, fazendo com que criaturas à sua escolha, à sua vista, dentro do alcance da magia e que possam ouvi-lo, façam uma salvaguarda de Sabedoria. Qualquer criatura que não possa ser enfeitiçada é automaticamente bem-sucedida na salvaguarda, e se você ou seus companheiros estiverem combatendo a criatura alvo, ela tem vantagem nesse teste. Se falhar, o alvo tem desvantagem nos testes de Sabedoria (Percepção) para perceber qualquer outra criatura que não seja o conjurador, enquanto a magia durar ou até que o alvo não consiga mais ouvi-lo.', '1 ação', 18, '1 minuto', NULL, TRUE, TRUE, FALSE, 2, 'Encantamento'),
(55, 'Carne para Pedra', 'Você tenta transformar uma criatura que você possa ver, dentro do alcance, em pedra. Se o corpo do alvo for feito de carne, a criatura deve realizar um teste de resistência de Constituição. Em caso de falha, ela ficará impedida, à medida que sua carne começa a endurecer. Se obtiver sucesso, a criatura não é afetada. Uma criatura impedida por essa magia deve realizar outro teste de resistência de Constituição no final de cada um dos turnos dela. Se obtiver sucesso na resistência contra essa magia três vezes, a magia termina. Se ela falhar no teste de resistência três vezes, ela se torna pedra é afetada pela condição petrificado pela duração. Os sucessos e falhas não precisam ser consecutivos; anote ambos os resultados até o alvo acumular três de mesmo tipo. Se a criatura for quebrada fisicamente enquanto petrificada, ela sofre deformidades similares se for revertida ao seu estado original. Se você mantiver sua concentração nessa magia durante toda a duração possível, a criatura é transformada em pedra até o efeito ser removido.', '1 ação', 18, 'Concentração, até 1 minuto', NULL, TRUE, TRUE, TRUE, 6, 'Transmutação'),
(56, 'Cegueira/Surdez', 'Você pode cegar ou ensurdecer um oponente. Escolha uma criatura que você possa ver dentro do alcance para fazer um teste de resistência de Constituição. Se ela falhar, ficará ou cega ou surda (à sua escolha) pela duração. No final de cada um dos turnos dele, o alvo pode realizar um teste de resistência de Constituição. Se obtiver sucesso, a magia termina. Em Níveis Superiores. Se você conjurar essa magia usando um espaço de magia de 3° nível ou superior, você pode afetar uma criatura adicional para cada nível de espaço acima do 2°.', '1 ação', 9, '1 minuto', NULL, TRUE, FALSE, FALSE, 2, 'Necromancia'),
(57, 'Chama Contínua', 'Uma chama, brilhante como uma tocha, surge de um objeto que você toca. O efeito assemelha-se ao de uma chama comum, exceto pelo fato de não emitir calor nem consumir oxigênio. Uma chama contínua pode ser coberta ou escondida, mas não apagada ou abafada.', '1 ação', 1, 'Até ser dissipada', NULL, TRUE, TRUE, TRUE, 2, 'Evocação'),
(58, 'Chama Sagrada', 'Uma irradiação instantânea semelhante a uma chama irrompe em uma criatura à sua vista, no alcance da magia. O alvo deve fazer uma salvaguarda de Destreza. Se falhar, sofre 1d8 pontos de dano radiante. O alvo não tem benefício algum de cobertura para essa salvaguarda. O dano desta magia aumenta em 1d8 quando você alcança o 5º nível (2d8), o 11º nível (3d8) e o 17º nível (4d8).', '1 ação', 18, 'Instantânea', '1d8', TRUE, TRUE, FALSE, 0, 'Evocação'),
(59, 'Chicote de Espinhos', 'Você cria um longo chicote parecido com uma videira e coberto de espinhos, que golpeia uma criatura no alcance ao seu comando. Faça um ataque mágico corpo a corpo contra o alvo. Se o ataque acertar, a criatura sofre 1d6 pontos de dano perfurante; e se a criatura for Grande ou menor, você a puxa até 3 metros mais para perto de você. O dano desta magia aumenta em 1d6 quando você alcança o 5° nível (2d6), o 11° nível (3d6) e o 17° nível (4d6).', '1 ação', 9, 'Instantânea', '1d6', TRUE, TRUE, TRUE, 0, 'Transmutação'),
(60, 'Chuva de Meteoros', 'Esferas em chamas, feitas de pura brasa, atingem o solo em quatro pontos diferentes à sua vista e dentro do alcance da magia. Cada criatura em um raio de 12 metros, centrado em cada ponto escolhido, precisa fazer uma salvaguarda de Destreza. Se falhar, sofre 20d6 pontos de dano ígneo e 20d6 pontos de dano contundente, ou metade do dano em caso de sucesso. Uma criatura na área afetada por mais de uma esfera sofre os efeitos de apenas uma.', '1 ação', 1500, 'Instantânea', '40d6', TRUE, TRUE, FALSE, 9, 'Evocação'),
(61, 'Círculo da Morte', 'Uma esfera de energia negativa ondula em um raio de 18 metros de um ponto ao alcance. Cada criatura na área deve realizar um teste de resistência de Constituição. Um alvo sofre 8d6 de dano necrótico se falhar no seu teste de resistência, ou metade desse dano se passar. Em Níveis Superiores. Se você conjurar essa magia usando um espaço de magia de 7° nível ou superior, o dano aumenta em 2d6 para cada nível do espaço acima do 6°.', '1 ação', 45, 'Instantânea', '8d6', TRUE, TRUE, TRUE, 6, 'Necromancia'),
(62, 'Círculo de Poder', 'Uma energia divina irradia de você, distorcendo e difundindo energia mágica dentro de uma área com 9 metros de raio. Enquanto a magia durar, a esfera, centrada em você, move-se para onde quer que você vá. Cada criatura amigável na área (incluindo você) tem vantagem nas salvaguardas contra magias e outros efeitos mágicos, e não sofre dano algum caso seja bem-sucedida em uma salvaguarda que permita reduzir o dano à metade.', '1 ação', 0, 'Concentração, até 10 minutos', NULL, TRUE, FALSE, FALSE, 5, 'Abjuração'),
(63, 'Círculo de Teletransporte', 'À medida que você conjura essa magia, você desenha um círculo de 3 metros de diâmetro no chão, inscrevendo selos que conectam sua localização a um círculo de teletransporte permanente, à sua escolha, cuja sequência de selos você conheça e esteja no mesmo plano de existência que você. Um portal cintilante se abre dentro do círculo que você desenhou e permanece aberto até o final do seu próximo turno. Qualquer criatura que entrar no portal, instantaneamente, aparecerá a 1,5 metro do círculo de destino ou no espaço desocupado mais próximo, se o espaço estiver ocupado. Muitos templos principais, guildas e outros locais importantes possuem círculos de teletransporte permanentes inscritos em algum lugar dos seus confins. Cada círculo desse inclui uma sequência única de selos – uma sequência de runas mágicas dispostas em um padrão específico. Quando você adquire a capacidade de conjurar essa magia pela primeira vez, você aprende a sequência de selos de dois destinos no Plano Material, determinadas pelo Mestre. Você pode aprender sequências de selos adicionais durante suas aventuras. Você pode consignar uma nova sequência de selos a memória após estuda-la por 1 minuto. Você pode criar um círculo de teletransporte permanente ao conjurar essa magia no mesmo local a cada dia por um ano. Você não precisa usar o círculo para se teletransportar quando você conjurar a magia desse modo.', '1 minuto', 3, '1 rodada', NULL, TRUE, FALSE, TRUE, 5, 'Conjuração'),
(64, 'Círculo Mágico', 'Você cria um cilindro de energia mágica de 3 metros de raio por 6 metros de altura, centrado num ponto no solo que você possa ver, dentro do alcance. Runas brilhantes aparecem toda vez que o cilindro toca o chão ou outra superfície. Escolha um ou mais dos tipos de criaturas seguintes: celestiais, corruptores, elementais, fadas ou mortos-vivos. O círculo afeta uma criatura do tipo escolhido das seguintes maneiras:  A criatura não consegue entrar no cilindro voluntariamente por meios não-mágicos. Se a criatura tentar usar teletransporte ou viagem interplanar para fazê-lo, ela deve, primeiro, ser bem sucedida num teste de resistência de Carisma.  A criatura tem desvantagem nas jogadas de ataque contra alvos dentro do cilindro.  Alvos dentro do cilindro não podem ser enfeitiçados, amedrontados ou possuídos pela criatura. Quando você conjurar essa magia, você pode decidir que a mágica dela opere na direção reversa, prevenindo que uma criatura de um tipo especifico saia do cilindro e protegendo os alvos fora dele. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 4° nível ou superior, a duração aumenta em 1 hora para cada nível do espaço acima do 3°.', '1 minuto', 3, '1 hora', NULL, TRUE, TRUE, TRUE, 3, 'Abjuração'),
(65, 'Clarividência', 'Você cria um sensor invisível dentro do alcance da magia, em um local que já tenha visto antes ou em uma localização óbvia que possa descrever. O sensor permanece no local enquanto a magia durar, não podendo ser atacado nem ser alvo de qualquer outro tipo de interação. Ao conjurar a magia, você escolhe ver ou ouvir. Você pode usar o sentido escolhido por meio do sensor como se estivesse no espaço ocupado por ele, e com uma ação pode alternar entre ver e ouvir.', '10 minutos', 1500, 'Concentração, até 10 minutos', NULL, TRUE, TRUE, TRUE, 3, 'Adivinhação'),
(66, 'Clone', 'Essa magia produz uma duplicata inerte de uma criatura viva como uma garantia contra a morte. Esse clone é formado dentro de um receptáculo selado e cresce ao seu tamanho total, atingindo a maturidade após 120 dias; Você também pode escolher que o clone seja uma versão mais jovem da mesma criatura. Ele permanece inerte e dura indefinidamente, enquanto seu receptáculo permanecer intocado. A qualquer momento, após o clone amadurecer, se a criatura original morrer, sua alma é transferida para o clone, considerando que a alma está livre e deseje retornar. O clone é fisicamente idêntico ao original e tem a mesma personalidade, memórias e habilidades, mas não possui qualquer equipamento do original. O físico da criatura original permanece, se ainda existir, se tornando inerte e não podendo, consequentemente, ser trazido de volta à vida, já que a alma da criatura está em outro lugar.', '1 hora', 1, 'Instantânea', NULL, TRUE, TRUE, TRUE, 8, 'Necromancia'),
(67, 'Coluna de Chamas', 'Uma coluna vertical de fogo divino emerge de baixo para os céus, no local que você especificar. Cada criatura num cilindro de 3 metros de raio por 12 metros de altura, centrado num ponto dentro do alcance, deve realizar um teste de resistência de Destreza. Uma criatura sofre 4d6 de dano de fogo e 4d6 de dano radiante se falhar na resistência, ou metade desse dano se obtiver sucesso. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 6° nível ou superior, o dano de fogo ou o dano radiante (à sua escolha) aumenta em 1d6 por nível do espaço acima do 5°.', '1 ação', 18, 'Instantânea', '8d6', TRUE, TRUE, TRUE, 5, 'Evocação'),
(68, 'Comando', 'Você pronuncia uma palavra de comando para uma criatura que você possa ver dentro do alcance. O alvo deve ser bem sucedido num teste de resistência de Sabedoria ou seguirá seu comando no próximo turno dele. A magia não tem efeito se o alvo for um morto-vivo, se ele não entender seu idioma ou se o comando for diretamente nocivo a ele. Alguns comandos típicos e seus efeitos a seguir. Você pode proferir um comando diferente dos descritos aqui. Se o fizer, o Mestre descreve como o alvo reage. Se o alvo não puder cumprir o comando, a magia termina. Aproxime-se. O alvo se move para próximo de você o máximo que puder na rota mais direta, terminando seu turno, se ele se mover a até 1,5 metro de você. Largue. O alvo larga o que quer que ele esteja segurando, e termina seu turno. Fuja. O alvo gasta seu turno se movendo para longe de você da forma mais rápida que puder. Deite-se. O alvo deita-se no chão e então, termina seu turno. Parado. O alvo não se move e não realiza nenhuma ação. Uma criatura voadora continua no alto, considerando que ela seja capaz de fazê-lo. Se ela tiver que se mover para continuar no alto, ela voa a mínima distância necessária para permanecer no ar. Em Níveis Superiores. Se você conjurar essa magia usando um espaço de magia de 2° nível ou superior, você pode afetar uma criatura adicional para cada nível do espaço acima do 1°. As criaturas devem estar a 9 metros entre si para serem afetadas.', '1 ação', 18, '1 rodada', NULL, TRUE, FALSE, FALSE, 1, 'Encantamento'),
(69, 'Compreender Idiomas', 'Enquanto a magia durar, você entende o significado literal de qualquer idioma falado que ouvir. Você também entende qualquer idioma escrito que veja, mas deve tocar a superfície sobre a qual as palavras estão escritas — demora cerca de 1 minuto para ler uma página de texto. Esta magia não decodifica mensagens secretas em um texto ou um glifo, como um selo arcano, que não faça parte de um idioma escrito.', '1 ação', 0, '1 hora', NULL, TRUE, TRUE, TRUE, 1, 'Adivinhação'),
(70, 'Compulsão', 'Criaturas, à sua escolha, que você puder ver dentro do alcance e que puderem ouvir você, devem realizar um teste de resistência de Sabedoria. Um alvo passa automaticamente nesse teste de resistência se ele não puder ser enfeitiçado. Se falhar no teste, um alvo é afetado por essa magia. Até a magia acabar, você pode usar uma ação bônus em cada um dos seus turnos, para designar uma direção horizontal a você. Cada criatura afetada deve se mover, da melhor forma possível, para essa direção no próximo turno dela. Ela pode realizar sua ação antes de se mover. Depois de se mover dessa forma, ela pode realizar outra resistência de Sabedoria para tentar acabar com o efeito. Um alvo não é obrigado a se mover em direção de um perigo obviamente mortal, como uma fogueira ou abismo, mas ele vai provocar ataques de oportunidade por se mover na direção designada.', '1 ação', 9, 'Concentração, até 1 minuto', NULL, TRUE, TRUE, FALSE, 4, 'Encantamento'),
(71, 'Comunhão', 'Você contata sua divindade ou um representante divino e faz até três perguntas que podem ser respondidas com um sim ou não. Você deve fazer suas perguntas antes da magia terminar. Você recebe uma resposta correta para cada pergunta. Seres divinos não são necessariamente oniscientes, portanto, você pode receber “incerto” como uma resposta se uma pergunta que diga respeito a uma informação além do conhecimento da divindade. Em caso de uma resposta de única palavra puder levar ao engano ou contrariar os interesses da divindade, o Mestre pode oferecer uma frase curta como resposta, no lugar. Se você conjurar essa magia duas ou mais vezes antes de terminar um descanso longo, existe uma chance cumulativa de 25 por cento de cada conjuração, depois da primeira que você fez, ter um resultado aleatório. O Mestre faz essa jogada secretamente.', '1 minuto', 0, '1 minuto', NULL, TRUE, TRUE, TRUE, 5, 'Adivinhação'),
(72, 'Comunhão com a Natureza', 'Você, momentaneamente, se torna uno com a natureza e ganha conhecimento do território ao seu redor. Ao ar livre, a magia lhe oferece conhecimento do terreno a até 4,5 quilômetros de você. Em cavernas e outros formações subterrâneas naturais, o raio é limitado a 150 metros. A magia não funciona onde a natureza foi substituída por construções, como em masmorras ou cidades. Você, instantaneamente, adquire conhecimento de até três fatos, à sua escolha, sobre qualquer dos assuntos a seguir, relacionados a área:  Terrenos e corpos de água  Plantas, minérios, animais e povo predominante  Celestiais, fadas, corruptores, elementais ou mortos vivos mais poderosos  Influência de outros planos de existência  Construções Por exemplo, você poderia determinar a localização de um morto-vivo poderoso na área, a localização da maior fonte de água potável e a localização de quaisquer cidades próximas.', '1 minuto', 0, 'Instantânea', NULL, TRUE, TRUE, FALSE, 5, 'Adivinhação'),
(73, 'Cone de Frio', 'Uma explosão de ar gelado irrompe das suas mãos. Cada criatura dentro do cone de 18 metros, deve realizar um teste de resistência de Constituição. Uma criatura sofre 8d8 de dano de frio se falhar na resistência, ou metade desse dano se passar. Uma criatura morta por essa magia se torna uma estátua congelada até derreter. Em Níveis Superiores. Se você conjurar essa magia usando um espaço de magia de 6° nível ou superior, o dano aumenta em 1d8 para cada nível do espaço acima do 5°.', '1 ação', 0, 'Instantânea', '8d8', TRUE, TRUE, TRUE, 5, 'Evocação'),
(74, 'Confusão', 'Essa magia ataca e embaralha as mentes das criaturas, gerando delírios e provocando ações descontroladas. Cada criatura em uma esfera com 3 metros de raio, centrada num ponto, à sua escolha, dentro do alcance, deve ser bem sucedida num teste de resistência de Sabedoria, quando você conjurar essa magia ou for afetada por ela. Um alvo afetado não pode realizar reações e deve rolar um d10 no início de cada um dos seus turnos para determinar seu comportamento nesse turno. d10 Comportamento A criatura usa todo seu deslocamento para se mover em uma direção aleatória. Para determinar a direção, role um d8 e atribua uma direção a cada face do dado. A criatura não realiza uma ação nesse turno. 2–6 A criatura não se move ou realiza ações nesse turno. 7–8 A criatura usa sua ação para realizar um ataque corpo-a corpo contra uma criatura, determinada aleatoriamente, ao seu alcance. Se não houver criaturas dentro do alcance, a criatura não faz nada nesse turno. 9–10 A criatura pode agir e se mover normalmente. Ao final de cada um dos seus turnos, um alvo afetado pode realizar um teste de resistência de Sabedoria. Se for bem sucedido, esse efeito acaba nesse alvo. Em Níveis Superiores. Se você conjurar essa magia usando um espaço de magia de 5° nível ou superior, o raio da esfera aumenta em 1,5 metro para cada nível do espaço acima do 4°.', '1 ação', 27, 'Concentração, até 1 minuto', NULL, TRUE, TRUE, TRUE, 4, 'Encantamento'),
(75, 'Conhecimento Lendário', 'Nomeie ou descreva uma pessoa, local ou objeto. A magia traz a sua mente um breve resumo do conhecimento significativo sobre a coisa que você nomeou. O conhecimento deve consistir em contos atuais, histórias esquecidas ou, até mesmo, conhecimento secreto que nunca foi amplamente divulgado. Se a coisa que você nomeou não for de importância lendária, você não recebe qualquer informação sofre ela. Quanto mais informação você possuir sobre a coisa, mais precisa e detalhada será a informação que você receberá. A informação que você aprende é precisa, mas pode ser redigida em linguagem figurada. Por exemplo, se você possuir um misterioso machado mágico na mão, a magia pode proporcionar essa informação: “Ai do malfeitor cuja mão toca o machado, até mesmo seu cabo corta a mão dos malignos. Só um verdadeiro Filho da Pedra, adorador e adorado de Moradin, pode despertar os verdadeiros poderes do machado e apenas com a palavra sagrada Rudnogg nos lábios.”', '10 minutos', 0, 'Instantânea', NULL, TRUE, TRUE, TRUE, 5, 'Adivinhação'),
(76, 'Conjurar Animais', 'Você invoca espíritos feéricos, que assumem formas de bestas, que aparecem em espaços desocupados, que você possa ver dentro do alcance. Escolha uma das opções a seguir para aparecer:  Uma besta de nível de desafio 2 ou inferior  Duas bestas de nível de desafio 1 ou inferior  Quatro bestas de nível de desafio 1/2 ou inferior  Oito bestas de nível de desafio 1/4 ou inferior Cada besta é também considerada uma fada e desaparece quando cair a 0 pontos de vida ou quando a magia acabar. As criaturas invocadas são amigáveis a você e a seus companheiros. Role a iniciativa para as criaturas invocadas como um grupo, que age no seu próprio turno. Eles obedecem a quaisquer comandos verbais que você emitir (não requer uma ação sua). Se você não emitir nenhum comando a elas, elas se defenderão de criaturas hostis, mas no mais, não realizarão nenhuma ação. O Mestre possui as estatísticas das criaturas. Em Níveis Superiores. Se você conjurar essa magia usando certos espaços de magia superiores, você escolhe uma das opções de invocação acima e mais criaturas aparecem: o dobro delas com um espaço de 5° nível, o triplo delas com um espaço de 7° nível e o quadruplo delas com um espaço de 9° nível.', '1 ação', 18, 'Concentração, até 1 hora', NULL, TRUE, TRUE, FALSE, 3, 'Conjuração'),
(77, 'Conjurar Celestial', 'Você invoca um celestial de nível de desafio 4 ou inferior, que aparece num espaço desocupado, que você possa ver dentro do alcance. O celestial desaparece se cair a 0 pontos de vida ou quando a magia acabar. O celestial é amigável a você e a seus companheiros pela duração. Role a iniciativa para o celestial, que age no seu próprio turno. Ele obedece a quaisquer comandos verbais que você emitir (não requer uma ação sua), contanto que não violem sua tendência. Se você não emitir nenhum comando a ele, ele se defenderá de criaturas hostis, mas no mais, não realizará nenhuma ação. O Mestre possui as estatísticas do celestial. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 9° nível, você invoca um celestial de nível de desafio 5 ou inferior.', '1 minuto', 27, 'Concentração, até 1 hora', NULL, TRUE, TRUE, FALSE, 7, 'Conjuração'),
(78, 'Conjurar Elementais Menores', 'Você invoca elementais que aparecem em espaços desocupados, que você possa ver dentro do alcance. Você escolhe uma das opções a seguir para aparecer:  Um elemental de nível de desafio 2 ou inferior  Dois elementais de nível de desafio 1 ou inferior  Quatro elementais de nível de desafio 1/2 ou inferior  Oito elementais de nível de desafio 1/4 ou inferior Um elemental invocado através dessa magia desaparece quando cair a 0 pontos de vida ou quando a magia acabar. As criaturas invocadas são amigáveis a você e a seus companheiros. Role a iniciativa para as criaturas invocadas como um grupo, que age no seu próprio turno. Eles obedecem a quaisquer comandos verbais que você emitir (não requer uma ação sua). Se você não emitir nenhum comando a elas, elas se defenderão de criaturas hostis, mas no mais, não realizarão nenhuma ação. O Mestre possui as estatísticas das criaturas. Em Níveis Superiores. Se você conjurar essa magia usando certos espaços de magia superiores, você escolhe uma das opções de invocação acima e mais criaturas aparecem: o dobro delas com um espaço de 6° nível e o triplo delas com um espaço de 8° nível.', '1 minuto', 27, 'Concentração, até 1 hora', NULL, TRUE, TRUE, FALSE, 4, 'Conjuração'),
(79, 'Conjurar Elemental', 'Você invoca um servo elemental. Escolha uma área de ar, água, fogo ou terra que preencha 3 metros cúbicos, dentro do alcance. Um elemental de nível de desafio 5 ou inferior, adequado a área que você escolheu, aparece em um espaço desocupado a até 3 metros dela. Por exemplo, um elemental do fogo emergiria de uma fogueira e um elemental da terra erguer-se-ia do solo. O elemental desaparece quando cair a 0 pontos de vida ou quando a magia acabar. O elemental é amigável a você e a seus companheiros pela duração. Role a iniciativa para o elemental, que age no seu próprio turno. Ele obedece a quaisquer comandos verbais que você emitir (não requer uma ação sua). Se você não emitir nenhum comando a ele, ele se defenderá de criaturas hostis, mas no mais, não realizará nenhuma ação. Se sua concentração for interrompida, o elemental não desaparece. Ao invés disso, você perde o controle sobre o elemental e ele se torna hostil a você e aos seus companheiros, e irá atacar. Um elemental fora de controle não pode ser dispensado e desaparece 1 hora depois de você ter o invocado.', '1 minuto', 27, 'Concentração, até 1 hora', NULL, TRUE, TRUE, TRUE, 5, 'Conjuração'),
(80, 'Conjurar Fada', 'Você invoca uma criatura feérica de nível de desafio 6 ou inferior ou um espírito feérico que assume a forma de uma besta de nível de desafio 6 ou inferior. Ela aparece num espaço desocupado, que você possa ver dentro do alcance. A criatura feérica desaparece se cair a 0 pontos de vida ou quando a magia acabar. A criatura feérica é amigável a você e a seus companheiros pela duração. Role a iniciativa para a criatura, que age no seu próprio turno. Ela obedece a quaisquer comandos verbais que você emitir (não requer uma ação sua), contanto que não violem sua tendência. Se você não emitir nenhum comando a ela, ela se defenderá de criaturas hostis, mas no mais, não realizará nenhuma ação. Se sua concentração for interrompida, a criatura feérica não desaparece. Ao invés disso, você perde o controle sobre o elemental e ele se torna hostil a você e aos seus companheiros, e irá atacar. Uma criatura feérica fora de controle não pode ser dispensada e desaparece 1 hora depois de você ter a invocado. O Mestre possui as estatísticas da criatura feérica. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 7° nível ou superior, o nível de desafio aumenta em 1 para cada nível do espaço acima do 6°.', '1 minuto', 27, 'Concentração, até 1 hora', NULL, TRUE, TRUE, FALSE, 6, 'Conjuração'),
(81, 'Conjurar Rajada', 'Você arremessa uma arma não-mágica, ou dispara uma munição não-mágica no ar, criando um cone de armas idênticas que disparam adiante e então desaparecem, causando dano a cada criatura no cone.', '1 ação', 0, 'Instantânea', '3d8', TRUE, TRUE, TRUE, 3, 'Conjuração'),
(82, 'Conjurar Saraivada', 'Você dispara uma munição não-mágica de uma arma à distância ou arremessa uma arma não-mágica no ar e escolhe um ponto dentro do alcance. Centenas de duplicatas da munição ou arma caem em uma saraivada vinda de cima e então desaparecem. Cada criatura num cilindro com 12 metros de raio e 6 metros de altura centrado no ponto, deve realizar um teste de resistência de Destreza. Uma criatura sofre 8d8 de dano se falhar na resistência, ou metade desse dano num sucesso. O tipo do dano é o mesmo da munição ou arma.', '1 ação', 45, 'Instantânea', '8d8', TRUE, TRUE, TRUE, 5, 'Conjuração'),
(83, 'Conjurar Seres da Floresta', 'Você invoca criaturas feéricas que aparecem em espaços desocupados, que você possa ver dentro do alcance. Escolha uma das opções a seguir para aparecer:  Uma criatura feérica de nível de desafio 2 ou inferior  Duas criaturas feéricas de nível de desafio 1 ou inferior  Quatro criaturas feéricas de nível de desafio 1/2 ou inferior  Oito criaturas feéricas de nível de desafio 1/4 ou inferior Uma criatura invocado desaparece quando cair a 0 pontos de vida ou quando a magia acabar. As criaturas invocadas são amigáveis a você e a seus companheiros. Role a iniciativa para as criaturas invocadas como um grupo, que age no seu próprio turno. Eles obedecem a quaisquer comandos verbais que você emitir (não requer uma ação sua). Se você não emitir nenhum comando a elas, elas se defenderão de criaturas hostis, mas no mais, não realizarão nenhuma ação. O Mestre possui as estatísticas das criaturas. Em Níveis Superiores. Se você conjurar essa magia usando certos espaços de magia superiores, você escolhe uma das opções de invocação acima e mais criaturas aparecem: o dobro delas com um espaço de 6° nível e o triplo delas com um espaço de 8° nível.', '1 ação', 18, 'Concentração, até 1 hora', NULL, TRUE, TRUE, TRUE, 4, 'Conjuração'),
(84, 'Consagrar', 'Você toca um ponto e infunde uma área em torno dele com poder sagrado (ou profano). A área pode ter um raio de até 18 metros, e a magia falha se o raio incluir uma área já sob o efeito de uma magia consagrar.', '24 horas', 1, 'Até ser dissipada', '5d6', TRUE, TRUE, TRUE, 5, 'Evocação'),
(85, 'Consertar', 'Esta magia repara um objeto quebrado ou rompido que você toque, como um elo de corrente quebrado, duas metades de uma chave quebrada, um manto rasgado ou um odre vazando. Se a quebra ou ruptura não for maior do que 30 centímetros em qualquer direção, você a repara sem deixar traços do dano anterior. Esta magia pode reparar um item mágico ou constructo, mas não pode restaurar a magia de tal objeto.', '1 minuto', 1, 'Instantânea', NULL, TRUE, TRUE, TRUE, 0, 'Transmutação'),
(86, 'Constrição', 'Ervas daninhas e vinhas aderentes brotam do chão em um quadrado de 6 metros de lado a partir de um ponto no alcance da magia. Enquanto a magia durar, as plantas transformam o solo da área em terreno difícil. Qualquer criatura na área que não for bem-sucedida em uma salvaguarda de Força fica contida pelas plantas constritoras enquanto a magia durar.', '1 ação', 27, 'Concentração, até 1 minuto', NULL, TRUE, TRUE, FALSE, 1, 'Conjuração'),
(87, 'Contato Extraplanar', 'Você estabelece contato mental com um semideus, o espírito de um sábio morto há muito tempo ou alguma outra entidade misteriosa de outro plano. Entrar em contato com essa inteligência extraplanar pode sobrecarregar, ou até mesmo danificar, a sua mente. Ao conjurar esta magia, faça uma salvaguarda de Inteligência com CD 15. Se falhar, sofre 6d6 pontos de dano psíquico e fica insano até terminar um descanso longo.', '1 minuto', 0, '1 minuto', '6d6', TRUE, FALSE, FALSE, 5, 'Adivinhação'),
(88, 'Contramágica', 'Você tenta interromper uma criatura no processo de conjuração de uma magia. Se a criatura estiver conjurando uma magia de 3° nível ou inferior, a magia falha e não gera nenhum efeito. Se ela estiver conjurando uma magia de 4° nível ou superior, faça um teste de habilidade usando sua habilidade de conjuração. A CD é igual a 10 + o nível da magia. Caso seja bem sucedido, a magia da criatura falha e não gera nenhum efeito. Em Níveis Superiores. Se você conjurar essa magia usando um espaço de magia de 4° nível ou superior, a magia interrompida não vai gerar efeito se o nível dela for menor ou igual ao nível do espaço de magia que você usar.', '1 reação', 18, 'Instantânea', NULL, FALSE, TRUE, FALSE, 3, 'Abjuração'),
(89, 'Contingência', 'Escolha uma magia de 5° círculo ou inferior que você possa conjurar, que tenha você mesmo como único alvo possível. Você conjura essa magia — a magia contingente — como parte da conjuração de contingência. Ela não tem efeito imediatamente; em vez disso, ela entra em ação quando ocorrer determinada circunstância que você descreve ao conjurar as duas magias. A magia contingente entra em vigor imediatamente após a circunstância ocorrer pela primeira vez, independentemente da sua escolha ou vontade, e então contingência termina. Você só pode ter uma magia contingência ativa de cada vez.', '10 minutos', 0, '10 dias', NULL, TRUE, TRUE, TRUE, 6, 'Evocação'),
(90, 'Controlar a Água', 'Até o fim da magia, você controla qualquer corpo de água dentro da área que você escolher, que é um cubo de 30 metros quadrados. Você pode escolher dentre quaisquer dos efeitos seguintes, quando você conjurar essa magia. Com uma ação no seu turno, você pode repetir o mesmo efeito ou escolher um diferente. Inundação. Você faz com que o nível da água de toda área afetada suba até 6 metros. Se a área incluir uma margem, a inundação ira transbordar para a terra seca. Se você escolher uma área em um extenso corpo de água, ao invés disso, você cria uma onda com 6 metros de altura que irá de um lado ao outro da área e então desaba. Qualquer veículo Enorme ou menor no caminho da onda será carregado por ela até o outro lado. Qualquer veículo Enorme ou menor atingido pela onda tem uma chance de 25 por cento de emborcar. O nível da água se mantem elevado até a magia acabar ou você escolher um efeito diferente. Se esse efeito produzir uma onda, a onda se repete no início do seu próximo turno enquanto o efeito de inundação durar. Dividir Água. Você faz com que a água na área se divida e crie uma trincheira. A trincheira se estende por toda área da magia e a água separada forma uma parede de cada lado. A trincheira permanece até a magia acabar ou você escolher um efeito diferente. A água, então, lentamente preenche a trincheira ao longo do curso da próxima rodada até o nível normal da água ser restaurado. Redirecionar Fluxo. Você faz com que o fluxo da água na área se mova na direção que você escolher, mesmo que a água tenha que fluir através de obstáculos, subir muros ou em outra direção improvável. A água na área se move na direção ordenada, mas uma vez que tenha se movido além da área da magia, ela conclui seu fluxo baseado nas condições do terreno. A água continua a se mover na direção que você escolheu até a magia acabar ou você escolher um efeito diferente. Redemoinho. Esse efeito requer um corpo de água de, pelo menos, 15 metros quadrados e 7,5 metros de profundidade. Você faz com que um redemoinho se forme no centro da área. O redemoinho forma um vórtice com 1,5 metro de largura na base, chegando a 15 metros de largura no topo e 7,5 metros de altura. Qualquer criatura ou objeto na água a até 7,5 metros do vórtice é puxado 3 metros na direção dele. Uma criatura pode tentar nadar para longe do vórtice com um teste de Força (Atletismo) contra a CD da magia. Quando uma criatura entrar no vórtice pela primeira vez no turno dela ou começar seu turno dentro dele, ela deve realizar um teste de resistência de Força. Se falhar, a criatura sofre 2d8 de dano de concussão e estará presa no vórtice até a magia acabar. Se passar na resistência, a criatura sofre metade do dano e não estará presa no vórtice. Uma criatura presa no vórtice pode usar sua ação para tentar nadar para fora do vórtice como descrito acima, mas terá desvantagem no teste de Força (Atletismo) para fazer isso. A primeira vez a cada turno que um objeto entrar no vórtice, o objeto sofre 2d8 de dano de concussão; esse dano se repete a cada rodada que ele permanecer no vórtice.', '1 ação', 90, 'Concentração, até 10 minutos', '2d8', TRUE, TRUE, TRUE, 4, 'Transmutação'),
(91, 'Controlar o Clima', 'Você toma controle do clima numa área de 7,5 quilômetros de você pela duração. Você deve estar ao ar livre para conjurar essa magia. Se mover para um lugar onde você não tenha uma visão clara do céu termina a magia prematuramente. Quando você conjurar essa magia, você muda as condições climáticas atuais, que são determinadas pelo Mestre baseado no ambiente e estação. Você pode mudar a precipitação, temperatura e vento. Leva 1d4 x 10 minutos para as novas condições fazerem efeito. Quando a magia terminar, o clima, gradualmente, volta ao normal. Quando você altera as condições climáticas, encontre a condição atual nas tabelas a seguir e mude em um estágio, para cima ou para baixo. Quando mudar o vento, você pode mudar a direção do mesmo. PRECIPITAÇÃO Estágio Condição Céu claro 2 Parcialmente encoberto Céu escuro ou nublado 4 Chuva, granizo ou neve Chuva torrencial, tempestade de granizo ou nevasca TEMPERATURA VENTO Estágio Condição Estágio Condição Calor insuportável Calmo 2 Quente 2 Vento moderado Morno Vento forte 4 Frio 4 Ventania Gelado Temporal Frio ártico', '10 minutos', 0, 'Concentração, até 8 horas', NULL, TRUE, TRUE, TRUE, 8, 'Transmutação'),
(92, 'Convocar Familiar', 'Você passa a contar com os serviços de um familiar, um espírito que assume a forma de um animal à sua escolha: morcego, gato, caranguejo, sapo (rã), falcão, lagarto, polvo, coruja, cobra venenosa, peixe (piranha), rato, corvo, cavalo marinho, aranha ou furão. O familiar tem as estatísticas da forma escolhida, apesar de ser um celestial, feérico ou ínfero (à sua escolha), em vez de uma fera. Ele age independentemente de você, mas sempre obedece aos seus comandos.', '1 hora', 3, 'Instantânea', NULL, TRUE, TRUE, TRUE, 1, 'Conjuração'),
(93, 'Convocar Montaria', 'Você invoca um espírito que assume a forma de uma montaria especialmente inteligente, forte e fiel, criando um vínculo de longa duração com ela. Escolha a forma: um alce, um camelo, um cavalo de guerra, um mastim ou um pônei. A montaria tem as estatísticas da forma escolhida, mas é um celestial, feérico ou ínfero (à sua escolha), em vez do tipo normal. Ela serve como sua montaria, tanto em combate quanto fora dele, e vocês têm um elo instintivo que lhes permite lutar como uma unidade perfeita. Quando a criatura ficar com 0 ponto de vida, ela desaparece, não deixando corpo algum para trás.', '10 minutos', 9, 'Instantânea', NULL, TRUE, TRUE, FALSE, 2, 'Conjuração'),
(94, 'Convocar Relâmpagos', 'Uma nuvem tempestuosa aparece em formato cilíndrico com 3 metros de altura e 18 metros de raio, centrada num ponto que você possa ver, 30 metros acima de você. A magia falha se você não puder ver um ponto no ar em que a nuvem possa aparecer (por exemplo, se você estiver em uma sala que não possa comportar a nuvem). Quando você conjurar a magia, escolha um ponto que você possa ver dentro do alcance. Um raio de eletricidade é disparado da nuvem no ponto. Cada criatura a 1,5 metro desse ponto deve realizar um teste de resistência de Destreza. Uma criatura sofre 3d10 de dano elétrico se falhar no teste, ou metade desse dano se passar. Em cada um dos seus turnos, até a magia acabar, você pode usar sua ação para convocar um relâmpago dessa forma novamente, afetando o mesmo ponto ou um diferente. Se você estiver a céu aberto em condições tempestuosas quando conjurar essa magia, a magia lhe dá controle sobre a tempestade existente ao invés de criar uma nova. Sob tais condições, o dano da magia aumenta em 1d10. Em Níveis Superiores. Se você conjurar essa magia usando um espaço de magia de 4° nível ou superior, o dano aumenta em 1d10 para cada nível do espaço acima do 3°.', '1 ação', 36, 'Concentração, até 10 minutos', '3d10', TRUE, TRUE, FALSE, 3, 'Conjuração'),
(95, 'Coroa da Loucura', 'Escolha um humanoide à sua vista e dentro do alcance da magia. O alvo deve ser bem-sucedido em uma salvaguarda de Sabedoria, ou fica enfeitiçado por você enquanto a magia durar. Uma coroa de ferro retorcido e irregular surge na cabeça, e loucura brilhante irradia dos olhos do alvo enquanto a magia durar. Em cada um dos próprios turnos e antes de se movimentar, o alvo enfeitiçado deve usar uma ação para realizar um ataque corpo a corpo contra uma criatura escolhida mentalmente por você, e que não seja ele mesmo.', '1 ação', 36, 'Concentração, até 1 minuto', NULL, TRUE, TRUE, FALSE, 2, 'Encantamento'),
(96, 'Cordão de Flechas', 'Você enfinca quatro munições não-mágicas – flechas ou virotes de besta – no solo dentro do alcance e conjura magia neles para proteger uma área. Até a magia acabar, sempre que uma criatura diferente de você se aproximar a 9 metros das munições pela primeira vez em um turno ou terminar seu turno na área, uma das munições voa para atingi-la. A criatura deve ser bem sucedida num teste de resistência de Destreza ou sofrerá 1d6 de dano perfurante. A munição, então, é destruída. A magia termina quando não restar nenhuma munição. Quando você conjurar essa magia, você pode designar quaisquer criaturas, à sua escolha, e a magia ignora-as. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 3° nível ou superior, a quantidade de munições que você pode afetar aumenta em dois para cada nível do espaço acima do 2°.', '1 ação', 1, '8 horas', '1d6', TRUE, TRUE, TRUE, 2, 'Transmutação'),
(97, 'Corrente de Relâmpagos', 'Você cria um raio elétrico que atinge um alvo, à sua escolha, que você possa ver dentro do alcance. Três raios saltam do alvo para até três outros alvos, cada um a não mais de 9 metros do alvo primário. Um alvo pode ser uma criatura ou um objeto e só pode ser alvo de um único desses raios. Um alvo deve realizar um teste de resistência de Destreza. O alvo sofre 10d8 de dano elétrico se falhar no teste ou metade desse dano se for bem sucedido. Em Níveis Superiores. Se você conjurar essa magia usando um espaço de magia de 7° nível ou superior, um raio adicional salta do alvo primário para outro alvo para cada nível do espaço acima do 6°.', '1 ação', 45, 'Instantânea', '10d8', TRUE, TRUE, TRUE, 6, 'Evocação'),
(98, 'Crescer Espinhos', 'O chão, em um raio de 6 metros centrado em um ponto no alcance da magia, é revirado e dele brotam espigões e espinhos. A área se torna terreno difícil enquanto a magia durar. Quando uma criatura se mover para dentro ou para fora da área, ela sofre 2d4 pontos de dano perfurante para cada 1,5 metro que se mover.', '1 ação', 45, 'Concentração, até 10 minutos', '2d4', TRUE, TRUE, TRUE, 2, 'Transmutação'),
(99, 'Criação', 'Você puxa mechas de matéria sombria da Umbra para criar objetos inanimados de matéria vegetal dentro do alcance: bens finos, cordas, madeira ou algo similar. Você também pode usar a magia para criar objetos minerais como pedra, cristal ou metal. O objeto criado não pode ser maior que um cubo de 1,5 metro e o objeto deve ser de um formado e material que você já tenha visto antes. A duração depende do material do objeto. Se o objeto for composto por diversos materiais, use o de menor duração. Material Duração Matéria vegetal 1 dia Pedra ou cristal 12 horas Metais preciosos 1 hora Gemas 10 minutos Adamante ou mitral 1 minuto Usar qualquer material criado por essa magia como componente material de outra magia faz com que a magia falhe. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 6° nível ou superior, o tamanho do cubo aumenta em 1,5 metro para cada nível do espaço de magia acima do 5°.', '1 minuto', 9, 'Especial', NULL, TRUE, TRUE, TRUE, 5, 'Ilusão'),
(100, 'Criar Alimentos', 'Você cria 20 quilos de comida e 120 litros de água no chão ou em recipientes no alcance da magia, o suficiente para sustentar até quinze humanoides ou cinco montarias por 24 horas.', '1 ação', 9, 'Instantânea', NULL, TRUE, TRUE, FALSE, 3, 'Conjuração'),
(101, 'Criar Chamas', 'Uma chama bruxuleante surge em sua mão. Ela permanece assim enquanto a magia durar e não causa dano a você ou ao seu equipamento. A labareda emite luz plena em um raio de 3 metros e meia-luz por mais 3 metros. A magia termina se você a dispensar com uma ação ou se conjurá-la novamente. Você também pode atacar com a chama, embora fazê-lo encerre a magia: faça um ataque de magia à distância contra uma criatura a até 9 metros de você. Se acertar, o alvo sofre 1d8 pontos de dano ígneo. O dano desta magia aumenta em 1d8 quando você alcança o 5° nível (2d8), o 11° nível (3d8) e o 17° nível (4d8).', '1 ação', 0, '10 minutos', '1d8', TRUE, TRUE, FALSE, 0, 'Conjuração'),
(102, 'Criar Mortos-Vivos', 'Você só pode conjurar essa magia durante a noite. Escolha até três corpos de humanoides Médios ou Pequenos dentro do alcance. Cada corpo se torna um carniçal sob seu controle. (O Mestre tem as estatísticas de jogo das criaturas.) Com uma ação bônus, em cada um dos seus turnos, você pode comandar mentalmente qualquer criatura que você animou com essa magia, se a criatura estiver a até 36 metros de você (se você controla diversas criaturas, você pode comandar qualquer uma ou todas elas ao mesmo tempo, emitindo o mesmo comando para cada uma). Você decide qual ação a criatura irá fazer e para onde ela irá se mover durante o próximo turno dela, ou você pode emitir um comando geral, como para guardar uma câmara ou corredor especifico. Se você não der nenhum comando, as criaturas apenas se defenderão contra criaturas hostis. Uma vez que receba uma ordem, a criatura continuará a segui-la até a tarefa estar concluída. A criatura fica sob seu controle por 24 horas, depois disso ela para de obedecer aos seus comandos. Para manter o controle da criatura por mais 24 horas, você deve conjurar essa magia na criatura novamente, antes das 24 horas atuais terminarem. Esse uso da magia recupera seu controle sobre até três criaturas que você tenha animado com essa magia, ao invés de animar novas. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 7° nível, você pode animar ou recuperar o controle de quatro carniçais. Quando você conjura essa magia usando um espaço de magia de 8° nível, você pode animar ou recuperar o controle de cinco carniçais ou dois lívidos ou aparições. Quando você conjurar essa magia usando um espaço de magia de 9° nível, você pode animar ou recuperar o controle de seis carniçais, três lívidos ou aparições ou duas múmias.', '1 minuto', 3, 'Instantânea', NULL, TRUE, TRUE, TRUE, 6, 'Necromancia'),
(103, 'Criar ou Destruir Água', 'Você pode tanto criar quanto destruir água. Criar Água. Você cria 30 litros de água limpa dentro do alcance, em um recipiente aberto. Alternativamente, a água pode cair como chuva em um cubo de 9 metros dentro do alcance, extinguindo chamas expostas na área. Destruir Água. Você destrói até 30 litros de água de um recipiente aberto dentro do alcance. Alternativamente, você pode destruir um nevoeiro em um cubo de 9 metros dentro do alcance. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 2° nível ou superior, você pode criar ou destruir 30 litros de água adicionais, ou o tamanho do cubo aumenta em 1,5 metro, para cada nível do espaço acima do 1°.', '1 ação', 9, 'Instantânea', NULL, TRUE, TRUE, TRUE, 1, 'Transmutação'),
(104, 'Criar Passagem', 'Uma passagem surge numa superfície de madeira, argamassa ou pedra (como uma parede, teto ou chão) escolhida, à sua vista, no alcance da magia, e permanece enquanto esta durar. Ao desaparecer, qualquer criatura ou objeto que estiver dentro da passagem criada pela magia é expelido com segurança para um espaço desocupado na superfície na qual você conjurou a magia.', '1 ação', 9, '1 hora', NULL, TRUE, TRUE, TRUE, 5, 'Transmutação'),
(105, 'Cúpula Antivida', 'Uma barreira cintilante se estende de você até 3 metros de raio, e se move com você, permanecendo centrada em você e restringindo criaturas diferentes de mortos-vivos e constructos. A barreira mantem-se pela duração. A barreira previna uma criatura afetada de atravessa la ou alcançar através dela. Uma criatura afetada pode conjurar magias ou realizar ataques à distância ou ataques com armas de haste através da barreira. Se você se mover forçando uma criatura afetada a atravessar a barreira, a magia termina.', '1 ação', 0, 'Concentração, até 1 hora', NULL, TRUE, TRUE, FALSE, 5, 'Abjuração'),
(106, 'Cura Completa', 'Escolha uma criatura que você possa ver, dentro do alcance. Um surto de energia positiva banha a criatura, fazendo-a recuperar 70 pontos de vida. Essa magia também acaba com efeitos de cegueira, surdez e qualquer doença que estejam afetando o alvo. Essa magia não tem efeito em constructos ou mortos-vivos. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 7° nível ou superior, a quantidade de cura aumenta em 10 para cada nível do espaço acima do 6°.', '1 ação', 18, 'Instantânea', NULL, TRUE, TRUE, FALSE, 6, 'Evocação'),
(107, 'Cura Completa em Massa', 'Uma inundação de energia curativa emerge de você para as criaturas feridas ao seu redor. Você restaura até 700 pontos de vida, divididos, à sua escolha, entre qualquer quantidade de criaturas que você possa ver, dentro do alcance. As criaturas curadas por essa magia também são curadas de todas as doenças e qualquer efeito que as deixou cegas ou surdas. Essa magia não afeta mortos vivos ou constructos.', '1 ação', 18, 'Instantânea', NULL, TRUE, TRUE, FALSE, 9, 'Evocação'),
(108, 'Curar Ferimentos', 'Uma criatura que você tocar recupera uma quantidade de pontos de vida igual a 1d8 + seu modificador de habilidade de conjuração. Essa magia não produz efeito em mortos-vivos ou constructos. Em Níveis Superiores. Se você conjurar essa magia usando um espaço de magia de 2° nível ou superior, a cura aumenta em 1d8 para cada nível do espaço acima do 1°.', '1 ação', 1, 'Instantânea', NULL, TRUE, TRUE, FALSE, 1, 'Evocação'),
(109, 'Curar Ferimentos em Massa', 'Uma onda de energia curativa emerge de um ponto, à sua escolha, dentro do alcance. Escolha até seis criaturas numa esfera de 9 metros de raio, centrada nesse ponto. Cada alvo recupera uma quantidade de pontos de vida igual a 3d8 + seu modificador de habilidade de conjuração. A magia não afeta mortos-vivos ou constructos. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 6° nível ou superior, a cura aumenta em 1d8 para cada nível do espaço acima do 5°.', '1 ação', 18, 'Instantânea', NULL, TRUE, TRUE, FALSE, 5, 'Evocação'),
(110, 'Dança Irresistível de Otto', 'Escolha uma criatura que você possa ver, dentro do alcance. O alvo começa a dançar comicamente no lugar: rodopiando, batendo os pés e saltitando pela duração. As criaturas que não podem ser enfeitiçadas são imunes a essa magia. Uma criatura dançando deve usar todo o seu movimento para dançar sem abandonar seu espaço e tem desvantagem nos testes de resistência de Destreza e nas jogadas de ataque. Enquanto o alvo estiver sob efeito dessa magia, as outras criaturas terão vantagem nas jogadas de ataque contra ele. Com uma ação, uma criatura dançando pode realizar um teste de resistência de Sabedoria para recuperar controle sobre si mesmo. Num sucesso na resistência, a magia acaba.', '1 ação', 9, 'Concentração, até 1 minuto', NULL, TRUE, FALSE, FALSE, 6, 'Encantamento'),
(111, 'Dedo da Morte', 'Você envia energia negativa na direção de uma criatura que você possa ver, dentro do alcance, causando dores severas nela. O alvo deve realizar um teste de resistência de Constituição. Ele sofre 7d8 + 30 de dano necrótico se falhar na resistência, ou metade desse dano se obtiver sucesso. Um humanoide morto por essa magia, se ergue no início do seu próximo turno como um zumbi que está permanentemente sob seu controle, seguindo suas ordens verbais da melhor forma possível.', '1 ação', 18, 'Instantânea', '7d8+30', TRUE, TRUE, FALSE, 7, 'Necromancia'),
(112, 'Desejo', 'Desejo é a mais poderosa magia que uma criatura mortal pode conjurar. Entre os efeitos possíveis: você permite que até vinte criaturas à sua vista recuperem todos os pontos de vida e encerra todos os efeitos descritos na magia restauração maior; você concede a até dez criaturas à sua vista resistência a um tipo de dano à sua escolha; você concede a até dez criaturas à sua vista imunidade a uma única magia ou outro efeito mágico por 8 horas; ou você pode desfazer um acontecimento recente, forçando uma nova jogada de dados feita na última rodada. Usar a magia para além de duplicar outra magia de 8º círculo ou menor traz o risco de fadiga arcana severa para o conjurador.', '1 ação', 0, 'Instantânea', NULL, TRUE, FALSE, FALSE, 9, 'Conjuração'),
(113, 'Desintegrar', 'Um fino raio esverdeado é lançado da ponta do seu dedo em um alvo que você possa ver dentro do alcance. O alvo pode ser uma criatura, um objeto ou uma criação de energia mágica, como uma muralha criada por muralha de energia. Uma criatura afetada por essa magia deve realizar um teste de resistência de Destreza. Se falhar na resistência, o alvo sofrerá 10d6 + 40 de dano de energia. Se esse dano reduzir os pontos de vida do alvo a 0, ele será desintegrado. Uma criatura desintegrada e tudo que ela está vestindo ou carregando, exceto itens mágicos, são reduzidos a uma pilha de um fino pó acinzentado. A criatura só pode ser trazida de volta a vida por meio das magias ressurreição verdadeira ou desejo. Essa magia desintegra, automaticamente, um objeto não-mágico Grande ou menor ou uma criação de energia mágica. Se o alvo for um objeto ou criação de energia Enorme ou maior, a magia desintegra uma porção de 3 metros cúbicos dele. Um item mágico não pode ser afetado por essa magia. Em Níveis Superiores. Se você conjurar essa magia usando um espaço de magia de 7° nível ou superior, o dano aumenta em 3d6 para cada nível do espaço acima do 6°.', '1 ação', 18, 'Instantânea', '10d6+40', TRUE, TRUE, TRUE, 6, 'Transmutação'),
(114, 'Despedaçar', 'Um alto som estridente, dolorosamente intenso, emerge de um ponto, à sua escolha, dentro do alcance. Cada criatura, numa esfera de 3 metros de raio, centrada no ponto deve fazer um teste de resistência de Constituição. Uma criatura sofre 3d8 de dano trovejante se falhar na resistência ou metade desse dano se obtiver sucesso. Uma criatura feita de material inorgânico como pedra, cristal ou metal, tem desvantagem nesse teste de resistência. Um objeto não-mágico que não esteja sendo vestido ou carregado, também sofre o dano, se estiver na área da magia. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 3° nível ou superior, o dano aumenta em 1d8 para cada nível do espaço acima do 2°.', '1 ação', 18, 'Instantânea', '3d8', TRUE, TRUE, TRUE, 2, 'Evocação'),
(115, 'Despertar', 'Depois de gastar o tempo de conjuração traçando padrões mágicos com uma pedra preciosa, você toca em uma fera ou planta de tamanho Enorme ou menor. O alvo deve ter um valor de Inteligência igual a 3 ou menor, ou não possuir Inteligência alguma. O alvo ganha um valor de Inteligência de 10, além da habilidade de falar um idioma que você conheça.', '8 horas', 1, 'Instantânea', NULL, TRUE, TRUE, TRUE, 5, 'Transmutação'),
(116, 'Despistar', 'Você fica invisível ao mesmo tempo que uma cópia ilusória sua aparece onde você estava. A cópia permanece pela duração, mas a invisibilidade acaba se você atacar ou conjurar uma magia. Você pode usar sua ação para mover a cópia ilusória até o dobro do seu deslocamento e fazê-la gesticular, falar e se comportar da forma que você quiser. Você pode ver através dos olhos e ouvir através dos ouvidos da cópia como se você estivesse localizado onde ela está. Em cada um dos seus turnos, com uma ação bônus, você pode trocar o uso dos sentidos dela pelo seu ou voltar novamente. Enquanto você está usando os sentidos dela, você fica cego e surdo ao que está a sua volta.', '1 ação', 0, 'Concentração, até 1 hora', NULL, FALSE, TRUE, FALSE, 5, 'Ilusão'),
(117, 'Destruição Banidora', 'Da próxima vez que você atingir uma criatura com um ataque com arma, antes do fim da magia, seu ataque crepita com energia e o ataque causa 5d6 de dano de energia extra ao alvo. Além disso, se esse ataque reduzir o alvo a 50 pontos de vida ou menos, você a bane. Se o alvo for nativo de um plano de existência diferente do que você está, o alvo desaparece, retornando ao seu plano natal. Se o alvo for nativo do plano que você está, a criatura é enviada para um semiplano inofensivo. Enquanto estiver lá, a criatura estará incapacitada. Ela permanece lá até a magia acabar, a partir desse ponto, o alvo reaparece no espaço em que ela deixou ou no espaço desocupado mais próximo, se o espaço dela estiver ocupado.', '1 ação bônus', 0, 'Concentração, até 1 minuto', '5d6', TRUE, FALSE, FALSE, 5, 'Abjuração'),
(118, 'Destruição Cegante', 'Da próxima vez que você atingir uma criatura com um ataque com arma, antes do fim da magia, sua arma emite uma luz intensa, e o ataque causa 3d8 de dano radiante extra ao alvo. Além disso, o alvo deve ser bem sucedido num teste de resistência de Constituição ou ficará cego até a magia acabar. Uma criatura cega por essa magia realiza outro teste de resistência de Constituição no final de cada um dos turnos dela. Se obtiver sucesso, não estará mais cega.', '1 ação bônus', 0, 'Concentração, até 1 minuto', '3d8', TRUE, FALSE, FALSE, 3, 'Evocação'),
(119, 'Destruição Colérica', 'Enquanto a magia durar, seu próximo acerto num ataque com uma arma de combate corpo a corpo causa 1d6 pontos de dano psíquico adicionais. Além disso, se o alvo for uma criatura, ela deve fazer uma salvaguarda de Sabedoria ou fica amedrontada enquanto a magia durar. Com uma ação, a criatura pode fazer um teste de Sabedoria contra a CD para evitar sua magia, endurecendo a própria determinação e encerrando os efeitos da magia sobre ela.', '1 ação bônus', 0, 'Concentração, até 1 minuto', '1d6', TRUE, FALSE, FALSE, 1, 'Evocação'),
(120, 'Destruição Estonteante', 'Na próxima vez que você acertar uma criatura com um ataque com uma arma de combate corpo a corpo durante a duração da magia, sua arma atinge tanto o corpo quanto a mente, e o ataque causa 4d6 pontos de dano psíquico adicionais no alvo. Além disso, o alvo deve ser bem-sucedido em uma salvaguarda de Sabedoria ou fica com desvantagem em jogadas de ataque e testes de atributo, e não pode ter reações, até o final do seu próximo turno.', '1 ação bônus', 0, 'Concentração, até 1 minuto', '4d6', TRUE, FALSE, FALSE, 4, 'Evocação'),
(121, 'Destruição Lancinante', 'Da próxima vez que você atingir uma criatura com um ataque corpo-a-corpo com arma enquanto essa magia durar, sua arma flameja com intensas chamas brancas e o ataque causa 1d6 de dano de fogo extra ao alvo, fazendo-o incendiar pelas chamas. No início de cada turno dele, até a arma acabar, o alvo deve realizar um teste de resistência de Constituição. Se falhar na resistência, ele sofre 1d6 de dano de fogo. Se passar na resistência, a magia acaba. Se o alvo ou uma criatura a 1,5 metro dele usar uma ação para apagar as chamas ou se algum outro efeito extinguir as chamas (como submergir o alvo em água), a magia acaba. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 2° nível ou superior, o dano extra inicial causado por esse ataque aumenta em 1d6 para cada nível do espaço acima do 1°.', '1 ação bônus', 0, 'Concentração, até 1 minuto', '1d6', TRUE, FALSE, FALSE, 1, 'Evocação'),
(122, 'Destruição Troveante', 'Enquanto a magia durar, na primeira vez que você acertar um ataque com uma arma de combate corpo a corpo, sua arma ressoa com trovões audíveis a 90 metros de você e causa 2d6 pontos de dano trovejante adicionais. Além disso, se o alvo for uma criatura, ela deve ser bem-sucedida em uma salvaguarda de Força ou é empurrada 3 metros para longe de você e fica caída.', '1 ação bônus', 0, 'Concentração, até 1 minuto', '2d6', TRUE, FALSE, FALSE, 1, 'Evocação'),
(123, 'Detectar o Bem e Mal', 'Enquanto a magia durar, você pode sentir a presença e localização de uma criatura do tipo aberração, celestial, elemental, feérico, ínfero ou morto-vivo que se encontre a até 9 metros de distância. Da mesma forma, você sabe se existe um lugar ou objeto a até 9 metros que tenha sido magicamente consagrado ou profanado.', '1 ação', 0, 'Concentração, até 10 minutos', NULL, TRUE, TRUE, FALSE, 1, 'Adivinhação'),
(124, 'Detectar Magia', 'Enquanto a magia durar, você pode sentir a presença de energia mágica a até 9 metros. Caso seja bem-sucedido ao fazê-lo, você pode usar sua ação para ver uma tênue aura ao redor de qualquer criatura ou objeto que possua energia mágica e que esteja visível na área, distinguindo, inclusive, a escola da magia, caso ela pertença a alguma.', '1 ação', 0, 'Concentração, até 10 minutos', NULL, TRUE, TRUE, FALSE, 1, 'Adivinhação'),
(125, 'Detectar Pensamentos', 'Enquanto a magia durar, você pode ler os pensamentos de certas criaturas. Ao conjurar esta magia, e com uma ação em cada um de seus turnos enquanto a magia durar, você pode focar sua mente em qualquer criatura à sua vista e que esteja a até 9 metros de distância de você. Perguntas verbais dirigidas à criatura alvo moldam naturalmente o curso dos pensamentos dela, o que torna esta magia particularmente eficaz como parte de um interrogatório. Você também pode usar esta magia para detectar a presença de criaturas pensantes que você não possa ver.', '1 ação', 0, 'Concentração, até 1 minuto', NULL, TRUE, TRUE, TRUE, 2, 'Adivinhação'),
(126, 'Detectar Veneno e Doença', 'Enquanto a magia durar, você pode sentir a presença e a localização de venenos, criaturas venenosas e doenças a até 9 metros de distância. Você também pode identificar o tipo de veneno, criatura venenosa ou doença em cada caso.', '1 ação', 0, 'Concentração, até 10 minutos', NULL, TRUE, TRUE, TRUE, 1, 'Adivinhação'),
(127, 'Dificultar Detecção', 'Você esconde uma criatura voluntária ou um objeto, tornando-o livre de detecção enquanto a magia durar. Ao conjurar a magia e tocar o alvo, este não pode ser alvo de magias de adivinhação ou percebido através de sensores mágicos criados por feitiços de adivinhação.', '1 ação', 1, '8 horas', NULL, TRUE, TRUE, TRUE, 3, 'Abjuração'),
(128, 'Disco Flutuante de Tenser', 'Esta magia cria um disco circular horizontal feito de energia com 1 metro de diâmetro e 2,5 centímetros de altura, que flutua a 1 metro do chão em um espaço desocupado à sua escolha, à sua vista e no alcance da magia. O disco permanece enquanto a magia durar e pode carregar até 225 quilos.', '1 ação', 9, '1 hora', NULL, TRUE, TRUE, TRUE, 1, 'Conjuração'),
(129, 'Disfarçar-se', 'Você faz com que você mesmo — incluindo suas roupas, armaduras, armas e outros pertences que esteja carregando — ganhe outra aparência, enquanto a magia durar ou até que você use sua ação para encerrá-la. Você pode parecer 30 centímetros mais baixo ou mais alto, e parecer magro, gordo ou algo entre os dois. Para descobrir que você está disfarçado, uma criatura pode usar a ação dela para inspecionar sua aparência, devendo ser bem-sucedida em um teste de Inteligência (Investigação) contra a CD para evitar sua magia.', '1 ação', 0, '1 hora', NULL, TRUE, TRUE, FALSE, 1, 'Ilusão'),
(130, 'Dissipar Magia', 'Escolha uma criatura, objeto ou efeito mágico dentro do alcance. Qualquer magia de 3° nível ou inferior no alvo, termina. Para cada magia de 4° nível ou superior no alvo, realize um teste de habilidade usando sua habilidade de conjuração. A CD é igual a 10 + o nível da magia. Se obtiver sucesso, a magia termina. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 4° nível ou superior, você dissipa automaticamente os efeitos de magias no alvo se o nível da magia for igual ou inferior ao nível do espaço de magia que você usar.', '1 ação', 36, 'Instantânea', NULL, TRUE, TRUE, FALSE, 3, 'Abjuração'),
(131, 'Dissipar o Bem e Mal', 'Energia cintilante envolve e protege você de fadas, mortos-vivos e criaturas originarias além do Plano Material. Pela duração, celestiais, corruptores, elementais, fadas e mortos-vivos tem desvantagem nas jogadas de ataque contra você. Você pode terminar a magia prematuramente usando uma das funções especiais a seguir. Cancelar Encantamento. Com sua ação, você toca uma criatura que você possa alcançar que esteja enfeitiçada, amedrontada ou possuída por um celestial, corruptor, elemental, fada ou morto-vivo. A criatura tocada não estará mais enfeitiçada, amedrontada ou possuída por tais criaturas. Demissão. Com sua ação, faça um ataque corpo-a corpo com magia contra um celestial, corruptor, elemental, fada ou morto-vivo que você possa alcançar. Se atingir, você pode tentar guiar a criatura de volta ao seu plano natal. A criatura deve ser bem sucedida num teste de resistência de Carisma ou será enviada de volta ao seu plano natal (se já não for aqui). Se elas não estiverem em seus planos de origem, mortos-vivos serão enviados para Umbra e fadas serão enviadas para Faéria.', '1 ação', 0, 'Concentração, até 1 minuto', NULL, TRUE, TRUE, TRUE, 5, 'Abjuração'),
(132, 'Doença Plena', 'Você introduz uma doença virulenta em uma criatura que você puder ver, dentro do alcance. O alvo deve realizar um teste de resistência de Constituição. Se falhar na resistência, ele sofre 14d6 de dano necrótico ou metade desse dano se obtiver sucesso na resistência. O dano não pode reduzir os pontos de vida do alvo abaixo de 1. Se o alvo falhar no teste de resistência, seu máximo de pontos de vida é reduzidos por 1 hora em uma quantidade igual ao dano necrótico causado. Qualquer efeito que remova uma doença permitirá que o máximo de pontos de vida do alvo volte ao normal antes do período indicado.', '1 ação', 18, 'Instantânea', '14d6', TRUE, TRUE, FALSE, 6, 'Necromancia'),
(133, 'Dominar Besta', 'Você tenta seduzir uma besta que você possa ver dentro do alcance. Ela deve ser bem sucedida num teste de resistência de Sabedoria ou ficará enfeitiçada por você pela duração. Se você ou criaturas amigáveis a você estiverem lutando com ela, ela terá vantagem no teste de resistência. Enquanto a besta estiver enfeitiçada, você terá uma ligação telepática com ela, contanto que ambos estejam no mesmo plano de existência. Você pode usar essa ligação telepática para emitir comandos para a criatura enquanto você estiver consciente (não requer uma ação), aos quais ela obedece da melhor forma possível. Você pode especificar um curso de ação simples e genérico, como “Ataque aquela criatura”, “Corra até ali”, ou “Traga aquele objeto”. Se a criatura completar a ordem e não receber direções posteriores de você, ela se defenderá e se auto preservará da melhor forma que puder. Você pode usar sua ação para tomar controle total e preciso do alvo. Até o final do seu próximo turno, a criatura realiza apenas as ações que você escolher e não faz nada que você não permita que ela faça. Durante esse período, você também pode fazer com que a criatura use uma reação, mas isso requer que você usa sua própria reação também. Cada vez que o alvo sofrer dano, ele realiza um novo teste de resistência de Sabedoria contra a magia. Se obtiver sucesso no teste de resistência, a magia termina. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 5° nível, a duração será concentração, até 10 minutos. Quando você usar um espaço de magia de 6° nível, a duração será concentração, até 1 hora. Quando você usar um espaço de magia de 7° nível, a duração será concentração, até 8 horas.', '1 ação', 18, 'Concentração, até 1 minuto', NULL, TRUE, TRUE, FALSE, 4, 'Encantamento'),
(134, 'Dominar Monstro', 'Você tenta seduzir uma criatura que você possa ver dentro do alcance. Ela deve ser bem sucedida num teste de resistência de Sabedoria ou ficará enfeitiçada por você pela duração. Se você ou criaturas amigáveis a você estiverem lutando com ela, ela terá vantagem no teste de resistência. Enquanto a criatura estiver enfeitiçada, você terá uma ligação telepática com ela, contanto que ambos estejam no mesmo plano de existência. Você pode usar essa ligação telepática para emitir comandos para a criatura enquanto você estiver consciente (não requer uma ação), aos quais ela obedece da melhor forma possível. Você pode especificar um curso de ação simples e genérico, como “Ataque aquela criatura”, “Corra até ali”, ou “Traga aquele objeto”. Se a criatura completar a ordem e não receber direções posteriores de você, ela se defenderá e se auto preservará da melhor forma que puder. Você pode usar sua ação para tomar controle total e preciso do alvo. Até o final do seu próximo turno, a criatura realiza apenas as ações que você escolher e não faz nada que você não permita que ela faça. Durante esse período, você também pode fazer com que a criatura use uma reação, mas isso requer que você usa sua própria reação também. Cada vez que o alvo sofrer dano, ele realiza um novo teste de resistência de Sabedoria contra a magia. Se obtiver sucesso no teste de resistência, a magia termina. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 9° nível, a duração será concentração, até 8 horas.', '1 ação', 18, 'Concentração, até 1 hora', NULL, TRUE, TRUE, FALSE, 8, 'Encantamento'),
(135, 'Dominar Pessoa', 'Você tenta seduzir um humanoide que você possa ver dentro do alcance. Ele deve ser bem sucedido num teste de resistência de Sabedoria ou ficará enfeitiçado por você pela duração. Se você ou criaturas amigáveis a você estiverem lutando com ele, ele terá vantagem no teste de resistência. Enquanto o alvo estiver enfeitiçado, você terá uma ligação telepática com ela, contanto que ambos estejam no mesmo plano de existência. Você pode usar essa ligação telepática para emitir comandos para a criatura enquanto você estiver consciente (não requer uma ação), aos quais ela obedece da melhor forma possível. Você pode especificar um curso de ação simples e genérico, como “Ataque aquela criatura”, “Corra até ali”, ou “Traga aquele objeto”. Se a criatura completar a ordem e não receber direções posteriores de você, ela se defenderá e se auto preservará da melhor forma que puder. Você pode usar sua ação para tomar controle total e preciso do alvo. Até o final do seu próximo turno, a criatura realiza apenas as ações que você escolher e não faz nada que você não permita que ela faça. Durante esse período, você também pode fazer com que a criatura use uma reação, mas isso requer que você usa sua própria reação também. Cada vez que o alvo sofrer dano, ele realiza um novo teste de resistência de Sabedoria contra a magia. Se obtiver sucesso no teste de resistência, a magia termina. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 6° nível, a duração será concentração, até 10 minutos. Quando você usar um espaço de magia de 7° nível, a duração será concentração, até 1 hora. Quando você usar um espaço de magia de 8° nível, a duração será concentração, até 8 horas.', '1 ação', 18, 'Concentração, até 1 minuto', NULL, TRUE, TRUE, FALSE, 5, 'Encantamento'),
(136, 'Druidismo', 'Sussurrando para os espíritos da natureza, você cria um dos seguintes efeitos dentro do alcance: um pequeno e inofensivo efeito sensorial que prevê qual será o clima na sua localização nas próximas 24 horas, manifestando-se como uma esfera dourada para céu claro, uma nuvem para chuva, flocos de neve caindo para neve, e assim por diante, persistindo por 1 rodada; uma flor desabrocha, uma semente amadurece ou um broto de folha se abre; um efeito sensorial inofensivo e instantâneo, como folhas caindo, um sopro de vento, o som de um pequeno animal ou o fraco odor de um gambá, que deve caber em um cubo de 1,5 metro; ou uma vela, tocha ou fogueira pequena acende ou apaga imediatamente.', '1 ação', 9, 'Instantânea', NULL, TRUE, TRUE, FALSE, 0, 'Transmutação'),
(137, 'Duelo Compelido', 'Você tenta compelir uma criatura a um duelo. Uma criatura à sua vista deve fazer uma salvaguarda de Sabedoria. Se falhar, a criatura é atraída até você, compelida por sua magia a duelar. No final de cada um dos turnos do alvo, enquanto a magia durar, ele deve fazer outra salvaguarda de Sabedoria se estiver tentando atacar ou se afastar de você.', '1 ação bônus', 9, 'Concentração, até 1 minuto', NULL, TRUE, FALSE, FALSE, 1, 'Encantamento'),
(138, 'Encarnação Fantasmagórica', 'Baseado nos mais profundos medos de um grupo de criaturas, você cria criaturas ilusórias nas mentes delas, visíveis apenas por elas. Cada criatura numa esfera com 9 metros de raio centrada num ponto, à sua escolha, dentro do alcance, deve realizar um teste de resistência de Sabedoria. Se falhar na resistência, uma criatura ficará amedrontada pela duração. A ilusão invoca os medos mais profundos da criatura, manifestando seus piores pesadelos como uma ameaça implacável. No final de cada turno da criatura amedrontada, ela deve ser bem sucedida num teste de resistência de Sabedoria ou sofrerá 4d10 de dano psíquico. Se obtiver sucesso na resistência, a magia termina para essa criatura.', '1 ação', 36, 'Concentração, até 1 minuto', '4d10', TRUE, TRUE, FALSE, 9, 'Ilusão'),
(139, 'Encontrar Armadilhas', 'Você sente a presença de qualquer armadilha em sua linha de visão e no alcance da magia. Uma armadilha, para os fins desta magia, inclui qualquer coisa que causaria um efeito repentino ou inesperado que você considera danoso ou indesejado, e que tenha sido especificamente projetada como tal por quem a criou.', '1 ação', 36, 'Instantânea', NULL, TRUE, TRUE, FALSE, 2, 'Adivinhação'),
(140, 'Encontrar o Caminho', 'Essa magia permite que você encontre a rota física mais curta e direta para um local especifico estático, que você seja familiar, no mesmo plano de existência. Se você denominar um destino em outro plano de existência, um local que se mova (como uma fortaleza andante) ou um destino que não seja especifico (como “o covil do dragão verde”), a magia falha. Pela duração, contanto que você esteja no mesmo plano de existência do destino, você saberá o quão longe ele está e em que direção ele se encontra. Enquanto estiver viajando, sempre que você se deparar com uma escolha de trajetória no caminho, você automaticamente determina qual trajetória tem a rota mais curta e direta (mas não necessariamente a rota mais segura) para o destino.', '1 minuto', 0, 'Concentração, até 1 dia', NULL, TRUE, TRUE, TRUE, 6, 'Adivinhação'),
(141, 'Enfeitiçar Pessoa', 'Você tenta enfeitiçar um humanoide que você possa ver dentro do alcance. Ele deve realizar um teste de resistência de Sabedoria, e recebe vantagem nesse teste se você ou seus companheiros estiverem lutando com ele. Se ele falhar, ficará enfeitiçado por você até a magia acabar ou até você ou seus companheiros fizerem qualquer coisa nociva contra ele. A criatura enfeitiçada reconhece você como um conhecido amigável. Quando a magia acabar, a criatura saberá que foi enfeitiçada por você. Em Níveis Superiores. Se você conjurar essa magia usando um espaço de magia de 2° nível ou superior, você pode afetar uma criatura adicional para cada nível do espaço acima do 1°. As criaturas devem estar a até 9 metros umas das outras quando você for afeta-las.', '1 ação', 9, '1 hora', NULL, TRUE, TRUE, FALSE, 1, 'Encantamento'),
(142, 'Enfraquecer Intelecto', 'Você ataca a mente de uma criatura que você possa ver, dentro do alcance, tentando despedaçar seu intelecto e personalidade. O alvo sofre 4d6 de dano psíquico e deve realizar um teste de resistência de Inteligência. Se falhar na resistência, os valores de Inteligência e Carisma da criatura se tornam 1. A criatura não pode conjurar magias, ativar itens mágicos, compreender idiomas ou se comunicar de qualquer forma inteligível. A criatura pode, no entanto, identificar seus amigos, segui los e, até mesmo, protege-los. Ao final de cada 30 dias, a criatura pode repetir seu teste de resistência contra essa magia. Se ela obtiver sucesso no teste de resistência, a magia termina. Essa magia também pode ser terminada através de restauração maior, cura completa ou desejo.', '1 ação', 45, 'Instantânea', '4d6', TRUE, TRUE, TRUE, 8, 'Encantamento'),
(143, 'Enviar Mensagem', 'Você envia uma mensagem curta, de até 25 palavras, para uma criatura com a qual tenha alguma familiaridade. O alvo ouve a mensagem em sua mente e pode responder mentalmente, e você recebe a resposta dele. A mensagem pode ser enviada a qualquer distância e até a outros planos de existência, mas se o alvo estiver em um plano diferente do seu, existe uma chance de 5% de que ela não seja entregue.', '1 ação', 9999, '1 rodada', NULL, TRUE, TRUE, TRUE, 3, 'Evocação'),
(144, 'Escrita Ilusória', 'Você escreve em um pergaminho, papel ou algum material apropriado para escrita, infundindo-o com uma ilusão potente enquanto a magia durar. Para você e quaisquer criaturas escolhidas quando a magia é conjurada, a escrita parece com sua caligrafia normal e expressa qualquer significado de sua intenção quando o texto foi escrito. Para todos os demais, as palavras aparecem como se fossem escritas em um alfabeto desconhecido ou mágico, tornando-as ininteligíveis.', '1 minuto', 1, '10 dias', NULL, FALSE, FALSE, TRUE, 1, 'Ilusão'),
(145, 'Escudo Arcano', 'Uma barreira de força mágica invisível surge e protege você. Até o início de seu próximo turno, você terá +5 na CA, inclusive contra o ataque que disparou a reação, e você não sofre dano de mísseis mágicos.', '1 reação', 0, '1 rodada', NULL, TRUE, TRUE, FALSE, 1, 'Abjuração'),
(146, 'Escudo da Fé', 'Um campo luminoso surge ao redor de uma criatura à sua escolha e no alcance da magia. A criatura ganha um bônus de +2 à CA enquanto esta magia durar.', '1 ação bônus', 18, 'Concentração, até 10 minutos', NULL, TRUE, TRUE, TRUE, 1, 'Abjuração'),
(147, 'Escudo de Fogo', 'Finas e discretas chamas rodeiam seu corpo pela duração, emitindo luz plena em 3 metros de raio e penumbra por mais 3 metros adicionais. Você pode terminar a magia prematuramente usando sua ação para dissipa-la. As chamas lhe conferem um escudo quente ou um escudo frio, à sua escolha. O escudo quente lhe garante resistência a dano de frio e o escudo frio lhe concede resistência a dano de fogo. Além disso, sempre que uma criatura a 1,5 metro de você atingir você com um ataque corpo-a-corpo, o escudo expele chamas. O atacante sofre 2d8 de dano de fogo do escudo quente ou 2d8 de dano de frio do escudo frio.', '1 ação', 0, '10 minutos', '2d8', TRUE, TRUE, TRUE, 4, 'Evocação'),
(148, 'Escuridão', 'Uma esfera de escuridão mágica, com raio de 4,5 metros, se alastra a partir de um ponto à sua escolha, no alcance da magia, e permanece enquanto a magia durar. A escuridão se alastra, contornando os cantos. Uma criatura com visão no escuro não pode ver através dessa escuridão, e uma luz não mágica não a ilumina.', '1 ação', 18, 'Concentração, até 10 minutos', NULL, TRUE, FALSE, TRUE, 2, 'Evocação'),
(149, 'Esfera Congelante de Otiluke', 'Um globo frigido de energia gelada é arremessado das pontas dos seus dedos para um ponto, à sua escolha, dentro do alcance, onde ele explode numa esfera de 18 metros de raio. Cada criatura dentro da área deve realizar um teste de resistência de Constituição. Se falhar na resistência, uma criatura sofre 10d6 de dano de frio. Se obtiver sucesso na resistência, ela sofre metade desse dano. Se o globo atingir um corpo de água ou liquido composto principalmente de água (não incluindo criaturas feitas de água), ele congela o líquido até uma profundidade de 15 centímetros numa área de 9 metros quadrados. Esse gelo dura por 1 minuto. Criaturas que estiverem nadando na superfície de água congelada estarão presas no gelo. Uma criatura presa pode usar sua ação para realizar um teste de Força contra a CD da magia para se libertar. Você pode evitar de disparar o globo após completar a magia, se desejar. Um pequeno globo, do tamanho de uma pedra de funda, frio ao toque, aparece em sua mão. A qualquer momento, você ou uma criatura a quem você entregar o globo, pode arremessa-lo (a uma distância de 12 metros) ou atira-lo com uma funda (ao alcance normal da funda). Ele se despedaça no impacto, produzindo o mesmo efeito da conjuração normal da magia. Você pode, também, soltar o globo no chão sem despedaça-lo. Após 1 minuto, se o globo ainda não tiver se despedaçado, ele explode. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 7° nível ou superior, o dano aumenta em 1d6 para cada nível do espaço acima do 6°.', '1 ação', 90, 'Instantânea', '10d6', TRUE, TRUE, TRUE, 6, 'Evocação'),
(150, 'Esfera Flamejante', 'Uma esfera de fogo, com 1,5 metro de diâmetro, aparece em um espaço desocupado, à sua escolha, dentro do alcance e permanece pela duração. Qualquer criatura que terminar seu turno a até 1,5 metro da esfera, deve realizar um teste de resistência de Destreza. A criatura sofre 2d6 de dano de fogo se falhar na resistência, ou metade desse dano se obtiver sucesso. Com uma ação bônus, você pode mover a esfera até 9 metros. Se você arremessar a esfera contra uma criatura, essa criatura deve realizar o teste de resistência contra o dano da esfera e a esfera para de se mover esse turno. Quando você move a esfera, você pode direciona-la para barreira de até 1,5 metro de altura e ela salta sobre fossos de até 3 metros de distância. A esfera incendeia objetos inflamáveis que não estejam sendo vestidos ou carregados e emite luz plena a 6 metros de raio e penumbra por mais 6 metros adicionais. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 3° nível ou superior, o dano aumenta em 1d6 para cada nível do espaço acima do 2°.', '1 ação', 18, 'Concentração, até 1 minuto', '2d6', TRUE, TRUE, TRUE, 2, 'Conjuração'),
(151, 'Esfera Resiliente de Otiluke', 'Uma esfera de energia cintilante envolve uma criatura ou objeto de tamanho Grande ou menor, no alcance da magia. Uma criatura que estiver na esfera contra a própria vontade deve fazer uma salvaguarda de Destreza. Se falhar, a criatura fica enclausurada enquanto a magia durar. Nada — nem objetos físicos, energia ou outros efeitos mágicos — pode passar através da barreira, para dentro ou fora, embora uma criatura na esfera possa respirar nela. A esfera é imune a todos os danos.', '1 ação', 9, 'Concentração, até 1 minuto', NULL, TRUE, TRUE, TRUE, 4, 'Evocação'),
(152, 'Espada de Mordenkainen', 'Você cria energia moldada na forma de uma espada, que paira dentro do alcance da magia. Ela fica ativa enquanto a magia durar. Quando a espada aparece, você faz um ataque mágico corpo a corpo contra um alvo à sua escolha no alcance de 1,5 metro da espada. Ao desferir um ataque bem-sucedido, o alvo sofre 3d10 pontos de dano energético. Enquanto a magia durar, você pode usar uma ação bônus em cada um de seus turnos para movê-la até 6 metros para um local à sua vista, repetindo esse ataque contra o mesmo alvo ou outro.', '1 ação', 18, 'Concentração, até 1 minuto', '3d10', TRUE, TRUE, TRUE, 7, 'Evocação'),
(153, 'Espíritos Guardiões', 'Você evoca espíritos para protege-lo. Eles flutuam a seu redor, a uma distância de 4,5 metros, pela duração. Se você for bom ou neutro, as formas espectrais deles aparenta ser angelical ou feérica (à sua escolha). Se você for mau, eles pareceram demoníacos. Quando você conjura essa magia, você pode designar qualquer quantidade de criaturas que você possa ver para não serem afetadas por ela. O deslocamento de uma criatura afetada é reduzido à metade na área e, quando a criatura entrar na área pela primeira vez num turno ou começar seu turno nela, ela deve realizar um teste de resistência de Sabedoria. Se falhar na resistência, a criatura sofrerá 3d8 de dano radiante (se você for bom ou neutro) ou 3d8 de dano necrótico (se você for mau). Com um sucesso na resistência, a criatura sofre metade desse dano. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 4° nível ou superior, o dano aumenta em 1d8 para cada nível do espaço acima do 3°.', '1 ação', 0, 'Concentração, até 10 minutos', '3d8', TRUE, TRUE, TRUE, 3, 'Conjuração'),
(154, 'Espirro Ácido', 'Você lança uma bolha de ácido. Escolha uma ou duas criaturas à sua vista, dentro do alcance da magia. Se escolher duas, elas devem estar a 1,5 metro uma da outra. O alvo deve ser bem-sucedido em uma salvaguarda de Destreza. Se falhar, sofre 1d6 pontos de dano ácido. O dano desta magia aumenta em 1d6 quando você alcança o 5° nível (2d6), o 11° nível (3d6) e o 17° nível (4d6).', '1 ação', 18, 'Instantânea', '1d6', TRUE, TRUE, FALSE, 0, 'Conjuração'),
(155, 'Esquentar Metal', 'Escolha uma objeto manufaturado de metal, como uma arma de metal ou uma armadura pesada ou média de metal, que você possa ver dentro do alcance. Você faz com que o objeto brilhe vermelho-incandescente. Qualquer criatura em contato físico com o objeto sofrerá 2d8 de dano de fogo quando você conjurar a magia. Até a magia acabar, você pode usar uma ação bônus, em cada um dos seus turnos subsequentes, para causar esse dano novamente. Se uma criatura estiver segurando ou vestindo o objeto e sofrer o dano dele, a criatura deve ser bem sucedida num teste de resistência de Constituição ou largará o objeto se ela puder. Se ela não largar o objeto, ela terá desvantagem em jogadas de ataque e testes de habilidade até o início do seu próximo turno. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 3° nível ou superior, o dano aumenta em 1d8 para cada nível do espaço acima do 2°.', '1 ação', 18, 'Concentração, até 1 minuto', '2d8', TRUE, TRUE, TRUE, 2, 'Transmutação'),
(156, 'Estabilizar', 'Toca uma criatura com 0 PV para estabilizá-la imediatamente.', '1 ação', 1, 'Instantânea', NULL, TRUE, TRUE, FALSE, 0, 'Necromancia'),
(157, 'Explosão Solar', 'Luz solar brilhante lampeja em um raio de 18 metros, centrada em um ponto à sua escolha e no alcance da magia. Cada criatura dentro da área da luz deve fazer uma salvaguarda de Constituição. Se falhar, sofre 12d6 pontos de dano radiante e fica cega durante 1 minuto. Em caso de sucesso, ela sofre metade do dano e não fica cega. Mortos-vivos e gosmas têm desvantagem nesta salvaguarda.', '1 ação', 45, 'Instantânea', '12d6', TRUE, TRUE, TRUE, 8, 'Evocação'),
(158, 'Fabricar', 'Você transforma matérias-primas em produtos do mesmo material. Por exemplo, você pode fabricar uma ponte de madeira a partir de um monte de árvores, uma corda a partir de um pedaço de cânhamo, e roupas a partir do linho ou lã. Escolha uma matéria-prima à sua vista e no alcance da magia; você pode fabricar um objeto de tamanho Grande ou menor, desde que haja matéria-prima suficiente.', '10 minutos', 36, 'Instantânea', NULL, TRUE, TRUE, FALSE, 4, 'Transmutação'),
(159, 'Falar com Animais', 'Você adquire a habilidade de compreender e se comunicar verbalmente com feras enquanto a magia durar. O conhecimento e a consciência são limitados pela inteligência delas mas, no mínimo, são capazes de dar informação sobre localidades e monstros próximos, incluindo tudo o que notam ou notaram nas últimas 24 horas.', '1 ação', 0, '10 minutos', NULL, TRUE, TRUE, FALSE, 1, 'Adivinhação'),
(160, 'Falar com os Mortos', 'Você concede um arremedo de vida e inteligência a um cadáver à sua escolha, no alcance da magia, permitindo-lhe responder às perguntas feitas a ele. O cadáver ainda deve ter uma boca e não pode ser um morto-vivo.', '1 ação', 3, '10 minutos', NULL, TRUE, TRUE, TRUE, 3, 'Necromancia'),
(161, 'Falar com Plantas', 'Você é capaz de imbuir plantas a até 9 metros de distância com intelecto limitado e razão, dando-lhes a habilidade de se comunicar e seguir comandos simples. Podem ser feitas perguntas a elas sobre eventos até o dia anterior, na área ao redor.', '1 ação', 0, '10 minutos', NULL, TRUE, TRUE, FALSE, 3, 'Transmutação'),
(162, 'Flecha Ácida de Melf', 'Uma flecha esverdeada cintilante voa em direção de um alvo dentro do alcance e explode em um jato de ácido. Faça um ataque à distância com magia contra o alvo. Se atingir, o alvo sofre 4d4 de dano de ácido imediatamente e 2d4 de dano de ácido no final do próximo turno dele. Se errar, a flecha salpica o alvo com ácido, causando metade do dano inicial e nenhum dano no final do próximo turno dele. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 3° nível ou superior, o dano (tanto inicial quanto posterior) aumenta em 1d4 para cada nível do espaço acima do 2°.', '1 ação', 36, 'Instantânea', '4d4', TRUE, TRUE, TRUE, 2, 'Evocação'),
(163, 'Flecha Relampejante', 'Da próxima vez que você realizar um ataque com uma arma à distância enquanto a magia durar, a munição da arma ou a própria arma, se ela for uma arma de arremesso, se transforma num relâmpago. Realize uma jogada de ataque normal. O alvo sofre 4d8 de dano elétrico se atingir ou metade desse dano se errar, ao invés do dano normal da arma. Independentemente de você acertar ou errar, cada criatura a até 3 metros do alvo deve realizar um teste de resistência de Destreza. Cada uma dessas criaturas sofre 2d8 de dano elétrico se falhar na resistência ou metade desse dano se obtiver sucesso. A munição ou arma então, volta a sua forma normal. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 4° nível ou superior, o dano de ambos os efeitos da magia aumenta em 1d8 para cada nível do espaço acima do 3°.', '1 ação bônus', 0, 'Concentração, até 1 minuto', '4d8', TRUE, TRUE, FALSE, 3, 'Transmutação'),
(164, 'Fogo das Fadas', 'Todos os objetos em um cubo de 6 metros no alcance da magia se tornam delineados por uma luz azul, verde ou violeta (à sua escolha). Qualquer criatura que esteja na área quando a magia for conjurada também é delineada pela luz, caso falhe em uma salvaguarda de Destreza. Enquanto a magia durar, objetos e criaturas afetadas por ela emitem uma luz tênue, criando meia-luz em um raio de 3 metros. Qualquer jogada de ataque contra uma criatura ou objeto afetado tem vantagem, caso o atacante possa vê-los.', '1 ação', 18, 'Concentração, até 1 minuto', NULL, TRUE, FALSE, FALSE, 1, 'Evocação'),
(165, 'Fome de Hadar', 'Você abre um portal para a escuridão entre as estrelas, uma região infestada de horrores desconhecidos. Uma esfera de 6 metros de raio de negritude e frio severo aparece, centrada num ponto dentro do alcance, e permanece pela duração. Esse vazio está preenchido por uma cacofonia de sussurros suaves e barulhos de rangidos que podem ser ouvidos a até 9 metros. Nenhuma luz, mágica ou qualquer que seja, pode iluminar a área e as criaturas totalmente dentro da área estarão cegas. O vazio cria uma dobra no tecido do espaço e a área é de terreno difícil. Qualquer criatura que começar seu turno na área sofre 2d6 de dano de frio. Qualquer criatura que terminar seu turno na área, deve ser bem sucedida num teste de resistência de Destreza ou sofrerá 2d6 de dano de ácido, à medida que tentáculos leitosos extraterrestres se esfregam contra ela.', '1 ação', 45, 'Concentração, até 1 minuto', '2d6', TRUE, TRUE, TRUE, 3, 'Conjuração'),
(166, 'Força Fantasmagórica', 'Você constrói uma ilusão que se enraíza na mente de uma criatura que você possa ver, dentro do alcance. O alvo deve realizar um teste de resistência de Inteligência. Se falhar na resistência, você cria um objeto, criatura ou outro fenômeno visível – porém, fantasmagórico – à sua escolha, com não mais de 3 metros cúbicos e que será percebido apenas pelo alvo, pela duração. Essa magia não afeta mortos-vivos ou constructos. O fantasma inclui som, temperatura e outros estímulos, também evidentes apenas para o alvo. O alvo pode usar sua ação para examinar o fantasma com um teste de Inteligência (Investigação) contra a CD da as magia. Se for bem sucedido, o alvo percebe que o fantasma é uma ilusão e a magia acaba. Enquanto o alvo estiver sob efeito dessa magia, ele considerará o fantasma como sendo real. O alvo racionalizará quaisquer resultados ilógicos ao interagir com o fantasma. Por exemplo, um alvo tentado atravessar uma ponte fantasmagórica que atravesse um abismo, cairá quando pisar na ponte. Se o alvo sobreviver a queda, ele ainda acreditará que a ponte existe e procurará outra explicação para a sua queda – ele foi puxado, ele escorregou ou um vento forte pode ter o jogado pra fora. Um alvo afetado está tão convencido da realidade do fantasma que pode até mesmo sofrer dano da ilusão. Um fantasma criado para se parecer com uma criatura pode atacar o alvo. Similarmente, um fantasma criado para se parecer com fogo, um poço de ácido ou lava, podem queimar o alvo. A cada rodada, no seu turno, o fantasma pode causar 1d6 de dano psíquico no alvo, se ele estiver na área do fantasma ou a 1,5 metro dele, considerando que a ilusão é de uma criatura ou perigo que, logicamente, possa causar dano, como por atacar. O alvo entende o dano como sendo de um tipo apropriado para a ilusão.', '1 ação', 18, 'Concentração, até 1 minuto', '1d6', TRUE, TRUE, TRUE, 2, 'Ilusão'),
(167, 'Forjar Morte', 'Você toca uma criatura voluntária e a coloca em um estado catatônico que é indistinguível da morte. Pela duração da magia, ou até você usar uma ação para tocar o alvo e dissipar a magia, o alvo aparenta estar morto para todas as inspeções externas e para magias usadas para determinar a condição do alvo. O alvo está cego e incapacitado e seu deslocamento cai para 0. O alvo tem resistência a todos os danos, exceto dano psíquico. Se o alvo estava doente ou envenenado quando você conjurou a magia, ou ficou doente ou envenenado durante o período em que estava sob efeito da magia, a doença e veneno não terá qualquer efeito até a magia terminar.', '1 ação', 1, '1 hora', NULL, TRUE, TRUE, TRUE, 3, 'Necromancia'),
(168, 'Forma Etérea', 'Você dá um passo para dentro das fronteiras do Plano Etéreo, na área em que ele se sobrepõem com o seu plano atual. Você se mantem na Fronteira Etérea pela duração ou até você usar sua ação para dissipar a magia. Durante esse período, você pode se mover para qualquer direção. Se você se mover para cima ou para baixo, cada passo de deslocamento custa um passo extra. Você pode ver e ouvir o plano que você se originou, mas tudo parece cinzento e você não pode ver nada além de 18 metros de você. Enquanto estiver no Plano Etéreo, você pode afetar e ser afetado apenas por criaturas nesse plano. As criaturas que não estiverem no Plano Etéreo não podem notar sua presença e não podem interagir com você, a menos que uma habilidade especial ou magia dê a elas a capacidade de fazê-lo. Você ignora todos os objetos e efeitos que não estiverem no Plano Etéreo, permitindo que você se mova através de objetos que você perceba no plano de onde você veio. Quando a magia acabar, você imediatamente retorna para o plano de onde você se originou, no lugar que você está ocupando atualmente. Se você estiver ocupando o mesmo espaço de um objeto sólido ou de uma criatura quando isso ocorrer, você é, imediatamente, desviado para o espaço desocupado mais próximo que você puder ocupar e sofre dano de energia igual a dez vezes a quantidade de quadrados de 1,5 metro que você foi movido. Essa magia não tem efeito se você conjura-la enquanto estiver no Plano Etéreo ou um plano que não faça fronteira com ele, como um dos Planos Exteriores. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 8° nível ou superior, você pode afetar até três criaturas voluntária (incluindo você) para cada nível do espaço acima do 7°. As criaturas devem estar a até 3 metros de você quando você conjurar a magia.', '1 ação', 0, 'Até 8 horas', NULL, TRUE, TRUE, FALSE, 7, 'Transmutação'),
(169, 'Forma Gasosa', 'Você toca uma criatura voluntária. O alvo, junto com tudo aquilo que estiver usando e carregando, é transformado em uma nuvem de neblina, enquanto a magia durar. A magia termina se os pontos de vida da criatura forem reduzidos a 0.', '1 ação', 1, 'Concentração, até 1 hora', NULL, TRUE, TRUE, TRUE, 3, 'Transmutação'),
(170, 'Formas Animais', 'Sua magia transforma você em bestas. Escolha qualquer quantidade de criaturas voluntárias que você possa ver, o alcance. Você muda cada alvo para a forma de uma besta Grande ou menor, com um nível de desafio de 4 ou inferior. Nos turnos subsequentes, você pode usar sua ação para mudar uma criatura afetada para uma nova forma. A transformação permanece pela duração para cada alvo, ou até o alvo cair para 0 pontos de vida ou morrer. Você pode escolher uma forma diferente para cada alvo. As estatísticas de jogo do alvo são substituídas pelas estatísticas da besta escolhida, mas o alvo mantem sua tendência e valores de Inteligência, Sabedoria e Carisma. O alvo adquire os pontos de vida da sua nova forma, e quando ele reverte para sua forma normal, ele volta aos pontos de vida que tinha antes de ser transformado. Se ele reverter como resultado de ter caído a 0 pontos de vida, todo dano excedente é recebido pela sua forma normal. Contanto que o dano excedente não reduza os pontos de vida da forma normal da criatura a 0, ela não cairá inconsciente. A criatura é limitada em suas ações pela natureza da sua nova forma e ela não pode falar nem conjurar magias. O equipamento do alvo mescla-se a sua nova forma. O alvo não pode ativar, empunhar ou, de outra forma, se beneficiar de qualquer de seus equipamentos.', '1 ação', 9, 'Concentração, até 24 horas', NULL, TRUE, TRUE, FALSE, 8, 'Transmutação'),
(171, 'Glifo de Vigilância', 'Quando você conjura essa magia, você inscreve um glifo não necessariamente nocivo, tanto sobre uma superfície (como uma mesa ou uma secção de piso ou parede) quanto dentro de um objeto que possa ser fechado (como um livro, um pergaminho ou um baú de tesouro) para ocultar o glifo. O glifo pode cobrir uma área que não seja superior a 3 metros de diâmetro. Se a superfície ou objeto for movido mais de 3 metros de onde você conjurou essa magia, o glifo se quebra e a magia termina sem ser ativada. O glifo é quase invisível e requer um teste de Inteligência (Investigação) contra a CD da magia para ser encontrado. Você define o que ativa o glifo quando você conjura a magia. Para glifos inscritos em uma superfície, os gatilhos mais típicos incluem tocar ou ficar sobre o glifo, remover outro objeto cobrindo o glifo, aproximar-se a uma certa distância do glifo ou manipular um objeto onde o glifo esteja inscrito. Para glifos inscritos dentro de objetos, os gatilhos mais comuns incluem abrir o objeto, aproximar se a uma certa distância do objeto ou ver ou ler o glifo. Uma vez que o glifo seja ativado, a magia termina. Você pode, posteriormente, aperfeiçoar o gatilho para que a magia se ative apenas sob certas circunstâncias ou de acordo com as características físicas (como altura ou peso), tipo de criatura (por exemplo, a proteção poderia ser definida para afetar aberrações ou drow) ou tendência. Você pode, também, definir condições para criaturas não ativarem o glifo, como aqueles que falarem determinada senha. Quando você inscreve o glifo, escolha runas explosivas ou glifo de magia. Runas Explosivas. Quando ativado, o glifo irrompe com energia mágica numa esfera com 6 metros de raio, centrada no glifo. A esfera se espalha, dobrando esquinas. Cada criatura na área deve realizar um teste de resistência de Destreza. Uma criatura sofre 5d8 de dano de ácido, elétrico, fogo, frio ou trovejante se falhar no teste de resistência (você escolhe o tipo quando cria o glifo) ou metade desse dano se obtiver sucesso. Glifo de Magia. Você pode armazenar uma magia preparada de 3° nível ou inferior no glifo ao conjura-la como parte da criação do glifo. A magia a ser armazenada não tem efeito imediato quando conjurada dessa forma. Quando o glifo for ativado, a magia armazenada é conjurada. Se a magia tiver um alvo, esse alvo será a criatura que ativou o glifo. Se a magia afetar uma área, a área será centrada na criatura. Se a magia invocar criaturas hostis ou criar objetos ou armadilhas nocivos, eles aparecerão o mais próximo possível do intruso e o atacarão. Se a magia precisar de concentração, ela dura o máximo possível da sua duração. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 4° nível ou superior, o dano do glifo de runas explosivas aumenta em 1d8 para cada nível do espaço acima do 3°. Se você criar um glifo de magia, você pode armazenar qualquer magia do mesmo nível, ou inferior, do espaço que você usar para o glifo de vigilância.', '1 hora', 1, 'Até ser dissipada', '5d8', TRUE, TRUE, TRUE, 3, 'Abjuração'),
(172, 'Globo de Invulnerabilidade', 'Uma barreira imóvel, levemente cintilante, surge do nada num raio de 3 metros centrado em você e permanece pela duração. Qualquer magia de 5° nível ou inferior conjurada de fora da barreira não poderá afetar as criaturas ou objetos dentro dela, mesmo que a magia seja conjurada usando um espaço de magia de nível superior. Tais magias podem ter como alvo criaturas e objetos dentro da barreira, mas a magia não produz nenhum efeito neles. Similarmente, a área dentro da barreira é excluída das áreas afetadas por tais magias. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 7° nível ou superior, a barreira bloqueia magias de um nível superior para cada nível do espaço acima do 6°.', '1 ação', 0, 'Concentração, até 1 minuto', NULL, TRUE, TRUE, TRUE, 6, 'Abjuração'),
(173, 'Globos de Luz', 'Você cria até quatro luzes no alcance da magia, fazendo com que se pareçam com tochas, lanternas ou globos brilhantes que pairam no ar por toda a duração da magia. Você também pode combinar as quatro luzes para que brilhem em uma forma vagamente humanoide de tamanho Médio. Qualquer que seja a forma escolhida, cada luz emite meia-luz em um raio de 3 metros. Com uma ação bônus em seu turno, você pode mover as luzes até 18 metros para um novo lugar dentro do alcance da magia.', '1 ação', 36, 'Concentração, até 1 minuto', NULL, TRUE, TRUE, TRUE, 0, 'Evocação'),
(174, 'Golpe Constritor', 'Da próxima vez que você atingir uma criatura com um ataque com arma, antes do final da magia, um emaranhado maciço de vinhas espinhentas aparecem no local do impacto e o alvo deve ser bem sucedido num teste de resistência de Força ou ficará impedido pelas vinhas mágicas, até o fim da magia. Uma criatura Grande ou maior tem vantagem no seu teste de resistência. Se o alvo for bem sucedido na resistência, as vinhas murcharão. Enquanto estiver impedido pela magia, um alvo sofre 1d6 de dano perfurante no início de cada um dos turnos dele. Uma criatura impedida pelas vinhas ou uma que possa tocar a criatura, pode usar sua ação para realizar um teste de Força contra a CD da magia. Num sucesso, o alvo é libertado. Em Níveis Superiores. Se você conjurar essa magia usando um espaço de magia de 2° nível ou superior, o dano aumenta em 1d6 para cada nível do espaço acima do 1°.', '1 ação bônus', 0, 'Concentração, até 1 minuto', '1d6', TRUE, FALSE, FALSE, 1, 'Conjuração'),
(175, 'Guardião da Fé', 'Um guardião espectral Grande aparece e flutua, pela duração, em um espaço desocupado, à sua escolha, que você possa ver dentro do alcance. O guardião ocupa esse espaço e é indistinto, exceto por uma espada reluzente e um escudo brasonado com o símbolo da sua divindade. Qualquer criatura hostil a você que se mover para um espaço a até 3 metros do guardião pela primeira vez em um turno, deve ser bem sucedida num teste de resistência de Destreza. A criatura sofre 20 de dano radiante se falhar na resistência ou metade desse dano se obtiver sucesso. O guardião desaparece após ter causado um total de 60 de dano.', '1 ação', 9, '8 horas', '20', TRUE, FALSE, FALSE, 4, 'Conjuração'),
(176, 'Heroísmo', 'Uma criatura voluntária que você tocar é imbuída com bravura. Até a magia acabar, a criatura é imune a ser amedrontada e ganha pontos de vida temporários igual ao seu modificador de habilidade de conjuração, no início de cada turno dela. Quando a magia acabar, o alvo perde qualquer ponto de vida temporário restante dessa magia. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 2° nível ou superior, você pode afetar uma criatura adicional para cada nível do espaço acima do 1°.', '1 ação', 1, 'Concentração, até 1 minuto', NULL, TRUE, TRUE, FALSE, 1, 'Encantamento'),
(177, 'Identificação', 'Escolha um objeto que você deve tocar durante a conjuração da magia. Se for um item mágico ou algum outro tipo de objeto imbuído de magia, você descobre as propriedades dele e como usá-las, se ele exige sintonização para ser usado e quantas cargas tem, caso as tenha. Você também descobre se alguma magia está afetando o objeto e que magia é essa.', '1 minuto', 1, 'Instantânea', NULL, TRUE, TRUE, TRUE, 1, 'Adivinhação'),
(178, 'Idiomas', 'A magia concede a uma criatura que você toque a habilidade de compreender e falar qualquer idioma que ela escute. Além disso, quando o alvo falar, qualquer criatura que conheça ao menos um idioma e consiga ouvi-lo, compreende o que ele diz.', '1 ação', 1, '1 hora', NULL, TRUE, FALSE, TRUE, 3, 'Adivinhação'),
(179, 'Ilusão Menor', 'Você cria um som ou uma imagem de um objeto ao alcance da magia, que permanece enquanto esta durar. A ilusão termina se você a dispensar com uma ação ou conjurá-la novamente.', '1 ação', 9, '1 minuto', NULL, FALSE, FALSE, TRUE, 0, 'Ilusão'),
(180, 'Ilusão Programada', 'Você cria uma ilusão de um objeto, uma criatura ou de algum outro fenômeno visível, dentro do alcance, que se ativa quando uma condição especifica ocorre. A ilusão é imperceptível até esse momento. Ela não pode ter mais de 9 metros cúbicos e você decide, quando conjura a magia, como a ilusão se comporta e quais sons ela faz. Essa performance roteirizada por durar até 5 minutos. Quando a condição que você especificou ocorrer, a ilusão surge do nada e age da maneira que você descreveu. Uma vez que a ilusão tenha acabado de agir, ela desaparece e permanece dormente por 10 minutos. Após desse período, a ilusão pode se ativar novamente. A condição de ativação pode ser tão genérica ou tão detalhada quando você quiser, apesar de ela precisar ser baseada em condições visuais ou audíveis que ocorram a até 9 metros da área. Por exemplo, você poderia criar uma ilusão, de si mesmo, que aparecerá e avisará a outros que tentarem abrir a porta com armadilha ou você pode programar a ilusão para se ativar apenas quando uma criatura disser a palavra ou frase correta. Interação física com a imagem revelará ela como sendo uma ilusão, já que as coisas podem atravessa-la. Uma criatura que usar sua ação para examinar a imagem, pode determinar que ela é uma ilusão sendo bem sucedida num teste de Inteligência (Investigação) contra a CD da magia para desacredita-la. Se a criatura discernir a ilusão como ela é, a criatura poderá ver através da imagem e qualquer barulho que ela fizer soará oco para a criatura.', '1 ação', 36, 'Até ser dissipada', NULL, TRUE, TRUE, TRUE, 6, 'Ilusão'),
(181, 'Imagem Maior', 'Você cria uma imagem de um objeto, uma criatura ou algum outro fenômeno visível que não tenha mais de 6 metros cúbicos. A imagem aparece em um local que você possa ver, dentro do alcance e permanece pela duração. Ela parece completamente real, incluindo sons, cheiros e temperatura apropriados para a coisa retratada. Você não pode criar calo ou frio suficiente para causar dano, um som alto o suficiente para causar dano trovejante ou ensurdecer uma criatura ou um cheiro que poderia nausear uma criatura (como o fedor de um troglodita). Enquanto você estiver dentro do alcance da ilusão, você pode usar sua ação pra fazer a imagem se mover para qualquer outro local dentro do alcance. À medida que a imagem muda de lugar, você pode alterar a aparência dela para que seu movimento pareça ser o natural para a imagem. Por exemplo, se você criar uma imagem de uma criatura e move-la, você pode alterar a imagem para que ela pareça estar andando. Similarmente, você pode fazer a ilusão emitir sons diferentes em momentos diferentes, sendo possível até mesmo manter uma conversa, por exemplo. Interação física com a imagem, revelará que ela é uma ilusão, já que as coisas podem passar através dela. Uma criatura que usar sua ação para examinar a imagem, pode determinar que ela é uma ilusão com um teste de Inteligência (Investigação) bem sucedido contra a CD da magia. Se uma criatura discernir a ilusão como sendo isso, a criatura verá através da imagem e suas outras qualidades sensoriais se tornaram suaves para a criatura. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 6° nível ou superior, a magia irá durar até ser dissipada, sem necessitar da sua concentração.', '1 ação', 36, 'Concentração, até 10 minutos', NULL, TRUE, TRUE, TRUE, 3, 'Ilusão'),
(182, 'Imagem Silenciosa', 'Você cria a imagem de um objeto, criatura ou algum fenômeno visual que não seja maior do que um cubo de 4,5 metros. A imagem surge em um lugar no alcance da magia e permanece enquanto esta durar. A imagem é puramente visual; ela não é acompanhada de som, cheiro ou outros efeitos sensoriais. Você pode usar sua ação para fazer a imagem se deslocar para qualquer lugar dentro do alcance da magia, alterando sua aparência para que os movimentos pareçam naturais. Interação física com a imagem revela que ela é uma ilusão, pois coisas podem passar através dela.', '1 ação', 18, 'Concentração, até 10 minutos', NULL, TRUE, TRUE, TRUE, 1, 'Ilusão'),
(183, 'Imobilizar Monstro', 'Escolha uma criatura que você possa ver, dentro do alcance. O alvo deve ser bem sucedido num teste de resistência de Sabedoria ou ficará paralisado pela duração. Essa magia não tem efeito em mortos-vivos. No final de cada um dos turnos dele, o alvo pode realizar outro teste de resistência de Sabedoria. Se obtiver sucesso, a magia termina no alvo. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 6° nível ou superior, você pode afetar uma criatura adicional para cada nível de magia acima do 5°. As criaturas devem estar a 9 metros entre si para serem afetadas.', '1 ação', 27, 'Concentração, até 1 minuto', NULL, TRUE, TRUE, TRUE, 5, 'Encantamento'),
(184, 'Imobilizar Pessoa', 'Escolha um humanoide que você possa ver, dentro do alcance. O alvo deve ser bem sucedido num teste de resistência de Sabedoria ou ficará paralisado pela duração. Essa magia não tem efeito em mortos-vivos. No final de cada um dos turnos dele, o alvo pode realizar outro teste de resistência de Sabedoria. Se obtiver sucesso, a magia termina no alvo. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 3° nível ou superior, você pode afetar um humanoide adicional para cada nível de magia acima do 2°. Os humanoides devem estar a 9 metros entre si para serem afetados.', '1 ação', 18, 'Concentração, até 1 minuto', NULL, TRUE, TRUE, TRUE, 2, 'Encantamento'),
(185, 'Infligir Ferimentos', 'Faça um ataque corpo-a-corpo com magia contra uma criatura dentro do alcance. Se atingir, o alvo sofre 3d10 de dano necrótico. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 2° nível ou superior, o dano aumenta em 1d10 para cada nível acima do 1°.', '1 ação', 1, 'Instantânea', '3d10', TRUE, TRUE, FALSE, 1, 'Necromancia'),
(186, 'Inseto Gigante', 'Você transforma até dez centopeias, três aranhas, cinco vespas ou um escorpião no alcance da magia em versões gigantes de suas formas naturais, enquanto a magia durar. Uma centopeia torna-se uma centopeia gigante, uma aranha torna-se uma aranha gigante, uma vespa torna-se uma vespa gigante e um escorpião torna-se um escorpião gigante. Cada criatura obedece aos seus comandos verbais.', '1 ação', 9, 'Concentração, até 10 minutos', NULL, TRUE, TRUE, FALSE, 4, 'Transmutação'),
(187, 'Inverter a Gravidade', 'Esta magia inverte a gravidade numa área de 15 metros de raio e 30 metros de altura, formando um cilindro centrado em um ponto no alcance da magia. Todas as criaturas e objetos que não estão, de alguma forma, ancorados ao solo nessa área, caem para cima e alcançam o topo da área quando a magia é conjurada. Uma criatura pode fazer uma salvaguarda de Destreza para se agarrar a um objeto fixo que possa alcançar, evitando a queda. Se algum objeto sólido (como um teto) for encontrado durante esta queda, criaturas e objetos caindo se chocam contra ele, como fariam durante uma queda normal.', '1 ação', 30, 'Concentração, até 1 minuto', NULL, TRUE, TRUE, TRUE, 7, 'Transmutação'),
(188, 'Invisibilidade', 'Uma criatura que você tocar, se torna invisível até a magia acabar. Qualquer coisa que o alvo esteja vestindo ou carregando fica invisível enquanto estiver de posse do alvo. A magia termina para o alvo caso ele ataque ou conjure uma magia. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 3° nível ou superior, você pode afetar um alvo adicional para cada nível do espaço acima do 2°.', '1 ação', 1, 'Concentração, até 1 hora', NULL, TRUE, TRUE, TRUE, 2, 'Ilusão'),
(189, 'Invisibilidade Maior', 'Você ou uma criatura tocada por você torna-se invisível enquanto a magia durar. Qualquer coisa que o alvo estiver usando ou carregando também se torna invisível, enquanto estiver em sua posse.', '1 ação', 1, 'Concentração, até 1 minuto', NULL, TRUE, TRUE, FALSE, 4, 'Ilusão'),
(190, 'Invocação Instantânea de Drawmij', 'Você toca um objeto pesando 5 quilos ou menos com maior dimensão de 1,8 metro ou menos. A magia deixa uma marca invisível na sua superfície e grava invisivelmente o nome do item na safira que você usou como componente material. A cada vez que você conjurar essa magia, você deve usar uma safira diferente. A qualquer momento, posteriormente, você pode usar sua ação para falar o nome do item e esmagar a safira. O item aparece instantaneamente em suas mãos, independentemente de distâncias físicas ou planares, e a magia termina. Se outra criatura estiver segurando ou carregando o item, esmagar a safira não irá transportar o item até você, ao invés disso, você descobre quem é a criatura possuindo o objeto e onde, vagamente, a criatura está localizada no momento. Dissipar magia ou um efeito similar aplicado com sucesso na safira, termina o efeito da magia.', '1 minuto', 1, 'Até ser dissipada', NULL, TRUE, TRUE, TRUE, 6, 'Conjuração'),
(191, 'Isolamento', 'Através dessa magia, uma criatura voluntária ou um objeto, pode ser escondido, seguro contra detecção pela duração. Quando você conjura essa magia e toca o alvo, ele fica invisível e não pode ser alvo de magias de adivinhação ou percebido através de sensores de vidência criados por magias de adivinhação. Se o alvo for uma criatura, ela entra num estado de animação suspensa. O tempo para de fluir para ela e ela não envelhece. Você pode determinar uma condição para que a magia termine prematuramente. A condição pode ser qualquer coisa, à sua escolha, mas deve ocorrer ou ser visível a até 1,5 quilômetro do alvo. Exemplos incluem “depois de 1.000 anos” ou “quando o tarrasque despertar”. Essa magia também acaba se o alvo sofrer qualquer dano.', '1 ação', 1, 'Até ser dissipada', NULL, TRUE, TRUE, TRUE, 7, 'Transmutação'),
(192, 'Labirinto', 'Você bane uma criatura que você possa ver, dentro do alcance, para um semiplano labiríntico. O alvo permanece lá pela duração ou até escapar do labirinto. O alvo pode usar sua ação para tentar escapar. Quando o fizer, ele realiza um teste de Inteligência com CD 20. Se for bem sucedido, ele escapa e a magia termina (um minotauro ou um demônio goristro, obtém sucesso automaticamente). Quando a magia termina, o alvo reaparece no espaço que ela estava ou, se o espaço estiver ocupado, no espaço desocupado mais próximo.', '1 ação', 18, 'Concentração, até 10 minutos', NULL, TRUE, TRUE, FALSE, 8, 'Conjuração'),
(193, 'Lâmina Flamejante', 'Você evoca uma lâmina ardente em sua mão livre. A lâmina é similar em tamanho e formato a uma cimitarra e ela permanece pela duração. Se você soltar a lâmina, ela desaparece, mas você pode evocar a lâmina novamente com uma ação bônus. Você pode usar sua ação para realizar ataques corpo-a corpo com magia com a lâmina ardente. Se atingir, o alvo sofrerá 3d6 de dano de fogo. A lâmina flamejante emite luz plena a 3 metros de raio e penumbra por mais 3 metros adicionais. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 4° nível ou superior, o dano aumenta em 1d6 para cada dois níveis do espaço acima do 2°.', '1 ação bônus', 0, 'Concentração, até 10 minutos', '3d6', TRUE, TRUE, TRUE, 2, 'Evocação'),
(194, 'Lentidão', 'Você altera o tempo ao redor para até seis criaturas à sua escolha em um cubo de 12 metros no alcance da magia. Cada alvo deve ser bem-sucedido em uma salvaguarda de Sabedoria ou sofre os efeitos enquanto a magia durar. Um alvo afetado tem seu deslocamento reduzido à metade, tem uma penalidade de -2 em sua CA e salvaguardas de Destreza, e não pode usar reações. No turno dele, ele pode usar uma ação ou ação bônus, mas não ambas.', '1 ação', 36, 'Concentração, até 1 minuto', NULL, TRUE, TRUE, TRUE, 3, 'Transmutação'),
(195, 'Leque Cromático', 'Um feixe ofuscante de luzes coloridas ordenadas, surge da sua mão. Role 6d10; o total é a quantidade de pontos de vida de criaturas que essa magia pode afetar. As criaturas num cone de 4,5 metros, originado de você, são afetadas em ordem ascendente dos seus pontos de vida (ignorando criaturas inconsciente e que não podem ver). Começando com as criaturas que tiverem menos pontos de vida, cada criatura afetada por essa magia ficará cega até o fim da magia. Subtraia os pontos de vida de cada criatura do total antes de considerar os pontos de vida da próxima criatura. Os pontos de vida de uma criatura devem ser iguais ou menores que o total restante para que essa criatura seja afetada Em Níveis Superiores. Se você conjurar essa magia usando um espaço de magia de 2° nível ou superior, jogue 2d10 adicionais para cada nível do espaço acima do 1°.', '1 ação', 0, '1 rodada', NULL, TRUE, TRUE, TRUE, 1, 'Ilusão'),
(196, 'Levitação', 'Escolha uma criatura ou objeto à sua vista e no alcance da magia. O alvo sobe verticalmente a até 6 metros de altura, permanecendo suspenso enquanto a magia durar. A magia pode levitar um alvo que pese até 225 quilos. Uma criatura involuntária que seja bem-sucedida em uma salvaguarda de Constituição não é afetada. O alvo pode se mover apenas ao empurrar ou puxar um objeto fixo ou superfície ao alcance dele.', '1 ação', 18, 'Concentração, até 10 minutos', NULL, TRUE, TRUE, TRUE, 2, 'Transmutação'),
(197, 'Ligação Telepática de Rary', 'Você forja uma ligação telepática entre até oito criaturas voluntárias, à sua escolha, dentro do alcance, ligando psiquicamente cada criatura a todas as outras, pela duração. Criaturas com valores de Inteligência 2 ou menos não são afetadas por essa magia. Até a magia acabar, os alvos podem se comunicar telepaticamente através do elo, independentemente de terem ou não um idioma em comum. A comunicação é possível a qualquer distância, apesar de não se estender a outros planos de existência.', '1 ação', 9, '1 hora', NULL, TRUE, TRUE, TRUE, 5, 'Adivinhação'),
(198, 'Limpar a Mente', 'Enquanto a magia durar, uma criatura voluntária que você toque fica imune a dano psíquico, a qualquer efeito capaz de sentir suas emoções ou ler seus pensamentos, a magias de adivinhação e à condição enfeitiçado. A magia pode até mesmo evitar a magia desejo e magias ou efeitos de poder semelhante usadas para afetar a mente do alvo ou para obter informação sobre ele.', '1 ação', 1, '24 horas', NULL, TRUE, TRUE, FALSE, 8, 'Abjuração'),
(199, 'Localizar Animais ou Plantas', 'Descreva ou nomeie um tipo específico de animal ou planta. Concentrando-se na voz da natureza ao seu redor, você descobre a direção e a distância (até 1,5 quilômetro) em que a criatura ou planta mais próxima daquele tipo se encontra, caso exista alguma na área.', '1 ação', 0, 'Instantânea', NULL, TRUE, TRUE, TRUE, 2, 'Adivinhação'),
(200, 'Localizar Criatura', 'Descreva ou nomeie uma criatura que lhe seja familiar. Você sente a direção do local onde ela se encontra, caso esteja a, no máximo, 1 quilômetro de distância. Se a criatura estiver se movendo, você sabe em que direção. Esta magia pode localizar uma criatura específica que você conheça, ou a criatura mais próxima de um tipo específico (como um humano ou unicórnio), contanto que você já tenha visto tal criatura de perto — a até 9 metros — ao menos uma vez.', '1 ação', 0, 'Concentração, até 1 hora', NULL, TRUE, TRUE, TRUE, 4, 'Adivinhação'),
(201, 'Localizar Objeto', 'Descreva ou nomeie um objeto que lhe seja familiar. Você sente a direção do local onde ele se encontra, caso esteja a, no máximo, 300 metros de distância. Se o objeto estiver se movendo, você sabe em que direção. A magia pode localizar um objeto específico que você conheça, desde que você já o tenha visto de perto — a até 9 metros — ao menos uma vez. Se preferir, a magia pode localizar um objeto de um tipo específico, como certo tipo de traje, joia, mobília, ferramenta ou arma.', '1 ação', 0, 'Concentração, até 10 minutos', NULL, TRUE, TRUE, TRUE, 2, 'Adivinhação'),
(202, 'Loquacidade', 'Até o fim da magia, quando você realizar um teste de Carisma, você pode substituir o número rolado por você por um 15. Além disso, não importa o que você diga, magias que determinam se você está dizendo a verdade indicarão que você está sendo sincero.', '1 ação', 0, '1 hora', NULL, TRUE, FALSE, FALSE, 8, 'Transmutação'),
(203, 'Lufada de Vento', 'Uma linha de vento forte, com 18 metros de comprimento e 3 metros de largura, é soprada a partir de você em uma direção à sua escolha, enquanto a magia durar. Cada criatura que comece seu próprio turno na linha deve ser bem-sucedida em uma salvaguarda de Força ou é empurrada 4,5 metros para longe de você, a favor da linha de vento.', '1 ação', 0, 'Concentração, até 1 minuto', NULL, TRUE, TRUE, TRUE, 2, 'Evocação'),
(204, 'Luz', 'Você toca um objeto que não tenha mais 3 metros em qualquer dimensão. Até a magia acabar, o objeto emite luz plena num raio de 6 metros e penumbra por 6 metros adicionais. Cobrir o objeto completamente com alguma coisa opaca bloqueará a luz. A magia termina se você conjura-la novamente ou dissipa-la com uma ação. Se você tentar afetar um objeto segurado ou vestido por uma criatura hostil, a criatura deve ser bem sucedida num teste de Destreza para evitar a magia.', '1 ação', 1, '1 hora', NULL, TRUE, FALSE, TRUE, 0, 'Evocação'),
(205, 'Luz do Dia', 'Uma esfera de luz com raio de 18 metros se expande a partir de um ponto à sua escolha e no alcance da magia. A esfera é de luz plena e emite meia-luz por mais 18 metros.', '1 ação', 18, '1 hora', NULL, TRUE, TRUE, FALSE, 3, 'Evocação'),
(206, 'Malogro', 'Energia necromântica inunda uma criatura, à sua escolha, que você possa ver dentro do alcance, drenando sua umidade e vitalidade. O alvo deve realizar um teste de resistência de Concentração. O alvo sofre 8d8 de dano necrótico se falhar no teste, ou metade desse dano se obtiver sucesso. Essa magia não surte efeito em mortos vivos ou constructos. Se você afetar uma criatura planta ou planta mágica, ela faz seu teste de resistência com desvantagem e a magia causa o máximo de dano a ela. Se você afetar uma planta não-mágica que não seja uma criatura, como uma árvore ou arbusto, ele não faz um teste de resistência; ela simplesmente seca e morre. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 5° nível ou superior, o dano aumenta em 1d8 para cada nível do espaço acima do 4°.', '1 ação', 9, 'Instantânea', '8d8', TRUE, TRUE, FALSE, 4, 'Necromancia'),
(207, 'Mansão Magnífica de Mordenkainen', 'Você conjura uma residência extradimensional, dentro do alcance, que permanece pela duração. Você escolhe onde sua única entrada é localizada. A entrada brilha discretamente e tem 1,5 metro de largura por 3 metros de altura. Você e qualquer criatura que você designou, quando conjurou a magia, pode entrar na residência extradimensional enquanto o portal permanecer aberto. Você pode abrir ou fechar o portal se estiver a até 9 metros dele. Enquanto estiver fechado, o portal é invisível. Além do portal existe um magnifico salão com inúmeros aposentos. A atmosfera é limpa, fresca e morna. Você pode criar qualquer projeto de piso que quiser, mas o espaço não pode exceder 50 cubos, cada cubo tendo 3 metros de cada lado. O local é mobiliado e decorado como você desejar. Ele contém comida suficiente para servir nove banquetes para até 100 pessoas. Uma equipe de 100 servos quase-transparentes atende todos que entrarem. Você decide a aparência visual dos servos e o vestuário deles. Eles são completamente obedientes as suas ordens. Cada servo pode realizar qualquer tarefa que um servo humano comum poderia fazer, mas eles não podem atacar ou realizar qualquer ação que poderia causar maleficio direto a outra criatura. Portanto, os servos podem buscar coisas, limpar, remendar, dobrar roupas, acender lareiras, servir comida, despejar vinho e assim por diante. Os servos podem ir a qualquer lugar na mansão, mas não podem deixa-la. Mobília e outros objetos criados por essa magia viram fumaça se forem removidos da mansão. Quando a magia acabar, qualquer criatura dentro do espaço extradimensional é expelida para o espaço vago mais próximo da entrada.', '1 minuto', 90, '24 horas', NULL, TRUE, TRUE, TRUE, 7, 'Conjuração'),
(208, 'Manto do Cruzado', 'Poder sagrado irradia de você em uma aura com um raio de 9 metros, despertando bravura em criaturas amigáveis. Enquanto a magia durar, a aura, centrada em você, move-se para onde quer que você vá. Enquanto estiver dentro da aura, cada criatura não hostil (incluindo você) causa 1d4 pontos de dano radiante adicionais ao acertar um ataque armado.', '1 ação', 0, 'Concentração, até 1 minuto', '1d4', TRUE, FALSE, FALSE, 3, 'Evocação'),
(209, 'Mão de Bigby', 'Você cria uma mão Grande de energia cintilante e translucida em um espaço desocupado que você possa ver dentro do alcance. A mão permanece pela duração da magia e ela se move ao seu comando, imitando os movimentos da sua própria mão. A mão é um objeto com CA 20 e pontos de vida igual ao seu máximo de pontos de vida. Se ela cair a 0 pontos de vida, a magia termina. Ela tem Força 26 (+8) e Destreza 10 (+0). A mão não preenche o espaço dela. Quando você conjura essa magia você pode, com uma ação bônus, nos seus turnos subsequentes, mover a mão até 18 metros e então causar um dos seguintes efeitos com ela. Mão Esmagadora. A mão tenta agarrar uma criatura Enorme ou menor a 1,5 metro dela. Você usa o valor de Força da mão para determinar o agarrão. Se o alvo for Médio ou menor, você terá vantagem no teste. Enquanto a mão estiver agarrando o alvo, você pode usar uma ação bônus para fazer a mão esmaga-lo. Quando o fizer, o alvo sofre dano de concussão igual a 2d6 + seu modificador de habilidade de conjuração. Mão Interposta. A mão se interpõem entre você e uma criatura a sua escolha até você lhe dar um comando diferente. A mão se move para ficar entre você e o alvo, concedendo a você meia-cobertura contra o alvo. O alvo não pode se mover através do espaço da mão se o valor de Força dele for menor ou igual ao valor de Força da mão. Se o valor de Força dele for maior que o valor de Força da mão, o alvo pode se mover até você através do espaço da mão, mas aquele espaço será considerado terreno difícil para o alvo. Mão Poderosa. A mão tenta empurrar uma criatura a 1,5 metro dela em uma direção a sua escolha. Realize um teste com a Força da mão, resistido por um teste de Força (Atletismo) do alvo. Se o alvo for Médio ou menor, você tem vantagem no teste. Se você for bem sucedido, a mão empurra o alvo até 1,5 metro mais uma quantidade de metros igual ao modificador da sua habilidade de conjuração multiplicado por 1,5. A mão se move com o alvo, permanecendo a 1,5 metro dele. Punho Cerrado. A mão golpeia uma criatura ou objeto a 1,5 metro dela. Realize uma jogada de ataque corpo-a-corpo com magia para a mão usando suas estatísticas de jogo. Se atingir, o alvo sofre 4d8 de dano de energia. Em Níveis Superiores. Se você conjurar essa magia usando um espaço de magia de 6° nível ou superior, o dano da opção punho cerrado aumenta em 2d8 e o dano da mão esmagadora aumenta em 2d6 para cada nível do espaço acima do 5°.', '1 ação', 36, 'Concentração, até 1 minuto', '4d8', TRUE, TRUE, TRUE, 5, 'Evocação'),
(210, 'Mãos Flamejantes', 'Enquanto você mantiver suas mãos com os polegares juntos e os dedos abertos, uma fino leque de chamas emerge das pontas dos seus dedos erguidos. Cada criatura num cone de 4,5 metros deve realizar um teste de resistência de Destreza. Uma criatura sofre 3d6 de dano de fogo se falhar no teste, ou metade desse dano se obtiver sucesso. O fogo incendeia qualquer objeto inflamável na área que não esteja sendo vestido ou carregado. Em Níveis Superiores. Se você conjurar essa magia usando um espaço de magia de 2° nível ou superior, o dano aumenta em 1d6 para cada nível do espaço acima do 1°.', '1 ação', 0, 'Instantânea', '3d6', TRUE, TRUE, FALSE, 1, 'Evocação'),
(211, 'Mãos Mágicas', 'Uma mão flutuante e espectral aparece em um ponto à sua escolha e no alcance da magia. A mão permanece enquanto a magia durar ou até você dispensá-la com uma ação. A mão desaparece caso se distancie mais de 9 metros de você ou se você conjurar a magia novamente. Você pode usar sua ação para controlar a mão, fazendo com que ela manipule objetos, abra portas ou recipientes destrancados, guarde ou pegue itens de recipientes abertos, ou derrame o conteúdo de frascos. Você pode movê-la até 9 metros a cada vez que a usa. Ela não pode atacar, ativar itens mágicos ou carregar mais de 4,5 quilos.', '1 ação', 9, '1 minuto', NULL, TRUE, TRUE, FALSE, 0, 'Conjuração'),
(212, 'Marca da Punição', 'Da próxima vez que você atingir uma criatura com um ataque com arma, antes do fim da magia, a arma cintilará com radiação astral quando você golpear. O ataque causa 2d6 de dano radiante extra ao alvo, que se torna visível, se estava invisível, e o alvo emite penumbra em um raio de 1,5 metro e não pode ficar invisível até a magia acabar. Em Níveis Superiores. Se você conjurar essa magia usando um espaço de magia de 3° nível ou superior, o dano extra aumenta em 1d6 para cada nível do espaço acima do 2°.', '1 ação bônus', 0, 'Concentração, até 1 minuto', '2d6', TRUE, FALSE, FALSE, 2, 'Evocação'),
(213, 'Marca do Caçador', 'Você escolhe uma criatura que possa ver, dentro do alcance e a marca misticamente como sua presa. Até a magia acabar, você causa 1d6 de dano extra ao alvo sempre que você o atingir com um ataque com arma e você tem vantagem em quaisquer testes de Sabedoria (Percepção) ou Sabedoria (Sobrevivência) feitos para encontrá-la. Se o alvo cair a 0 pontos de vida antes da magia acabar, você pode usar uma ação bônus, no seu turno subsequente para marcar uma nova criatura. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 3° ou 4° nível, você poderá manter sua concentração na magia por até 8 horas. Quando você usar um espaço de magia de 5° nível ou superior, você poderá manter sua concentração na magia por até 24 horas.', '1 ação bônus', 27, 'Concentração, até 1 hora', '1d6', TRUE, FALSE, FALSE, 1, 'Adivinhação'),
(214, 'Medo', 'Você projeta uma imagem fantasmagórica dos piores medos de uma criatura. Cada criatura num cone de 9 metros deve ser bem-sucedida numa salvaguarda de Sabedoria ou derrubará o que estiver segurando e ficará amedrontada enquanto a magia durar. Em cada um dos turnos dela, a criatura deve executar a ação Correr e distanciar-se o máximo que puder de você pela rota mais segura disponível, a menos que não haja para onde ir.', '1 ação', 0, 'Concentração, até 1 minuto', NULL, TRUE, TRUE, TRUE, 3, 'Ilusão'),
(215, 'Mensageiro Animal', 'Através dessa magia, você usa um animal para entregar uma mensagem. Escolha uma besta Miúda que você possa ver dentro do alcance, como um esquilo, um gaio-azul ou um morcego. Você especifica um local, que você já deve ter visitado, e um remetente com uma descrição geral, como “um homem ou mulher vestido em um uniforme da guarda da cidade” ou “um anão ruivo vestindo um chapéu pontudo”. Você também fala uma mensagem com até vinte e cindo palavras. A besta alvo viaja pela duração da magia para o local especifico, cobrindo 75 quilômetros em 24 horas para um mensageiro voador ou 37,5 quilômetros para outros animais. Quando o mensageiro chegar, ele entrega sua mensagem para a criatura que você descreveu, repetindo o som da sua voz. O mensageiro fala apenas para uma criatura que tenha uma descrição compatível com a que ele recebeu. Se o mensageiro não alcançar o destino antes do fim da magia, a mensagem é perdida e a besta faz seu caminho de volta para onde você conjurou a magia. Em Níveis Superiores. Se você conjurar essa magia usando um espaço de magia de 3° nível ou superior, a duração da magia aumenta em 48 horas para cada nível do espaço acima do 2°.', '1 ação', 9, '24 horas', NULL, TRUE, TRUE, TRUE, 2, 'Encantamento'),
(216, 'Mensagem', 'Você aponta seu dedo para uma criatura no alcance da magia e sussurra uma mensagem. O alvo (e somente ele) ouve a sua mensagem e pode responder ao sussurrar uma réplica que apenas você será capaz de ouvir. Você pode conjurar esta magia através de objetos sólidos se for familiar com o alvo e souber que ele está atrás da barreira. Silêncio mágico, 30 centímetros de pedra, 3 centímetros de metal comum, uma folha fina de chumbo ou 90 centímetros de madeira bloqueia a magia.', '1 ação', 36, '1 rodada', NULL, TRUE, TRUE, TRUE, 0, 'Transmutação'),
(217, 'Mesclar-se às Rochas', 'Você pisa em um objeto ou superfície de pedra grande o suficiente para conter o seu corpo totalmente, mesclando a si mesmo e a todo o equipamento que estiver carregando enquanto a magia durar. Usando seu movimento, você pisa na pedra, tornando sua presença totalmente invisível ou indetectável por sentidos não-mágicos. Enquanto fundido à rocha, você não pode ver o que acontece fora dela, e quaisquer testes de Sabedoria (Percepção) que você fizer para ouvir sons do lado de fora são feitos com desvantagem.', '1 ação', 1, '8 horas', '6d6', TRUE, TRUE, FALSE, 3, 'Transmutação'),
(218, 'Metamorfose', 'Você assume a forma de uma criatura diferente enquanto a magia durar. A nova forma pode ser de qualquer criatura com um nível de desafio igual ou menor que o seu próprio nível.', '1 ação', 18, 'Concentração, até 1 hora', NULL, TRUE, TRUE, TRUE, 9, 'Transmutação'),
(219, 'Metamorfose Verdadeira', 'Escolha uma criatura ou objeto não-mágico que você possa ver, dentro do alcance. Você transforma a criatura em uma criatura diferente, a criatura em um objeto ou o objeto em uma criatura (o objeto não pode nem estar sendo vestido nem carregado por outra criatura). A transformação permanece pela duração ou até o alvo cair a 0 pontos de vida ou morrer. Se você se concentrar nessa magia por toda a duração, a transformação será permanente. Metamorfos não são afetados por essa magia. Uma criatura involuntária pode realizar um teste de resistência de Sabedoria e, se for bem sucedida, não será afetada por essa magia. Criatura em Criatura. Se você transformar uma criatura em outro tipo de criatura, a nova forma pode ser de qualquer tipo que você desejar, contanto que o nível de desafio seja igual ou menor que o do alvo (ou o nível dele, caso o alvo não possua nível de desafio). As estatísticas de jogo do alvo, incluindo seus valores de habilidades mentais, são substituídas pelas estatísticas da nova forma. Ele mantem sua tendência e personalidade. O alvo assume os pontos de vida da sua nova forma e, quando ela reverter a sua forma normal, a criatura retorna à quantidade de pontos de vida que ela tinha antes da transformação. Se ela reverter como resultado de ter caído a 0 pontos de vida, qualquer dano excedente é recebido pela sua forma normal. Contanto que o dano excedente não reduza os pontos de vida da forma normal da criatura a 0, ela não cairá inconsciente. Essa magia não pode afetar um alvo com 0 pontos de vida. A criatura é limitada em suas ações pela natureza da sua nova forma e ela não pode falar, conjurar magias ou realizar qualquer outra ação que precise de mãos ou de vocalização, a não ser que a nova forma seja capaz de tais ações. O equipamento do alvo mescla-se a sua nova forma. O alvo não pode ativar, empunhar ou, de outra forma, se beneficiar de qualquer de seus equipamentos. Objeto em Criatura. Você pode transformar um objeto em um tipo de criatura, contanto que o tamanho da criatura não seja maior que o tamanho do objeto e, o nível de desafio da criatura será 9 ou menor. A criatura é amigável a você e aos seus companheiros. Ela age em cada um dos seus turnos. Você decide qual ação ela realizará e como ela se move. O Mestre tem as estatísticas da criatura e resolve todas as ações e movimentos dela. Se a magia se tornar permanente, você não terá mais controle sobre a criatura. Ele pode continuar amigável a você, dependendo da forma como você a tratou. Criatura em Objeto. Se você transformar uma criatura em um objeto, ela se transformará, junto com tudo que estiver vestindo ou carregando, nessa forma. As estatísticas da criatura tornam-se as do objeto e a criatura não se lembrará do tempo que passou nessa forma, depois da magia acabar e ela retornar a sua forma normal.', '1 ação', 9, 'Concentração, até 1 hora', NULL, TRUE, TRUE, TRUE, 9, 'Transmutação'),
(220, 'Miragem', 'Você faz um terreno em uma área de até 1,5 quilômetro quadrados pareça, soe, cheire e, até, sinta com outro tipo de terreno natural. Os formatos gerais do terreno permanecem os mesmos, no entanto. Campos abertos ou uma estrada podem ser modificados para se assemelharem a um pântano, colina, fenda ou algum outro tipo de terreno difícil ou intransponível. Uma lagoa pode ser modificada para se parecer com um prado, um precipício com um declive suave ou um barranco pedregoso com uma estrada larga e lisa. Similarmente, você pode alterar a aparência de estruturas ou adiciona-las onde nenhuma existia. A magia não disfarça, esconde ou adiciona criaturas. A ilusão inclui elementos audíveis, visuais, táteis e olfativos, portanto, ela pode transformar solo limpo em terreno difícil (ou vice-versa) ou, de outra forma, impedir o movimento através da área. Qualquer porção de terreno ilusório (como uma rocha ou galho) que seja removida da área da magia desaparece imediatamente. Criaturas com visão verdadeira podem ver através da ilusão a verdadeira forma do terreno; porém, todos os outros elementos da ilusão permanecem, então, mesmo que a criatura esteja ciente da presença da ilusão, ela ainda interage fisicamente com a ilusão.', '10 minutos', 500, '10 dias', NULL, TRUE, TRUE, FALSE, 7, 'Ilusão'),
(221, 'Missão', 'Você impõe um comando mágico a uma criatura que você possa ver, dentro do alcance, forçando-a a fazer algum serviço ou reprimindo-a por alguma ação ou curso de atividade, como você decidir. Se a criatura puder compreender você, ela deve ser bem sucedida num teste de resistência de Sabedoria ou ficará enfeitiçada por você pela duração. Enquanto a criatura estiver enfeitiçada por você, ela sofrerá 5d6 de dano psíquico toda vez que ela agir de maneira diretamente contrária às suas instruções, mas não mais de uma vez por dia. Uma criatura que não puder compreender você não é afetada por essa magia. Você pode emitir qualquer comando que escolher, exceto uma atividade que resulte em morte certa. Se você emitir um comando suicida, a magia termina. Você pode terminar a magia prematuramente usando uma ação para dissipa-la. As magias remover maldição, restauração maior ou desejo também podem termina-la. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 7° ou 8° nível, a duração será 1 ano. Quando você conjurar essa magia usando um espaço de magia de 9° nível, a magia dura até ser terminada por uma das magias mencionadas acima.', '1 minuto', 18, '30 dias', '5d6', TRUE, FALSE, FALSE, 5, 'Encantamento'),
(222, 'Mísseis Mágicos', 'Você cria três dardos brilhantes de energia mística. Cada dardo atinge uma criatura, à sua escolha, que você possa ver, dentro do alcance. Um dardo causa 1d4 + 1 de dano de energia ao alvo. Todos os dardos atingem simultaneamente e você pode direciona-los para atingir uma criatura ou várias. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 2° nível ou superior, a magia cria um dardo adicional para cada nível do espaço acima do 1°.', '1 ação', 36, 'Instantânea', '1d4+1', TRUE, TRUE, FALSE, 1, 'Evocação'),
(223, 'Modificar Memória', 'Você tenta modelar as memórias de outra criatura. Uma criatura que você possa ver, deve realizar um teste de resistência de Sabedoria. Se você estiver lutando com a criatura, ela terá vantagem no teste de resistência. Se falhar na resistência, o alvo fica enfeitiçado por você pela duração. O alvo enfeitiçado está incapacitado e não sabe o que está acontecendo seu redor, apesar de ainda poder ouvir você. Se ele sofrer qualquer dano ou for alvo de outra magia, essa magia acaba, e nenhuma das memórias do alvo é modificada. Enquanto esse feitiço durar, você pode afetar a memória sobre um evento que o alvo participou nas últimas 24 horas e que não tenha durado mais de 10 minutos. Você pode, permanentemente, eliminar todas as memórias desse evento, permitir que o alvo relembre do evento com perfeita clareza e riqueza de detalhes, mudar sua memória sobre os detalhes do evento ou criar uma memória de outro evento qualquer. Você deve falar ao alvo para descrever como sua memória é afetada e ele deve ser capaz de compreender seu idioma para que as memórias modificadas se enraízem. A mente dele preenche qualquer lacuna nos detalhes da sua descrição. Se a magia terminar antes de você ter finalizado a descrição das memórias modificadas, a memória da criatura não será alterada. Do contrário, as memórias modificadas tomam lugar quando a magia acabar. Uma memória modificada não afeta, necessariamente, como uma criatura se comporta, particularmente se a memória contradiz as inclinações, tendência ou crenças naturais da criatura. Uma modificação ilógica na memória, como implantar uma memória de como a criatura gosta de se encharcar de ácido, é repudiada, talvez como um sonho ruim. O Mestre pode considerar uma modificação na memória muito absurda para afetar uma criatura de uma forma significativa. Uma magia remover maldição ou restauração maior, conjurada no alvo, restaura a verdadeira memória da criatura. Em Níveis Superiores. Se você conjurar essa magia usando um espaço de magia de 6° nível ou superior, você pode alterar a memória do alvo de um evento que aconteceu a até 7 dias atrás (6° nível), 30 dias atrás (7° nível), 1 ano atrás (8° nível) ou em qualquer momento do passado da criatura (9° nível).', '1 ação', 9, 'Concentração, até 1 minuto', NULL, TRUE, TRUE, FALSE, 5, 'Encantamento'),
(224, 'Moldar Rochas', 'Você toca um objeto de pedra de tamanho Médio ou menor, ou uma seção de rocha com não mais que 1,5 metro em qualquer direção, e a modela em qualquer formato que sirva a seus propósitos, como transformar uma grande rocha em uma arma, ídolo ou baú, ou fazer uma pequena passagem através de uma parede.', '1 ação', 1, 'Instantânea', NULL, TRUE, TRUE, TRUE, 4, 'Transmutação'),
(225, 'Montaria Fantasmagórica', 'Uma criatura Grande, quase-real, similar a um cavalo, aparece no solo em um espaço desocupado, à sua escolha, dentro do alcance. Você decide a aparência da criatura, mas ela é equipada com sela, estribo e arreio. Qualquer equipamento criado por essa magia vira fumaça caso se afaste a mais de 3 metros da montaria. Pela duração, você ou a criatura que você escolher, pode cavalgar a montaria. A criatura usa as estatísticas de um cavalo de montaria, exceto por seu deslocamento ser de 30 metros e poder viajar 15 quilômetros em uma hora, ou 20 quilômetros em um ritmo rápido. Quando a magia acaba, a montaria desaparece gradualmente, dando ao cavaleiro 1 minuto para desmontar. A magia acaba se você usar uma ação para dissipa-la ou se a montaria sofrer qualquer dano.', '1 minuto', 9, '1 hora', NULL, TRUE, TRUE, FALSE, 3, 'Ilusão'),
(226, 'Mover Terra', 'Escolha uma área de terreno não maior que 12 metros de lado, dentro do alcance. Você pode remodelar terra, areia ou barro na área da maneira que quiser, pera duração. Você pode erguer ou abaixar a elevação da área, criar ou preencher valas, levantar ou deitar um muro ou formar uma coluna. A extensão de tais mudanças não pode exceder metade da maior dimensão da área. Portanto, se você afetar um quadrado de 12 metros, você poderá criar um pilar de até 6 metros de altura, erguer ou abaixar a elevação do quadrado em até 6 metros ou cavar uma vala de até 6 metros de profundidade e assim por diante. Leva 10 minutos para completar essas modificações. Ao final de cada 10 minutos que você gastar se concentrando nessa magia, você pode escolher uma nova área de terreno para afetar. Devido às transformações no terreno ocorrerem lentamente, as criaturas na área normalmente não podem ficar presas ou sofrer dano pela movimentação do solo. Essa magia pode manipular rocha natural ou construções de pedra. Pedra e estruturas deslocam-se para acomodar o novo terreno. Se a forma pela qual você modela o terreno poderia tornar uma estrutura instável, ela poderá desmoronar. Similarmente, essa magia não afeta diretamente o crescimento da vegetação. A terra movida carrega quaisquer plantas no caminho junto com ela.', '1 ação', 36, 'Concentração, até 2 horas', NULL, TRUE, TRUE, TRUE, 6, 'Transmutação'),
(227, 'Movimentação Livre', 'Você toca uma criatura voluntária. Enquanto a magia durar, o movimento do alvo não é afetado por terreno difícil, e magias e outros efeitos mágicos não podem reduzir o deslocamento, paralisar ou conter o alvo. O alvo também pode gastar 1,5 metro de movimento para escapar automaticamente de impedimentos não-mágicos, como algemas ou o agarramento de uma criatura. Por fim, estar debaixo d''água não impõe penalidades ao movimento do alvo ou aos seus ataques.', '1 ação', 1, '1 hora', NULL, TRUE, TRUE, TRUE, 4, 'Abjuração'),
(228, 'Muralha de Energia', 'Uma muralha invisível de energia aparece do nada num ponto, à sua escolha, dentro do alcance. A muralha aparece em qualquer orientação que você escolher, como uma barreira horizontal ou vertical ou em uma angulação. Ela pode estar flutuando no ar ou apoiada em uma superfície sólida. Você pode molda-la em uma cúpula hemisférica ou uma esfera com um raio de até dez painéis de 3 metros por 3 metros. Cada painel deve ser contíguo com outro painel. Em qualquer formato, a muralha terá 0,6 centímetros de espessura. Ela permanece pela duração. Se a muralha passar pelo espaço ocupado por uma criatura quando ela surgir, a criatura será empurrada para um dos lados da muralha (você escolhe qual lado). Nada pode passar fisicamente através da muralha. Ela é imune a todos os danos e não pode ser dissipada por dissipar magia. A magia desintegrar destrói a muralha instantaneamente, no entanto. A muralha também se estende ao Plano Etéreo, bloqueando a viagem etérea através dela.', '1 ação', 36, 'Concentração, até 10 minutos', NULL, TRUE, TRUE, TRUE, 5, 'Evocação'),
(229, 'Muralha de Espinhos', 'Você cria uma muralha de arbustos robustos, flexíveis, emaranhados e eriçados com espinhos pontudos. A muralha aparece, dentro do alcance, em uma superfície sólida e permanece pela duração. Você escolher fazer a muralha com até 18 metros de comprimento, 3 metros de altura e 1,5 metro de espessura ou um círculo com 6 metros de diâmetro e até 6 metros de altura com 1,5 metro de espessura. A muralha bloqueia a visão. Quando a muralha aparece, cada criatura dentro da área deve realizar um teste de resistência de Destreza. Se falhar na resistência, uma criatura sofrerá 7d8 de dano perfurante ou metade desse dano se obtiver sucesso. Uma criatura pode se mover através da muralha, embora lentamente e dolorosamente. Para cada 1,5 metro que a criatura atravesse da muralha, ela deve gastar 6 metros de movimento. Além disso, a primeira vez que a criatura entrar na muralha num turno ou termina o turno nela, ela deve fazer um teste de resistência de Destreza. Ela sofre 7d8 de dano cortante se falhar na resistência ou metade desse dano se obtiver sucesso. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 7° nível ou superior, ambos os tipos de dano aumentam em 1d8 para cada nível do espaço acima do 6°.', '1 ação', 36, 'Concentração, até 10 minutos', '7d8', TRUE, TRUE, TRUE, 6, 'Conjuração'),
(230, 'Muralha de Fogo', 'Você cria uma muralha de fogo numa superfície sólida dentro do alcance. Você pode fazer uma muralha de até 18 metros de comprimento, 6 metros de altura e 30 centímetros de espessura ou uma muralha anelar de até 6 metros de diâmetro, 6 metros de altura e 30 centímetros de espessura. A muralha é opaca e permanece pela duração. Quando a muralha aparece, cada criatura dentro da área dela deve realizar um teste de resistência de Destreza. Se falhar na resistência, uma criatura sofrerá 5d8 de dano, ou metade desse dano se passar na resistência. Um lado da muralha, escolhido por você no momento da conjuração da magia, causa 5d8 de dano de fogo a cada criatura que terminar o turno dela a até 3 metros desse lado ou dentro da muralha. Uma criatura sofre o mesmo dano quando entra na muralha pela primeira vez num turno ou termina seu turno nela. O outro lado da muralha não causa dano algum. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 5° nível ou superior, o dano aumenta em 1d8 para cada nível do espaço acima do 4°.', '1 ação', 36, 'Concentração, até 1 minuto', '5d8', TRUE, TRUE, TRUE, 4, 'Evocação'),
(231, 'Muralha de Gelo', 'Você cria uma muralha de gelo numa superfície sólida dentro do alcance. Você pode molda-la em uma cúpula hemisférica ou uma esfera com um raio de até dez painéis de 3 metros por 3 metros. Cada painel deve ser contíguo com outro painel. Em qualquer formato, a muralha terá 0,6 centímetros de espessura. Ela permanece pela duração. Se a muralha passar pelo espaço ocupado por uma criatura quando ela surgir, a criatura na área será empurrada para um dos lados da muralha (você escolhe qual lado) e deve realizar um teste de resistência de Destreza. Se falhar na resistência, a criatura sofrerá 10d6 de dano de frio ou metade desse dano se passar na resistência. A muralha é um objeto que pode ser danificado e então, partido. Ela tem CA 12, 30 pontos de vida por seção de 3 metros e é vulnerável a dano de fogo. Reduzir os pontos de vida de uma seção de 3 metros da muralha a 0 destruirá essa seção, deixando para trás uma camada de ar gelado no espaço ocupado pela muralha. Uma criatura que atravesse a camada de ar gelado pela primeira vez num turno, deve realizar um teste de resistência de Constituição. Essa criatura sofrerá 5d6 de dano de frio se fracassar na resistência, ou metade desse dano se obtiver sucesso. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 7° nível ou superior, o dano causado quando ela aparece aumenta em 2d6 e o dano por atravessar através da camada de ar gelado aumenta em 1d6 para cada nível do espaço acima do 6°.', '1 ação', 36, 'Concentração, até 10 minutos', '10d6', TRUE, TRUE, TRUE, 6, 'Evocação'),
(232, 'Muralha de Pedra', 'Uma muralha não-mágica de rocha sólida surge do nada num ponto, à sua escolha, dentro do alcance. A muralha tem 15 centímetros de espessura e é composta por dez painéis de 3 metros por 3 metros. Cada painel deve ser contíguo com, pelo menos, outro painel. Alternativamente, você pode criar painéis de 3 metros por 6 metros com apenas 7,5 centímetros de espessura. Se a muralha passar pelo espaço ocupado por uma criatura quando ela surgir, a criatura será empurrada para um dos lados da muralha (você escolhe qual lado). Se a criatura fosse ser rodeada por todos os lados da muralha (ou pela muralha e outra superfície sólida), a criatura pode realizar um teste de resistência de Destreza. Se obtiver sucesso, ela pode usar sua reação para se mover até seu deslocamento, assim não ficando mais cercada pela muralha. A muralha pode ter qualquer formato que você desejar, no entanto, ela não pode ocupar o mesmo espaço de uma criatura ou objeto. A muralha não precisa ser vertical ou se apoiar em qualquer fundação estável. Ela deve, no entanto, se fundir e estar solidamente suportada por rocha existente. Então, você pode usar essa magia para criar uma ponte sobre um abismo ou criar uma rampa. Se você criar um vão com mais de 6 metros de comprimento, você deve reduzir o tamanho de cada painel à metade para criar suportes. Você pode moldar grosseiramente a parede para criar merlões, ameias e assim por diante. A muralha é um objeto feito de pedra que pode ser danificado e então, partido. Cada painel tem CA 15 e 30 pontos de vida para cada 2,5 centímetros de espessura. Reduzir os pontos de vida de um painel a 0, o destruirá e pode fazer painéis conectados desmoronarem, à critério do Mestre. Se você mantiver sua concentração nessa magia por toda a duração, a muralha se tornará permanente e não poderá ser dissipada. Do contrário, a muralha desaparece quando a magia acabar.', '1 ação', 36, 'Concentração, até 10 minutos', NULL, TRUE, TRUE, TRUE, 5, 'Evocação'),
(233, 'Muralha de Vento', 'Uma muralha de ventos fortes surge do chão em um ponto à sua escolha, no alcance da magia, e permanece enquanto a magia durar. Ela pode ter até 15 metros de comprimento, 4,5 metros de altura e 30 centímetros de espessura. Você pode moldá-la à sua escolha, desde que ela percorra um caminho contínuo no chão. O vento forte mantém névoa, fumaça e outros gases à distância; objetos e criaturas voadoras Pequenas ou menores não conseguem atravessar a muralha.', '1 ação', 36, 'Concentração, até 1 minuto', '3d8', TRUE, TRUE, TRUE, 3, 'Evocação'),
(234, 'Muralha Prismática', 'Uma plano cintilante multicolorido de luzes forma uma parece vertical opaca – de até 27 metros de comprimento, 9 metros de altura e 2,5 centímetros de espessura – centrada num ponto que você possa ver, dentro do alcance. Alternativamente, você pode moldar a muralha numa esfera de 9 metros de diâmetro centrada num ponto, à sua escolha, dentro do alcance. A muralha permanece no lugar pela duração. Se você posicionar a muralha de forma que ela passaria através do espaço ocupado por uma criatura, a magia falha e sua ação e o espaço de magia são desperdiçados. A muralha emite luz plena num raio de 30 metros e penumbra por 30 metros adicionais. Você e as criaturas designadas, no momento que você conjurou a magia, podem passar através e permanecer perto da muralha sem se ferirem. Se outra criatura que puder ver a muralha se aproximar mais de 6 metros dela ou começar seu turno lá, a criatura deve realizar um teste de resistência de Constituição ou ficará cega por 1 minuto. A muralha consiste em sete camadas, cada uma de uma cor diferente. Quando uma criatura tenta tocar ou passar através da muralha, ela atravessa uma camada de cada vez, até atravessar todas as camadas da muralha. À medida que ela passa ou toca cada camada, a criatura realiza um teste de resistência de Destreza ou será afetada pelas propriedades daquela camada, como descrito abaixo. A muralha pode ser destruída, também, uma camada por vez, em ordem de vermelho à violeta, pelos meios especificados em cada camada. Quando uma camada é destruída, ela permanece assim pela duração da magia. Um campo antimagia não produz efeito em uma muralha prismática. 1. Vermelho. O alvo sofre 10d6 de dano de fogo se falhar na resistência ou metade desse dano se obtiver sucesso. Enquanto essa camada estiver no lugar, ataques à distância não-mágicos não podem atravessar a muralha. A camada pode ser destruída causando, pelo menos, 25 de dano de frio a ela. 2. Laranja. O alvo sofre 10d6 de dano de ácido se falhar na resistência ou metade desse dano se obtiver sucesso. Enquanto essa camada estiver no lugar, ataques à distância mágicos não podem atravessar a muralha. A camada pode ser destruída por um vento forte. 3. Amarelo. O alvo sofre 10d6 de dano elétrico se falhar na resistência ou metade desse dano se obtiver sucesso. A camada pode ser destruída causando, pelo menos, 60 de dano de energia a ela. 4. Verde. O alvo sofre 10d6 de dano de veneno se falhar na resistência ou metade desse dano se obtiver sucesso. A magia criar passagem ou outra magia de nível igual ou superior que possam abrir um portal em uma superfície sólida, destroem essa camada. 5. Azul. O alvo sofre 10d6 de dano de frio se falhar na resistência ou metade desse dano se obtiver sucesso. A camada pode ser destruída causando, pelo menos, 25 de dano de fogo a ela. 6. Anil. Se falhar na resistência, o alvo ficará impedido. Ele deve então, fazer um teste de resistência de Constituição ao final de cada um dos turnos dele. Se obtiver sucesso três vezes, a magia termina. Se falhar na resistência três vezes, ela se torna pedra é afetada pela condição petrificado. Os sucessos e falhas não precisam ser consecutivos; anote ambos os resultados até o alvo acumular três de mesmo tipo. Enquanto essa camada estiver no lugar, magias não podem ser conjuradas através da muralha. A camada pode ser destruída por luz plena emitida pela magia luz do dia ou uma magia similar de nível equivalente ou superior. 7. Violeta. Se falhar na resistência, o alvo ficará cego. Ele deve realizar um teste de resistência de Sabedoria no início do seu próximo turno. Um sucesso na resistência acaba com a cegueira. Se falhar na resistência, a criatura é transportada para outro plano de existência, escolhido pelo Mestre, e não estará mais cego. (Tipicamente, uma criatura que esteja em um plano que não seja o seu plano natal é banida para lá, enquanto que outras criaturas geralmente são enviadas para os Planos Astral ou Etéreo.) Essa camada é destruída pela magia dissipar magia ou por uma magia similar de nível equivalente ou superior que possa acabar com magias e efeitos mágicos.', '1 ação', 18, '10 minutos', '10d6', TRUE, TRUE, FALSE, 9, 'Abjuração'),
(235, 'Nevasca', 'Até a magia acabar, uma chuva congelante e neve caem num cilindro de 6 metros de altura por 12 metros de raio, centrado num ponto, à sua escolha, dentro do alcance. A área é de escuridão densa e, chamas expostas na área são extintas. O solo na área é coberto por gelo escorregadio, tornando-o terreno difícil. Quando uma criatura entrar na área da magia pela primeira vez num turno ou começar seu turno nela, ela deve realizar um teste de resistência de Destreza. Se falhar, cairá no chão. Se um, criatura estiver se concentrando na área da magia, a criatura deve realizar um teste de resistência de Constituição contra a CD da magia, ou perderá a concentração.', '1 ação', 45, 'Concentração, até 1 minuto', NULL, TRUE, TRUE, TRUE, 3, 'Conjuração'),
(236, 'Névoa Fétida', 'Você cria uma esfera com raio de 6 metros, feita de um gás amarelo e nauseabundo, centrado em um ponto à sua escolha e no alcance da magia. A nuvem se alastra, contornando os cantos, e a área afetada fica totalmente obscurecida. Cada criatura que estiver totalmente dentro da nuvem no início do próprio turno deve fazer uma salvaguarda de Constituição contra veneno. Se falhar, a criatura gasta uma ação naquele turno vomitando e cambaleando.', '1 ação', 27, 'Concentração, até 1 minuto', NULL, TRUE, TRUE, TRUE, 3, 'Conjuração'),
(237, 'Névoa Mortal', 'Você cria uma esfera de nevoeiro venenoso de cor amarelo-esverdeado, com 6 metros de raio, centrado em um ponto, à sua escolha, dentro do alcance. O nevoeiro se espalha, dobrando esquinas. Ele permanece pela duração ou até um vento forte dispersar o nevoeiro, terminando a magia. Sua área é de escuridão densa. Quando uma criatura entra na área da magia pela primeira vez no turno dela ou começa seu turno lá, essa criatura deve realizar um teste de resistência de Constituição. A criatura sofre 5d8 de dano de veneno, ou metade desse dano, se passar no teste. As criaturas serão afetadas mesmo se prenderem a respiração ou não precisarem respirar. O nevoeiro se afasta 3 metros de você no começo de cada um dos seus turnos, deslizando pela superfície do solo. Os vapores são mais pesados que o ar, mantendo-se nos níveis mais baixos do terreno, até mesmo caindo em aberturas. Em Níveis Superiores. Se você conjurar essa magia usando um espaço de magia de 6° nível ou superior, o dano aumenta em 1d8 para cada nível do espaço acima do 5°.', '1 ação', 36, 'Concentração, até 10 minutos', '5d8', TRUE, TRUE, FALSE, 5, 'Conjuração'),
(238, 'Névoa Obscurecente', 'Você cria uma esfera de 6 metros de raio de névoa, centrada num ponto, dentro do alcance. A esfera se espalha, dobrando esquinas, e a área dela é de escuridão densa. Ela permanece pela duração ou até um vento moderado ou mais rápido (pelo menos 15 quilômetros por hora) dispersa-la. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 2° nível ou superior, o raio da névoa aumenta em 6 metros para cada nível do espaço acima do 1°.', '1 ação', 36, 'Concentração, até 1 hora', NULL, TRUE, TRUE, FALSE, 1, 'Conjuração'),
(239, 'Nublar', 'Seu corpo se torna turvo, mudando e oscilando para todos que puderem ver você. Pela duração, qualquer criatura terá desvantagem nas jogadas de ataque contra você. Um atacante é imune a esse efeito se não depender de visão, como os que tenham percepção às cegas ou os que puderem ver através de ilusões, como os com visão verdadeira.', '1 ação', 0, 'Concentração, até 1 minuto', NULL, TRUE, FALSE, FALSE, 2, 'Ilusão'),
(240, 'Nuvem de Adagas', 'Você preenche o ar com adagas giratórias num cubo de 1,5 metro quadrado, centrado em m ponto, à sua escolha, dentro do alcance. Uma criatura sofre 4d4 de dano cortante quando entra na área da magia pela primeira vez no turno dela ou começa seu turno na área. Em Níveis Superiores. Se você conjurar essa magia usando um espaço de magia de 3° nível ou superior, o dano aumenta em 2d4 para cada nível do espaço acima do 2°.', '1 ação', 18, 'Concentração, até 1 minuto', '4d4', TRUE, TRUE, TRUE, 2, 'Conjuração'),
(241, 'Nuvem Incendiária', 'Uma nuvem de fumaça rodopiante que dispara brasas incandescentes aparece numa esfera de 6 metros centrada num ponto, dentro do alcance. A nuvem se espalha, dobrando esquinas, e gera escuridão densa. Ela permanece pela duração ou até que um vento de velocidade moderada ou mais forte (pelo menos 15 quilômetros por hora) a disperse. Quando a nuvem aparece, cada criatura deve realizar um teste de resistência de Destreza. Uma criatura sofre 10d8 de dano de fogo se falhar na resistência ou metade desse dano se passar. Uma criatura deve, também, realizar um teste de resistência quando entrar na área da magia pela primeira vez num turno ou terminar seu turno nela. A nuvem se afasta 3 metros de você numa direção, que você escolheu, no começo de cada um dos seus turnos.', '1 ação', 45, 'Concentração, até 1 minuto', '10d8', TRUE, TRUE, FALSE, 8, 'Conjuração'),
(242, 'Olho Arcano', 'Você cria um olho mágico invisível, dentro do alcance, que flutua no ar pela duração. Você mentalmente recebe informações visuais do olho, que possui visão normal e visão no escuro com alcance de 9 metros. O olho pode ver em todas as direções. Com uma ação, você pode mover o olho até 9 metros em qualquer direção. Não existe limite de quão longe de você o olho pode se mover, mas ele não pode entrar em outro plano de existência. Uma barreira solida bloqueia o movimento do olho, mas o olho pode passar através de aberturas de até 3 centímetros de diâmetro.', '1 ação', 9, 'Concentração, até 1 hora', NULL, TRUE, TRUE, TRUE, 4, 'Adivinhação'),
(243, 'Onda Destrutiva', 'Você golpeia o chão, criando uma explosão de energia divina que se propaga de você. Cada criatura, à sua escolha, a até 9 metros de você, deve ser bem sucedida em um teste de resistência de Constituição ou sofrerá 5d5 de dano trovejante, assim como 5d6 de dano radiante ou necrótico (à sua escolha), e será derrubada no chão. Uma criatura que obtenha sucesso no teste de resistência sofre metade desse dano e não é derrubada no chão.', '1 ação', 0, 'Instantânea', '10d6', TRUE, FALSE, FALSE, 5, 'Evocação'),
(244, 'Onda Troveante', 'Uma onda de força trovejante varre tudo a partir de você. Cada criatura em um cubo de 4,5 metros originando em você deve fazer uma salvaguarda de Constituição. Se falhar, sofre 2d8 pontos de dano trovejante e é empurrada 3 metros para longe de você. Em caso de sucesso, a criatura sofre metade do dano e não é empurrada. Além disso, objetos soltos que estejam completamente dentro da área de efeito são automaticamente empurrados 3 metros para longe de você, e a magia emite um estrondo trovejante audível a até 90 metros.', '1 ação', 0, 'Instantânea', '2d8', TRUE, TRUE, FALSE, 1, 'Evocação'),
(245, 'Oração Curativa', 'Até seis criaturas, à sua escolha, que você possa ver, dentro do alcance, recuperam uma quantidade de pontos de vida igual a 2d8 + seu modificador de habilidade de conjuração, cada uma. Essa magia não afeta mortos-vivos ou constructos. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 3° nível ou superior, a cura aumenta em 1d8 para cada nível do espaço acima do 2°.', '10 minutos', 9, 'Instantânea', NULL, TRUE, FALSE, FALSE, 2, 'Evocação'),
(246, 'Orbe Cromática', 'Você arremessa uma esfera de energia de 12 centímetros de diâmetro numa criatura que você possa ver dentro do alcance. Você escolhe ácido, frio, fogo, elétrico, veneno ou trovejante para o tipo de orbe que você cria e, então, realiza um ataque à distância com magia. Se o ataque atingir, a criatura sofre 3d8 de dano do tipo escolhido. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 2° nível ou superior, o dano aumenta em 1d8 para cada nível do espaço acima do 1°.', '1 ação', 27, 'Instantânea', '3d8', TRUE, TRUE, TRUE, 1, 'Evocação'),
(247, 'Orientação', 'Você toca uma criatura voluntária. Uma vez, antes da magia acabar, o alvo pode rolar um d4 e adicionar o número rolado a um teste de habilidade a escolha dele. Ele pode rolar o dado antes ou depois de realizar o teste de habilidade. Após isso, a magia termina.', '1 ação', 1, 'Concentração, até 1 minuto', NULL, TRUE, TRUE, FALSE, 0, 'Adivinhação'),
(248, 'Padrão Hipnótico', 'Você cria um padrão distorcido de cores o qual serpenteia no ar dentro de um cubo de 9 metros de lado, no alcance da magia. O padrão aparece por um momento e desaparece. Cada criatura na área, e que seja capaz de ver o padrão, deve fazer uma salvaguarda de Sabedoria. Se falhar, a criatura fica enfeitiçada enquanto a magia durar. Criaturas afetadas por esta magia estão incapacitadas e têm deslocamento igual a 0.', '1 ação', 36, 'Concentração, até 1 minuto', NULL, FALSE, TRUE, TRUE, 3, 'Ilusão'),
(249, 'Palavra Curativa', 'Uma criatura, à sua escolha, que você possa ver dentro do alcance recupera uma quantidade de pontos de vida igual a 1d4 + seu modificador de habilidade de conjuração. Essa magia não tem efeito em mortos-vivos ou constructos Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 2° nível ou superior, a cura aumenta em 1d4 para cada nível do espaço acima do 1°.', '1 ação bônus', 18, 'Instantânea', NULL, TRUE, FALSE, FALSE, 1, 'Evocação'),
(250, 'Palavra Curativa em Massa', 'À medida que você brada palavras de restauração, até seis criaturas, à sua escolha, que você possa ver, dentro do alcance, recuperam uma quantidade de pontos de vida igual a 1d4 + seu modificador de habilidade de conjuração. Essa magia não afeta mortos-vivos ou constructos. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 4° nível ou superior, a cura aumenta em 1d4 para cada nível do espaço acima do 3°.', '1 ação bônus', 18, 'Instantânea', NULL, TRUE, FALSE, FALSE, 3, 'Evocação'),
(251, 'Palavra de Poder Atordoar', 'Você pronuncia uma palavra de poder que pode oprimir a mente de uma criatura que você possa ver, dentro do alcance, deixando-a estupefata. Se o alvo escolhido estiver com 150 pontos de vida ou menos, ele ficará atordoado. Do contrário, essa magia não produz efeito. O alvo atordoado deve realizar um teste de resistência de Constituição no final de cada um dos turnos dele. Se obtiver sucesso na resistência, o efeito de atordoamento termina.', '1 ação', 18, 'Instantânea', NULL, TRUE, FALSE, FALSE, 8, 'Encantamento'),
(252, 'Palavra de Poder Curar', 'Uma onda de energia curativa inunda a criatura tocada. O alvo recupera todos os seus pontos de vida. Se a criatura estiver enfeitiçada, amedrontada, paralisada ou atordoada, a condição termina. Se a criatura estiver caída, ela pode usar a reação dela para se levantar. Essa magia não afeta mortos-vivos ou constructos.', '1 ação', 1, 'Instantânea', NULL, TRUE, TRUE, FALSE, 9, 'Evocação'),
(253, 'Palavra de Poder Matar', 'Você profere uma palavra de poder que pode compelir uma criatura que você possa ver, dentro do alcance, a morrer instantaneamente. Se o alvo escolhido estiver com 100 pontos de vida ou menos, ele morre. Do contrário, essa magia não produz efeito.', '1 ação', 18, 'Instantânea', NULL, TRUE, FALSE, FALSE, 9, 'Encantamento'),
(254, 'Palavra de Recordação', 'Você e até cinco criaturas voluntária a 1,5 metro de você, instantaneamente são teletransportadas para um santuário previamente designado. Você e qualquer criatura que se teletransportar com você, aparece no espaço desocupado mais próximo do ponto que você designou quando preparou seu santuário (veja abaixo). Se você conjurar essa magia sem ter preparado um santuário primeiro, a magia não funciona. Você deve designar um santuário na conjuração dessa magia dentro de um local, como um templo dedicado ou fortemente ligado a sua divindade. Se você tentar conjurar essa magia dessa forma em uma área que não seja dedicada à sua divindade, a magia não funciona.', '1 ação', 2, 'Instantânea', NULL, TRUE, FALSE, FALSE, 6, 'Conjuração'),
(255, 'Palavra Divina', 'Você profere uma palavra divina, imbuída com o poder que moldou o mundo na aurora da criação. Escolha qualquer quantidade de criaturas que você possa ver dentro do alcance. Cada criatura que puder ouvir você deve realizar um teste de resistência de Carisma. Ao falhar na resistência, uma criatura sofre um efeito baseado nos seus pontos de vida atuais:  50 pontos de vida ou menos: surda por 1 minuto  40 pontos de vida ou menos: surda e cega por 10 minutos  30 pontos de vida ou menos: surda, cega e atordoada por 1 hora  20 pontos de vida ou menos: morta instantaneamente Independentemente dos seus pontos de vida atuais, um celestial, corruptor, elemental ou fada que falhar na sua resistência é obrigado a voltar para o plano de origem dele (se já não for aqui) e não pode retornar para o plano atual por 24 horas através de nenhum meio inferior à magia desejo.', '1 ação bônus', 9, 'Instantânea', NULL, TRUE, FALSE, FALSE, 7, 'Evocação'),
(256, 'Parar o Tempo', 'Você, por um breve momento, para o fluxo do tempo pra tudo, menos pra você. Nenhum tempo se passa para as outras criaturas, enquanto você realiza 1d4 + 1 turnos de uma vez, durante os quais você pode usar ações e se mover normalmente. Essa magia termina se uma das ações que você fizer durante esse período ou qualquer efeito que você criar, afetar uma criatura diferente de você ou um objeto que esteja sendo vestido ou carregado por outro que não você. Além disso, a magia termina se você se mover para um lugar a mais de 300 metros do local onde você conjurou essa magia.', '1 ação', 0, 'Instantânea', NULL, TRUE, FALSE, FALSE, 9, 'Transmutação'),
(257, 'Passo Nebuloso', 'Rodeado brevemente por uma névoa prateada, você se teleporta a até 9 metros para um espaço desocupado à sua vista.', '1 ação bônus', 0, 'Instantânea', NULL, TRUE, FALSE, FALSE, 2, 'Conjuração'),
(258, 'Passos Longos', 'Você toca uma criatura. O deslocamento do alvo aumenta em 3 metros, até a magia acabar. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 2° nível ou superior, você pode afetar uma criatura adicional para cada nível do espaço acima do 1°.', '1 ação', 1, '1 hora', NULL, TRUE, TRUE, TRUE, 1, 'Transmutação'),
(259, 'Passos Sem Pegadas', 'Um véu de sombras e silêncio irradia de você, mascarando você e seus aliados contra detecção. Enquanto a magia durar, cada criatura à sua escolha no alcance de 9 metros (incluindo você) tem um bônus de +10 nos testes de Destreza (Furtividade) e não pode ser rastreada a não ser por meios mágicos. Uma criatura com este bônus não deixa rastros ou outros traços de sua passagem.', '1 ação', 0, 'Concentração, até 1 hora', NULL, TRUE, TRUE, TRUE, 2, 'Abjuração'),
(260, 'Patas de Aranha', 'Até a magia acabar, uma criatura voluntária que você tocar, recebe a habilidade de se mover para cima, para baixo e através de superfícies verticais e de cabeça para baixo pelos tetos, enquanto deixa suas mãos livres. O alvo também ganha deslocamento de escalada igual a seu deslocamento de caminhada.', '1 ação', 1, 'Concentração, até 1 hora', NULL, TRUE, TRUE, TRUE, 2, 'Transmutação'),
(261, 'Pele de Árvore', 'Você toca uma criatura voluntária. Até o fim da magia, a pele da criatura fica rígida, similar a casca de um carvalho, e a CA do alvo não pode ser inferior a 16, independentemente do tipo de armadura que ela esteja vestindo.', '1 ação', 1, 'Concentração, até 1 hora', NULL, TRUE, TRUE, TRUE, 2, 'Transmutação'),
(262, 'Pele de Pedra', 'Essa magia transforma a pele de uma criatura voluntária que você tocar em rocha sólida. Até a magia acabar, o alvo tem resistência a dano de concussão, cortante e perfurante não-mágico.', '1 ação', 1, 'Concentração, até 1 hora', NULL, TRUE, TRUE, TRUE, 4, 'Abjuração'),
(263, 'Pequena Cabana de Leomund', 'Um domo de energia imóvel, de 3 metros de raio, aparece do nada, ao seu redor e acima de você e permanece parado pela duração. A magia termina se você deixar a área. Nove criaturas de tamanho Médio ou menor podem caber dentro do domo com você. A magia falha se a área incluir criaturas maiores ou mais de nove criaturas. Criaturas e objetos dentro do domo quando você conjurou essa magia, podem se mover através dele livremente. Todas as outras criaturas e objetos são bloqueados ao tentarem atravessa-lo. Magias e outros efeitos mágicos não podem se estender através do domo ou serem conjurados através dele. A atmosfera dentro do espaço é confortável e seca, independente do clima do lado de fora. Até a magia acabar, você pode comandar o interior para que fique mal iluminado ou escuro. O domo é opaco do lado de fora, de qualquer cor que você desejar, mas é transparente do lado de dentro.', '1 minuto', 0, '8 horas', NULL, TRUE, TRUE, TRUE, 3, 'Evocação'),
(264, 'Perdição', 'Até três criaturas, à sua escolha, que você possa ver dentro do alcance, devem realizar um teste de resistência de Carisma. Sempre que um alvo que falhou nessa resistência realizar uma jogada de ataque ou um teste de resistência antes da magia acabar, o alvo deve rolar um d4 e subtrair o valor rolado da jogada de ataque ou teste de resistência. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 2° nível ou superior, você pode afetar uma criatura adicional para cada nível do espaço acima do 1°.', '1 ação', 9, 'Concentração, até 1 minuto', NULL, TRUE, TRUE, TRUE, 1, 'Encantamento'),
(265, 'Piskar', 'Role um d20 no final de cada um dos seus turnos pela duração da magia. Com um resultado de 11 ou maior, você desaparece do seu plano de existência atual e reaparece no Plano Etéreo (a magia falha e a conjuração é perdida se você já estiver nesse plano). No início do seu próximo turno e quando a magia terminar, se você estiver no Plano Etéreo, você retorna a um espaço desocupado de sua escolha que você possa ver a até 3 metros do espaço em que você desapareceu. Se não houver um espaço disponível dentro do alcance, você reaparece no espaço desocupado mais próximo (escolhido aleatoriamente, se existir mais de um espaço a mesma distância). Você pode dissipar a magia com uma ação. Quando estiver no Plano Etéreo, você pode ver e ouvir o plano de onde você veio, que aparece em tons de cinza, e você não pode ver nada além de 18 metros. Você só pode afetar ou ser afetado por outras criaturas no Plano Etéreo. As criaturas que não estiverem lá não podem notar você nem interagir com você, a não ser que elas tenham uma habilidade que as permita.', '1 ação', 0, '1 minuto', NULL, TRUE, TRUE, FALSE, 3, 'Transmutação'),
(266, 'Porta Dimensional', 'Você pode se teleportar a partir de sua localização atual para qualquer outro local dentro do alcance da magia. Você chega exatamente no local desejado, seja um lugar que possa ver, visualizar ou descrever.', '1 ação', 150, 'Instantânea', NULL, TRUE, FALSE, FALSE, 4, 'Conjuração'),
(267, 'Portal', 'Você conjura um portal conectando um espaço desocupado que você possa ver, dentro do alcance, a uma localização precisa em um plano de existência diferente. O portal é uma abertura circular, que você pode fazer ter de 1,5 a 6 metros de diâmetro. Você pode orientar o portal em qualquer direção, à sua escolha. O portal permanece pela duração. O portal terá uma frente e um fundo em cada plano que ele aparecer. Viajar pelo portal só é possível ao atravessa-lo pela frente. Qualquer coisa que o fizer, é instantaneamente transportado para o outro plano, aparecendo no espaço desocupado mais próximo do portal. Divindades e outros soberanos planares podem impedir que portais criados através dessa magia se abram na presença deles ou em qualquer parte dos seus domínios. Quando você conjurar essa magia, você pode falar o nome de uma criatura especifica (um pseudônimo, título ou apelido não funcionará). Se essa criatura estiver em um plano diferente do que você está, o portal se abre na vizinhança imediata da criatura nomeada e suga a criatura para dentro do portal, fazendo-a aparecer no espaço desocupado mais próximo do seu lado do portal. Você não adquire qualquer poder especial sobre a criatura e ela está livre para agir como o Mestre julgar apropriado. Ela pode ir embora, atacar você ou ajudar você.', '1 ação', 18, 'Concentração, até 1 minuto', NULL, TRUE, TRUE, TRUE, 9, 'Conjuração'),
(268, 'Portal Arcano', 'Você cria portais de teletransporte conectados que permanecem abertos pela duração. Escolha dois pontos no solo que você possa ver, um ponto a até 3 metros de você e outro a até 150 metros de você. Um portal circular, com 3 metros de diâmetro, se abre em cada ponto. Se o portal se abriria num local ocupado por uma criatura, a magia falha e a conjuração é perdida. Os portais são dois anéis dimensionais brilhantes cheios de névoa, flutuando a centímetros do chão, perpendicular a ele no ponto escolhido. Um anel é visível apenas de um lado (à sua escolha), que é o lado que funciona como portal. Qualquer criatura ou objeto que adentrar o portal, sairá pelo outro portal, como se ambos estivessem adjacentes um ao outro; atravessar um portal do lado que não é um portal não tem efeito. A névoa que preenche cada portal é opaca e bloqueia a visão através dele. No seu turno, você pode girar os anéis, com uma ação bônus, fazendo o lado ativo ficar em uma direção diferente.', '1 ação', 150, 'Concentração, até 10 minutos', NULL, TRUE, TRUE, FALSE, 6, 'Conjuração'),
(269, 'Praga', 'Seu toque inflige uma doença. Faça um ataque de magia corpo-a-corpo contra uma criatura ao seu alcance. Se atingir, você aflige a criatura com uma doença, de sua escolha, entre qualquer um das descritas abaixo. No final de cada turno do alvo, ele deve realizar um teste de resistência de Constituição. Após obter três falhas nesses testes de resistência, o efeito da doença permanece pela duração e a criatura para de fazer testes de resistência. Após obter três sucessos nesses testes de resistência, a criatura se recupera da doença e a magia termina. Já que essa magia induz uma doença natural no alvo, qualquer efeito que remova uma doença, ou de outra forma, melhore os efeitos de uma doença, se aplica a ela. Ardência Mental. A mente da criatura fica febril. A criatura tem desvantagem em testes de Inteligência, testes de resistência de Inteligência e a criatura age como se estivesse sob efeito da magia confusão durante um combate. Enjoo Cegante. A dor se agarra a mente da criatura e seus olhos ficam branco-leitosos. A criatura tem desvantagem em testes de Sabedoria e testes de resistência de Sabedoria e está cega. Febre do Esgoto. Uma febre voraz se espalha pelo corpo da criatura. A criatura tem desvantagem em testes de Força, testes de resistência de Força e jogadas de ataque que usem Força. Necrose da Carne. A carne da criatura se decompõe. A criatura tem desvantagem em testes de Carisma e vulnerabilidade a todos os danos. Perdição Pegajosa. A criatura começa a sangrar incontrolavelmente. A criatura tem desvantagem em testes de Constituição e testes de resistência de Constituição. Além disso, sempre que a criatura sofrer dano, ela ficará atordoada até o fim do seu próximo turno. Tremedeira. A criatura é acometida por espasmos. A criatura tem desvantagem em testes de Destreza, testes de resistência de Destreza e jogadas de ataque que usem Destreza.', '1 ação', 1, '7 dias', NULL, TRUE, TRUE, FALSE, 5, 'Necromancia'),
(270, 'Praga de Insetos', 'Um enxame voraz de gafanhotos preenche uma esfera de 6 metros de raio, centrada no ponto que você escolher, dentro do alcance. A esfera se espalha dobrando esquinas. A esfera permanece pela duração e sua área é de escuridão leve. A área da esfera é de terreno difícil. Quando a área aparece, cada criatura dentro dela deve realizar um teste de resistência de Constituição. Uma criatura sofre 4d10 de dano perfurante se falhar na resistência ou metade desse dano se passar. Uma criatura deve, também, realizar um teste de resistência quando entrar na área da magia pela primeira vez num turno ou terminar seu turno nela. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 6° nível ou superior, o dano aumenta em 1d10 para cada nível do espaço acima do 5°.', '1 ação', 90, 'Concentração, até 10 minutos', '4d10', TRUE, TRUE, TRUE, 5, 'Conjuração'),
(271, 'Prestidigitação', 'Esta magia é um pequeno truque mágico que conjuradores iniciantes usam para praticar. Crie um dos seguintes efeitos mágicos no alcance da magia: um efeito sensorial instantâneo e inofensivo, como uma chuva de faíscas, um sopro de vento, notas musicais fantasmagóricas ou um odor característico; acender ou apagar instantaneamente uma vela, tocha ou pequena fogueira; limpar ou sujar instantaneamente um objeto que não seja maior que um cubo de 30 centímetros de lado; resfriar, esquentar ou temperar por 1 hora um cubo de até 30 centímetros de lado feito de matéria não-viva; ou colorir, fazer uma pequena marca ou um símbolo aparecer em um objeto ou superfície por 1 hora.', '1 ação', 3, 'Até 1 hora', NULL, TRUE, TRUE, FALSE, 0, 'Transmutação'),
(272, 'Prisão de Energia', 'Uma prisão em formato cúbico, imóvel e invisível, composta de energia mágica brota do nada, em volta de uma área, à sua escolha, dentro do alcance. A prisão pode ser uma cela ou uma caixa sólida, à sua escolha. Uma prisão em formato de cela pode ter até 6 metros quadrados e é feita de barras com 1,5 centímetro de diâmetro espaçadas a 1,5 centímetro umas das outras. Uma prisão em formato de caixa pode ter até 3 metros quadrados, criando uma barreira sólida que impede qualquer matéria de atravessa-la e bloqueia qualquer magia conjurada de entrar ou sair da área. Quando você conjura a magia, qualquer criatura que estiver completamente dentro da área da prisão ficará presa. As criaturas que estiverem apenas parcialmente na área, ou as grandes demais para caber dentro da área, são empurradas do centro da área, até estarem completamente fora dela. Uma criatura dentro da prisão não pode sair dela por meios não-mágicos. Se a criatura tentar usar teletransporte ou viagem entre planos para abandonar a prisão, ela deve, primeiro, realizar um teste de resistência de Carisma. Se obtiver sucesso, a criatura pode usar a magia e sair da prisão. Se falhar, a criatura não pode sair da prisão e desperdiça o uso da magia ou efeito. A prisão também se estende ao Plano Etéreo, bloqueando viagem etérea. Essa magia não pode ser dissipada por dissipar magia.', '1 ação', 30, '1 hora', NULL, TRUE, TRUE, TRUE, 7, 'Evocação'),
(273, 'Proibição', 'Você cria uma defesa contra viagem mágica que protege até 12.000 metros quadrados de solo até 9 metros de altura do solo. Pela duração, criaturas não conseguem se teletransportar para dentro da área ou usar portais, como os criados pela magia portal, para entrar na área. A magia protege a área contra viagem planar e, portanto, impede criaturas de acessarem a área por meio do Plano Astra, Plano Etéreo, Faéria, Umbra ou pela magia viagem planar. Além disso, a magia causa dano a certos tipos de criatura, à sua escolha, quando a conjurar. Escolha um ou mais dentre os seguintes: celestiais, corruptores, elementais, fadas ou mortos-vivos. Quando uma criatura escolhida entrar na área da magia pela primeira vez em um turno ou começa seu turno nela, a criatura sofre 5d6 de dano radiante ou necrótico (à sua escolha, quando você conjura a magia). Quando você conjura essa magia, você pode definir uma senha. Uma criatura que falar a senha quando entrar na área não sofrerá dano dessa magia. A área da magia não pode sobrepor a área de outra magia proibição. Se você conjurar proibição a cada dia por 30 dias no mesmo local, a magia durará até ser dissipada, e os componentes materiais serão consumidos apenas na última conjuração.', '10 minutos', 1, '1 dia', '5d6', TRUE, TRUE, TRUE, 6, 'Abjuração'),
(274, 'Projeção Astral', 'Você e até oito criaturas voluntárias dentro do alcance da magia projetam seus corpos astrais no Plano Astral (a magia falha e a conjuração é desperdiçada caso você já se encontre nesse plano). O corpo material que você deixa para trás fica inconsciente e em estado de animação suspensa; ele não precisa de comida ou ar e não envelhece.', '1 hora', 3, 'Especial', NULL, TRUE, TRUE, TRUE, 9, 'Necromancia'),
(275, 'Projetar Imagem', 'Você cria uma cópia ilusória de si mesmo, que permanece pela duração. A cópia pode aparecer em qualquer lugar, dentro do alcance, que você já tenha visto antes, independentemente da intervenção de obstáculos. A ilusão se parece e fala como você, mas é intangível. Se a ilusão sofrer qualquer dano, ela desaparece e a magia acaba. Você pode ver através dos olhos e ouvir através dos ouvidos da cópia como se você estivesse no lugar dela. Em cada um dos seus turnos, com uma ação bônus, você pode trocar o uso dos sentidos dela pelo seu ou voltar novamente. Enquanto você está usando os sentidos dela, você fica cego e surdo ao que está a sua volta. Interação física com a imagem revelará ela como sendo uma ilusão, já que as coisas podem atravessa-la. Uma criatura que usar sua ação para examinar a imagem, pode determinar que ela é uma ilusão sendo bem sucedida num teste de Inteligência (Investigação) contra a CD da magia para desacredita-la. Se a criatura discernir a ilusão como ela é, a criatura poderá ver através da imagem e qualquer barulho que ela fizer soará oco para a criatura.', '1 ação', 750000, 'Concentração, até 1 dia', NULL, TRUE, TRUE, TRUE, 7, 'Ilusão'),
(276, 'Proteção contra a Morte', 'Ao tocar uma criatura, você lhe concede alguma medida de proteção contra a morte. Na primeira vez que ela sofrer dano e isso reduzir-lhe os pontos de vida a 0, ela volta a ter 1 ponto de vida e a magia termina. Se a magia ainda estiver em ação quando a criatura for submetida a um efeito que a mataria instantaneamente sem causar dano, esse efeito é anulado e a magia termina.', '1 ação', 1, '8 horas', NULL, TRUE, TRUE, FALSE, 4, 'Abjuração'),
(277, 'Proteção contra Energia', 'Você toca uma criatura voluntária. Enquanto a magia durar, o alvo passa a ter resistência a um tipo de dano à sua escolha: ácido, elétrico, ígneo, gélido ou trovejante.', '1 ação', 1, 'Concentração, até 1 hora', NULL, TRUE, TRUE, FALSE, 3, 'Abjuração'),
(278, 'Proteção contra Lâminas', 'Você estende a sua mão e traça um símbolo de proteção no ar. Até o final do seu próximo turno, você tem resistência contra dano contundente, cortante e perfurante causado por ataques armados.', '1 ação', 0, '1 rodada', NULL, TRUE, TRUE, FALSE, 0, 'Abjuração'),
(279, 'Proteção contra o Bem e Mal', 'Enquanto a magia durar, uma criatura voluntária tocada por você passa a ter proteção contra certos tipos de criaturas: aberrações, celestiais, elementais, feéricos, ínferos e mortos-vivos. Criaturas destes tipos têm desvantagem nas jogadas de ataque contra o alvo, e o alvo não pode ser amedrontado, enfeitiçado ou possuído por elas. Se o alvo já estiver amedrontado, enfeitiçado ou possuído por estas criaturas, ele terá vantagem sobre qualquer nova salvaguarda contra o efeito relevante.', '1 ação', 1, 'Concentração, até 10 minutos', NULL, TRUE, TRUE, TRUE, 1, 'Abjuração'),
(280, 'Proteção contra Veneno', 'Você toca uma criatura. Se ela estiver envenenada, você neutraliza o veneno. Se mais de um veneno afligir o alvo, você neutraliza o veneno que sabe estar presente, ou neutraliza um se não souber qual. Pelas próximas 24 horas, o alvo tem vantagem em salvaguardas contra veneno.', '1 ação', 1, '1 hora', NULL, TRUE, TRUE, FALSE, 2, 'Abjuração'),
(281, 'Proteger Fortaleza', 'Você cria uma defesa que protege até 225 metros quadrados de espaço (uma área de um quadrado de 15 metros ou cem quadrados de 1,5 metro ou vinte e cinco quadrados de 3 metros). A área protegida pode ter até 6 metros de altura, no formado que você desejar. Você pode proteger diversos armazéns de uma fortaleza dividindo a área entre eles, contanto que você possa andar em cada área contígua enquanto estiver conjurando a magia. Quando você conjura essa magia, você pode especificar indivíduos que não serão afetados por qualquer dos efeitos que você escolher. Você também pode especificar uma senha que, ao ser falada em voz alta, deixa o orador imune aos efeitos. Proteger fortaleza cria os seguintes efeitos dentro da área protegida. Corredores. Névoa preenche todos os corredores protegidos, tornando-os área de escuridão densa. Além disso, cada interseção ou passagem ramificada oferecendo uma escolha de direção, há 50 por cento de chance de uma criatura diferente de você acredite que está indo na direção oposta à que escolheu. Portas. Todas as portas na área protegida estão trancadas magicamente, como se estivessem seladas pela magia tranca arcana. Além disso, você pode cobrir até dez portas com uma ilusão (equivalente a função de objeto ilusório da magia ilusão menor) para fazê-las parecer seções simples da parede. Escadas. Teias preenchem todas as escadas na área protegida do topo ao solo, como a magia teia. Esses fios voltam a crescer em 10 minutos se forem queimados ou partidos enquanto proteger fortaleza durar. Outros Efeitos de Magia. Você pode colocar, à sua escolha, um dos seguintes efeitos mágicos dentro da área protegida de uma fortaleza.  Colocar globos de luz em quatro corredores. Você pode designar uma programação simples que as luzes repetem enquanto proteger fortaleza durar.  Colocar boca encantada em duas localizações.  Colocar névoa fétida em duas localizações. Os vapores aparecem nos locais que você designar; eles retornam dentro de 10 minutos, se forem dispersados por um vento, enquanto proteger fortaleza durar.  Colocar uma lufada de vento constante em um corredor ou aposento.  Colocar uma sugestão em uma localização. Você seleciona uma área de um quadrado de 1,5 metro e, qualquer criatura que entrar ou passar através dessa área recebe a sugestão mentalmente. A área protegida inteira irradia magia. Uma dissipar magia conjurada em uma área especifica, se for bem sucedida, remove apenas aquele efeito. Você pode criar uma estrutura, permanentemente, afetada por proteger fortaleza ao conjurar essa magia nela a cada dia por um ano.', '10 minutos', 1, '24 horas', NULL, TRUE, TRUE, TRUE, 6, 'Abjuração'),
(282, 'Purificar Alimentos', 'Toda a comida e bebida não-mágica dentro de uma esfera de 1,5 metro de raio centrada em um ponto à sua escolha, no alcance da magia, é purificada e tornada livre de venenos e doenças.', '1 ação', 3, 'Instantânea', NULL, TRUE, TRUE, FALSE, 1, 'Transmutação'),
(283, 'Queda Suave', 'Escolha até cinco criaturas no alcance da magia e que estejam caindo. A velocidade de queda de uma criatura é reduzida para 18 metros por rodada enquanto a magia durar. Se a criatura pousar antes do fim da magia, não sofrerá dano por queda, podendo aterrissar em pé, e a magia se encerra para ela.', '1 reação', 18, '1 minuto', NULL, TRUE, FALSE, TRUE, 1, 'Transmutação'),
(284, 'Raio Adoecente', 'Um raio adoecente de energia esverdeada chicoteia na direção de uma criatura dentro do alcance. Faça um ataque à distância com magia contra o alvo. Se atingir, o alvo sofrerá 2d8 de dano de veneno e deve realizar um teste de resistência de Constituição. Se falhar na resistência, ele também ficará envenenado até o final do seu próximo turno. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 2° nível ou superior, o dano da magia aumenta em 1d8 para cada nível do espaço acima do 1°.', '1 ação', 18, 'Instantânea', '2d8', TRUE, TRUE, FALSE, 1, 'Necromancia'),
(285, 'Raio Ardente', 'Você cria três raios de fogo e os arremessa em alvos dentro do alcance. Você pode arremessa-los em um alvo ou em vários. Realize um ataque à distância com magia para cada raio. Se atingir, o alvo sofrerá 2d6 de dano de fogo. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 3° nível ou superior, você cria um raio adicional para cada nível do espaço acima do 2°.', '1 ação', 36, 'Instantânea', '2d6', TRUE, TRUE, FALSE, 2, 'Evocação'),
(286, 'Raio de Bruxa', 'Um raio crepitante de energia azul é arremessado em uma criatura dentro do alcance, formando um arco elétrico contínuo entre você e o alvo. Faça um ataque à distância com magia contra a criatura. Se atingir, o alvo sofrerá 1d12 de dano elétrico e, em cada um dos seus turnos, pela duração, você pode usar sua ação para causar 1d12 de dano elétrico ao alvo, automaticamente. A magia acaba se você usar sua ação para fazer qualquer outra coisa. A magia também acaba se o alvo estiver fora do alcance da magia ou se você tiver cobertura total para ele. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 2° nível ou superior, o dano inicial aumenta em 1d12 para cada nível do espaço acima do 1°.', '1 ação', 9, 'Concentração, até 1 minuto', '1d12', TRUE, TRUE, TRUE, 1, 'Evocação'),
(287, 'Raio de Fogo', 'Você lança uma faísca de fogo em uma criatura ou objeto no alcance da magia. Faça um ataque mágico à distância contra o alvo. Se acertar, o alvo sofre 1d10 pontos de dano ígneo. Um objeto inflamável atingido por esta magia inflama-se caso não esteja sendo vestido ou carregado. O dano desta magia aumenta em 1d10 quando você alcança o 5° nível (2d10), o 11° nível (3d10) e o 17° nível (4d10).', '1 ação', 36, 'Instantânea', '1d10', TRUE, TRUE, FALSE, 0, 'Evocação'),
(288, 'Raio de Gelo', 'Um feixe branco-azulado, luminoso e gélido parte na direção de uma criatura no alcance da magia. Faça um ataque mágico à distância contra o alvo. Se acertar, o alvo sofre 1d8 pontos de dano gélido e o deslocamento dele é reduzido em 3 metros até o começo do seu próximo turno. O dano desta magia aumenta em 1d8 quando você alcança o 5° nível (2d8), o 11° nível (3d8) e o 17° nível (4d8).', '1 ação', 18, 'Instantânea', '1d8', TRUE, TRUE, FALSE, 0, 'Evocação'),
(289, 'Raio do Enfraquecimento', 'Um feixe negro de energia debilitante brota do seu dedo em direção a uma criatura no alcance da magia. Faça um ataque mágico à distância contra o alvo. Se acertar, enquanto a magia durar, o alvo passa a causar apenas metade do dano em ataques armados que usem Força. No final de cada um dos próprios turnos, o alvo pode fazer uma salvaguarda de Constituição contra a magia. Em caso de sucesso, a magia se encerra.', '1 ação', 18, 'Concentração, até 1 minuto', NULL, TRUE, TRUE, FALSE, 2, 'Necromancia'),
(290, 'Raio Guiador', 'Um lampejo de luz se lança em direção de uma criatura, à sua escolha, dentro do alcance. Realize um ataque à distância com magia contra o alvo. Se atingir, o alvo sofre 4d6 de dano radiante e, a próxima jogada de ataque contra esse alvo, antes do final do seu próximo turno, terá vantagem, graças a penumbra mística cintilando no alvo, até então. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 2° nível ou superior, o dano aumenta em 1d6 para cada nível do espaço acima do 1°.', '1 ação', 36, '1 rodada', '4d6', TRUE, TRUE, FALSE, 1, 'Evocação'),
(291, 'Raio Lunar', 'Um raio prateado de luz pálida brilha para baixo em um cilindro com 1,5 metro de raio e 12 metros de altura, centrado num ponto dentro do alcance. Até a magia acabar, penumbra preenche o cilindro. Quando uma criatura entrar na área da magia pela primeira vez em um turno, ou começar seu turno lá, ela é engolfada por chamas fantasmagóricas que causam dores lancinantes e ela deve realizar um teste de resistência de Constituição. Ela sofre 2d10 de dano radiante se falhar na resistência ou metade desse dano se passar. Um metamorfo faz seu teste de resistência com desvantagem. Se ele falhar, ele, também, reverte instantaneamente para sua forma original e não pode assumir uma forma diferente até deixar a luz da magia. Em cada um dos seus turnos após conjurar essa magia, você pode usar uma ação para mover o raio até 18 metros em qualquer direção. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 3° nível ou superior, o dano aumenta em 1d10 para cada nível do espaço acima do 2°.', '1 ação', 36, 'Concentração, até 1 minuto', '2d10', TRUE, TRUE, TRUE, 2, 'Evocação'),
(292, 'Raio Solar', 'Um feixe de luz brilhante surge da sua mão em uma linha de 1,5 metro de largura por 18 metros de comprimento. Cada criatura na linha deve fazer uma salvaguarda de Constituição. Se falhar, sofre 6d8 pontos de dano radiante e fica cega até o seu próximo turno, ou metade do dano e não fica cega em caso de sucesso. Mortos-vivos e gosmas têm desvantagem nesta salvaguarda.', '1 ação', 0, 'Concentração, até 1 minuto', '6d8', TRUE, TRUE, TRUE, 6, 'Evocação'),
(293, 'Rajada de Veneno', 'Você estende a sua mão, projetando um sopro de gás nocivo da sua palma, que segue em direção a uma criatura à sua vista e no alcance da magia. A criatura deve ser bem-sucedida em uma salvaguarda de Constituição ou sofre 1d12 pontos de dano venenoso. O dano desta magia aumenta em 1d12 quando você alcança o 5° nível (2d12), o 11° nível (3d12) e o 17° nível (4d12).', '1 ação', 3, 'Instantânea', '1d12', TRUE, TRUE, FALSE, 0, 'Conjuração'),
(294, 'Rajada Mística', 'Um raio de energia crepitante salta na direção de uma criatura dentro do alcance da magia. Faça um ataque mágico à distância contra o alvo. Se acertar, o alvo sofre 1d10 pontos de dano de força.', '1 ação', 36, 'Instantânea', '1d10', TRUE, TRUE, FALSE, 0, 'Evocação'),
(295, 'Rajada Prismática', 'Oito raios de luz multicoloridos saem da sua mão. Cada raio possui uma cor única, com poder e propósito diferente. Cada criatura em um cone de 18 metros deve fazer uma salvaguarda de Destreza. Para cada alvo, jogue 1d8 para determinar que raio o afeta, causando um tipo de dano diferente (ígneo, ácido, elétrico, entre outros efeitos) de 10d6 pontos, ou metade do dano em caso de sucesso.', '1 ação', 0, 'Instantânea', '10d6', TRUE, TRUE, FALSE, 7, 'Evocação'),
(296, 'Recipiente Arcano', 'Seu corpo entra em um estado catatônico, enquanto sua alma o abandona e entra num recipiente que você usa como componente material da magia. Enquanto sua alma permanecer no recipiente, você estará ciente do seu entorno como se você estivesse no espaço do recipiente. Você não pode se mover ou usar reações. A única ação que você pode realizar é projetar sua alma a até 30 metros do recipiente, tanto para retornar para o seu corpo (terminando a magia) ou para tentar possuir um corpo humanoide. Você pode tentar possuir qualquer humanoide a até 30 metros de você que você possa ver (criaturas protegidas pelas magias proteção contra o bem e mal ou círculo mágico não podem ser possuídas). O alvo deve realizar um teste de resistência de Carisma. Se falhar, sua alma se move para o corpo do alvo e a alma do alvo fica aprisionada no recipiente. Se obtiver sucesso, o alvo resiste aos seus esforços em possuí-lo e você não poderá tentar possuí-lo novamente por 24 horas. Uma vez que tenha possuído o corpo de uma criatura, você a controla. Suas estatísticas de jogo são substituídas pelas estatísticas da criatura, no entanto, você mantem sua tendência e seus valores de Inteligência, Sabedoria e Carisma. Você mantem os benefícios das suas características de classe. Se o alvo tiver quaisquer níveis de classe, você não pode usar quaisquer das características de classe dele. Nesse período, a alma da criatura possuída pode perceber do recipiente usando os sentidos dela, mas, no mais, não pode se mover ou realizar quaisquer ações. Enquanto estiver possuindo um corpo, você pode usar sua ação para retornar do corpo do hospedeiro para o recipiente se ele estiver a até 30 metros de você, devolvendo a alma da criatura hospedeira para o corpo dela. Se o corpo do hospedeiro morrer enquanto você estiver dentro dele, a criatura morre e você deve realizar um teste de resistência de Carisma contra a sua CD de conjuração. Se obtiver sucesso, você retorna ao recipiente se ele estiver a até 30 metros de você. Caso contrário, você morre. Se o recipiente for destruído ou a magia acabar, sua alma, imediatamente, retorna para o seu corpo. Se seu corpo estiver a mais de 30 metros de você ou se seu corpo estiver morto quando você tentar retornar para ele, você morre. Se a alma de outra criatura estiver no recipiente quando ele for destruído, a alma da criatura volta para o corpo dela se o corpo estiver vivo e a até 30 metros dela. Caso contrário, a criatura morre. Quando a magia acabar, o recipiente é destruído.', '1 minuto', 0, 'Até ser dissipada', NULL, TRUE, TRUE, TRUE, 6, 'Necromancia'),
(297, 'Recuo Acelerado', 'Esta magia permite que você se mova em um ritmo incrível. Ao conjurá-la, e depois com uma ação bônus em cada um dos seus turnos, você pode executar a ação Correr.', '1 ação bônus', 0, 'Concentração, até 10 minutos', NULL, TRUE, TRUE, FALSE, 1, 'Transmutação'),
(298, 'Reencarnação', 'Você toca um humanoide morto ou um pedaço de um humanoide morto. Considerando que a criatura não esteja morta a mais de 10 dias, a magia forma um novo corpo adulto para ele e então, chama a alma para entrar no corpo. Se a alam do alvo não estiver livre ou deseje fazê lo, a magia falha. A magia forma um novo corpo para que a criatura habite, o que, provavelmente, fará com que a raça da criatura mude. O Mestre rola um d100 e consulta a tabela seguinte para determinar qual forma a criatura terá quando voltar a vida, ou o Mestre pode escolher uma forma. d100 Raça 01–04 Draconato 05–13 Anão, colina 14–21 Anão, montanha 22–25 Elfo, negro 26–34 Elfo, alto 35–42 Elfo, floresta 43–46 Gnomo, floresta 47–52 Gnomo, rochas 53–56 Meio-elfo 57–60 Meio-orc 61–68 Halfling, pés leves 69–76 Halfling, robusto 77–96 97–00 Humano Tiefling A criatura reencarnada lembra-se da sua vida e experiências anteriores. Ela mantem as capacidades que a sua forma original tinha, exceto por trocar sua raça original pela nova e mudar suas características raciais adequadamente.', '1 hora', 1, 'Instantânea', NULL, TRUE, TRUE, TRUE, 5, 'Transmutação'),
(299, 'Reflexos', 'Três duplicatas ilusórias de você aparecem no seu espaço. Enquanto a magia durar, as duplicatas se movem com você e imitam suas ações e mudanças de posição, tornando impossível distinguir qual das imagens é a verdadeira. Você pode usar uma ação para dispensar as duplicatas ilusórias. Enquanto a magia durar, cada vez que uma criatura tem você como alvo de um ataque, jogue 1d20 para determinar se ela ataca uma das suas duplicatas. Caso tenha três duplicatas, você deve tirar 6 ou mais para mudar o ataque para uma cópia. Com duas duplicatas, você deve tirar um 8 ou mais. Com uma duplicata, você deve tirar um 11 ou mais.', '1 ação', 0, '1 minuto', NULL, TRUE, TRUE, FALSE, 2, 'Ilusão'),
(300, 'Regeneração', 'Você toca uma criatura e estimula sua capacidade natural de cura. O alvo recupera 4d8+15 pontos de vida. Enquanto a magia durar, o alvo recupera 1 ponto de vida no começo de cada turno dele (10 pontos de vida por minuto).', '1 minuto', 1, '1 hora', '4d8+15', TRUE, TRUE, TRUE, 7, 'Transmutação'),
(301, 'Relâmpago', 'Um relâmpago forma uma linha de 30 metros de comprimento e 1,5 metro de largura que é disparado por você em uma direção, à sua escolha. Cada criatura na linha deve realizar um teste de resistência de Destreza. Uma criatura sofre 8d6 de dano elétrico se falhar na resistência ou metade desse dano se obtiver sucesso. O relâmpago incendeia objetos inflamáveis na área que não estejam sendo vestidos ou carregados. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 4° nível ou superior, o dano aumenta em 1d6 para cada nível do espaço acima do 3°.', '1 ação', 0, 'Instantânea', '8d6', TRUE, TRUE, TRUE, 3, 'Evocação'),
(302, 'Remover Maldição', 'Ao tocar uma criatura ou objeto, todas as maldições lançadas sobre eles se encerram. Se o objeto for um item mágico amaldiçoado, a maldição se mantém, mas a magia quebra a sintonia do dono com o objeto, de modo que ele pode ser removido ou descartado.', '1 ação', 1, 'Instantânea', NULL, TRUE, TRUE, FALSE, 3, 'Abjuração'),
(303, 'Repouso Tranquilo', 'Você toca um cadáver ou outros restos mortais. Enquanto a magia durar, o alvo está protegido da decomposição e não pode se tornar um morto-vivo. A magia também estende efetivamente o tempo limite para trazer o alvo dos mortos, pois os dias passados sob a influência desta magia não contam contra o tempo limite de magias como reviver os mortos.', '1 ação', 1, '10 dias', NULL, TRUE, TRUE, TRUE, 2, 'Necromancia'),
(304, 'Repreensão Infernal', 'Você aponta seu dedo e a criatura que causou dano a você é, momentaneamente, envolta por chamas infernais. A criatura deve realizar um teste de resistência de Destreza. Ela sofre 2d10 de dano de fogo se falhar na resistência ou metade desse dano se obtiver sucesso. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 2° nível ou superior, o dano aumenta em 1d10 para cada nível do espaço acima do 1°.', '1 reação', 18, 'Instantânea', '2d10', TRUE, TRUE, FALSE, 1, 'Evocação'),
(305, 'Resistência', 'Você toca uma criatura voluntária. Uma vez antes da magia terminar, o alvo pode jogar 1d4 e adicionar o número a uma salvaguarda à sua escolha. Ele pode jogar o dado antes ou depois de fazer a salvaguarda. A magia, então, se encerra.', '1 ação', 1, 'Concentração, até 1 minuto', NULL, TRUE, TRUE, TRUE, 0, 'Abjuração'),
(306, 'Respirar na Água', 'Até dez criaturas voluntárias à sua vista e no alcance da magia ganham a habilidade de respirar embaixo d''água até o fim da magia.', '1 ação', 9, '24 horas', NULL, TRUE, TRUE, TRUE, 3, 'Transmutação'),
(307, 'Ressurreição', 'Você toca uma criatura, morta há não mais do que dois séculos e que tenha morrido por qualquer motivo, exceto por idade avançada. Se a alma dela estiver livre e disposta, a criatura retorna à vida com todos os pontos de vida. Esta magia fecha todas as feridas, neutraliza qualquer veneno, cura todas as doenças e cancela quaisquer maldições que afetavam a criatura quando ela morreu. Membros ou órgãos amputados ou danificados são restabelecidos.', '1 hora', 1, 'Instantânea', NULL, TRUE, TRUE, TRUE, 7, 'Necromancia'),
(308, 'Ressurreição Verdadeira', 'Você toca uma criatura que tenha morrido há não mais de 200 anos e que não tenha morrido de velhice. A magia neutraliza todos os efeitos que impediriam a criatura de ser trazida de volta à vida. O alvo é revivido com todos os pontos de vida, e membros ou órgãos amputados ou danificados são restabelecidos. A magia pode até fornecer um novo corpo se o original não existir mais; nesse caso, basta falar o nome da criatura, e ela aparece em um espaço desocupado à sua escolha a até 3 metros de você.', '1 hora', 1, 'Instantânea', NULL, TRUE, TRUE, TRUE, 9, 'Necromancia'),
(309, 'Restauração Maior', 'Você imbui uma criatura que você toca, com energia positiva para desfazer um efeito debilitante. Você pode reduzir a exaustão do alvo em um nível ou remover um dos seguintes do alvo:  Um efeito que enfeitice ou petrifique o alvo  Uma maldição, incluindo a sintonização do alvo com um item mágico amaldiçoado  Qualquer redução a um dos valores de habilidade do alvo  Um efeito que esteja reduzindo o máximo de pontos de vida do alvo', '1 ação', 1, 'Instantânea', NULL, TRUE, TRUE, TRUE, 5, 'Abjuração'),
(310, 'Restauração Menor', 'Você toca uma criatura e pode tanto curar uma doença quanto remover uma condição que a aflija. A condição pode ser cego, envenenado, paralisado ou surdo.', '1 ação', 1, 'Instantânea', NULL, TRUE, TRUE, FALSE, 2, 'Abjuração'),
(311, 'Reviver os Mortos', 'Uma criatura que você toca retorna dos mortos, desde que não tenha falecido há mais de 10 dias. Se a alma dela estiver disposta e livre para retornar ao corpo, ela retorna à vida com 1 ponto de vida. A magia também neutraliza quaisquer venenos e cura doenças não-mágicas que a afetavam no momento em que morreu. Esta magia não retorna um morto-vivo à vida.', '1 hora', 1, 'Instantânea', NULL, TRUE, TRUE, TRUE, 5, 'Necromancia'),
(312, 'Revivificar', 'Você toca uma criatura que faleceu há menos de um minuto. Aquela criatura volta à vida com 1 ponto de vida. A magia não pode retornar quem morreu de idade avançada, nem pode restaurar quaisquer partes perdidas do corpo.', '1 ação', 1, 'Instantânea', NULL, TRUE, TRUE, TRUE, 3, 'Necromancia'),
(313, 'Riso Histérico de Tasha', 'Você escolhe uma criatura à sua vista e no alcance da magia, que passa a perceber tudo como hilariantemente engraçado, sofrendo ataques de riso, caso seja afetada pela magia. O alvo deve ser bem-sucedido em uma salvaguarda de Sabedoria ou fica caído, incapacitado e incapaz de se levantar enquanto a magia durar. Uma criatura de Inteligência 4 ou menos não pode ser afetada.', '1 ação', 9, 'Concentração, até 1 minuto', NULL, TRUE, TRUE, TRUE, 1, 'Encantamento'),
(314, 'Rogar Maldição', 'Você toca uma criatura e a criatura deve ser bem sucedida em um teste de resistência de Sabedoria ou será amaldiçoada pela duração da magia. Quando você conjura essa magia, escolha a natureza da maldição dentre as seguintes opções:  Escolha um valor de habilidade. Enquanto amaldiçoado, o alvo tem desvantagem em testes de habilidade e testes de resistência feitos com esse valor de habilidade,  Enquanto amaldiçoado, o alvo tem desvantagem nas jogadas de ataque contra você.  Enquanto amaldiçoado, o alvo deve realizar um teste de resistência de Sabedoria no começo de cada um dos turnos dela. Se ela falhar, ela perderá sua ação aquele turno, não fazendo nada.  Enquanto o alvo estiver amaldiçoado, seus ataques e magias causam 1d8 de dano necrótico extra a ele. Uma magia remover maldição termina esse efeito. Com a permissão do Mestre, você pode escolher um efeito alternativo de maldição, mas ele não deve ser mais poderoso que os descritos acima. O Mestre tem a palavra final sobre o efeito de uma maldição. Em Níveis Superiores. Se você conjurar essa magia usando um espaço de magia de 4° nível, a duração da concentração sobe para 10 minutos. Se você usar um espaço de magia de 5° ou 6° nível, a duração será de 8 horas. Se você usar um espaço de magia de 7° ou 8° nível, a duração será de 24 horas. Se você usar um espaço de magia de 9° nível, a magia dura até ser dissipada. Usar um espaço de magia de 5° nível ou superior faz com que a duração não necessite de concentração.', '1 ação', 1, 'Concentração, até 1 minuto', '1d8', TRUE, TRUE, FALSE, 3, 'Necromancia'),
(315, 'Salto', 'Você toca uma criatura. Enquanto a magia durar, a distância de salto da criatura é triplicada.', '1 ação', 1, '1 minuto', NULL, TRUE, TRUE, TRUE, 1, 'Transmutação'),
(316, 'Santuário', 'Você protege uma criatura que esteja dentro do alcance da magia contra ataques. Enquanto a magia durar, qualquer criatura que tenha a criatura protegida como alvo de um ataque ou de uma magia prejudicial deve antes fazer uma salvaguarda de Sabedoria. Se falhar, o atacante deve escolher outro alvo ou perderá o ataque ou magia. Esta magia não garante ao alvo proteção contra efeitos de área.', '1 ação bônus', 9, '1 minuto', NULL, TRUE, TRUE, TRUE, 1, 'Abjuração'),
(317, 'Santuário Particular de Mordenkainen', 'Você deixa uma área, dentro do alcance, magicamente segura. A área é um cubo que pode ser tão pequeno quanto 1,5 metro ou tão grande quanto 30 metros de cada lado. A magia permanece pela duração ou até você usar uma ação para dissipa-la. Quando você conjura essa magia, você decide que tipo de segurança ela fornecerá, escolhendo qualquer ou todas as propriedades a seguir:  Sons não podem atravessar a barreira na fronteira da área protegida.  A barreira da área protegida escura e nebulosa, impedindo visão (inclusive visão no escuro) através dela.  Sensores criados por magia de adivinhação não podem aparecer dentro da área protegida ou atravessar a barreira no perímetro.  As criaturas na área não podem ser alvo de magias de adivinhação.  Nada pode se teletransportar para dentro ou para fora da área protegida.  Viagem planar está bloqueada para dentro da área protegida. Conjurar essa magia no mesmo lugar, a cada dia, por um ano, torna o efeito permanente. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 5° nível ou superior, você pode aumentar o tamanho do cubo em 30 metros de cada lado para cada nível do espaço acima do 4°. Então, você poderia proteger um cubo de até 60 metros de lado usando um espaço de magia de 5° nível.', '10 minutos', 36, '24 horas', NULL, TRUE, TRUE, TRUE, 4, 'Abjuração'),
(318, 'Saraivada de Espinhos', 'Da próxima vez que você atingir uma criatura com um ataque à distância com arma, antes da magia acabar, essa magia cria uma chuva de espinhos que brota da sua arma à distância ou munição. Além do efeito normal do ataque, o alvo do ataque e cada criatura a até 1,5 metro dele, devem realizar um teste de resistência de Destreza. Uma criatura sofre 1d10 de dano perfurante se falhar na resistência ou metade desse dano se obtiver sucesso. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 2° nível ou superior, o dano aumenta em 1d10 para cada nível do espaço acima do 1° (até o máximo de 6d10).', '1 ação bônus', 0, 'Concentração, até 1 minuto', '1d10', TRUE, FALSE, FALSE, 1, 'Conjuração'),
(319, 'Semiplano', 'Você cria uma porta de sombras em uma superfície sólida e plana, à sua vista e dentro do alcance da magia. A porta é grande o suficiente para permitir que uma criatura Média passe sem impedimento. Quando aberta, a porta leva para um semiplano que parece ser um quarto vazio, com 9 metros em cada dimensão, feito de madeira ou pedra. Quando a magia termina, a porta desaparece e quaisquer criaturas ou objetos dentro do semiplano ficam presos ali, já que a porta também desaparece do outro lado.', '1 ação', 18, '1 hora', NULL, TRUE, FALSE, FALSE, 8, 'Conjuração'),
(320, 'Sentido Bestial', 'Você toca uma besta voluntária. Pela duração da magia, você pode usar sua ação para ver através dos olhos e ouvir através dos ouvidos da besta e continua a fazê-lo até você usar sua ação para retornar aos seus sentidos normais. Enquanto estiver utilizando os sentidos da besta, você ganha os benefícios de qualquer sentido especial possuído pela criatura, no entanto, você estará cego e surdo em relação aos seus próprios sentidos.', '1 ação', 1, 'Concentração, até 1 hora', NULL, FALSE, TRUE, FALSE, 2, 'Adivinhação'),
(321, 'Servo Invisível', 'Esta magia cria uma força invisível, irracional e amorfa que cumpre tarefas simples dadas por você. O servo surge em um espaço desocupado sobre o solo no alcance da magia. Ele tem CA 10, 1 ponto de vida, Força 2 e não pode atacar. Se ele cair para 0 ponto de vida, a magia se encerra. Uma vez em cada um dos seus turnos, com uma ação bônus, você pode comandar mentalmente o servo a se mover até 4,5 metros e interagir com um objeto. O servo pode executar tarefas simples que um servo humano poderia fazer, como buscar coisas, limpar, remendar, dobrar roupas, acender fogo, servir comida e servir vinho.', '1 ação', 18, '1 hora', NULL, TRUE, TRUE, TRUE, 1, 'Conjuração'),
(322, 'Sexto Sentido', 'Você toca uma criatura voluntária e a abençoa com uma habilidade limitada de ver o futuro iminente. Pela duração, o alvo não pode ser surpreendido e tem vantagem nas jogadas de ataque, testes de habilidade e testes de resistência. Além disso, outras criaturas tem desvantagem nas jogadas de ataque contra o alvo, pela duração. Essa magia termina imediatamente, se você conjura-la novamente antes da duração acabar.', '1 minuto', 1, '8 horas', NULL, TRUE, TRUE, TRUE, 9, 'Adivinhação'),
(323, 'Silêncio', 'Enquanto a magia durar, nenhum som pode ser criado dentro ou passar através de uma esfera de 6 metros de raio, centrado em um ponto à sua escolha e no alcance da magia.', '1 ação', 36, 'Concentração, até 10 minutos', NULL, TRUE, TRUE, FALSE, 2, 'Ilusão'),
(324, 'Símbolo', 'Quando você conjura essa magia, você inscreve um glifo nocivo, tanto sobre uma superfície (como uma secção de piso, uma parede ou mesa) quanto dentro de um objeto que possa ser fechado (como um livro, um pergaminho ou um baú de tesouro). Se você escolher uma superfície, o glifo pode cobrir uma área da superfície não superior a 3 metros de diâmetro. Se você escolher um objeto, o objeto deve permanecer no seu local; se ele for movido mais de 3 metros de onde você conjurou essa magia, o glifo será quebrado e a magia termina sem ser ativada. O glifo é quase invisível e requer um teste de Inteligência (Investigação) contra a CD da magia para ser encontrado. Você define o que ativa o glifo quando você conjura a magia. Para glifos inscritos em uma superfície, os gatilhos mais típicos incluem tocar ou ficar sobre o glifo, remover outro objeto cobrindo o glifo, aproximar-se a uma certa distância do glifo ou manipular um objeto onde o glifo esteja inscrito. Para glifos inscritos dentro de objetos, os gatilhos mais comuns incluem abrir o objeto, aproximar se a uma certa distância do objeto ou ver ou ler o glifo. Você pode, posteriormente, aperfeiçoar o gatilho para que a magia se ative apenas sob certas circunstâncias ou de acordo com as características físicas (como altura ou peso), tipo de criatura (por exemplo, a proteção poderia ser definida para afetar aberrações ou drow) ou tendência. Você pode, também, definir condições para criaturas não ativarem o glifo, como aqueles que falarem determinada senha. Quando você inscreve o glifo, escolha uma das opções abaixo para seu efeito. Uma vez ativado, o glifo brilha, preenchendo uma esfera de 18 metros de raio com penumbra por 10 minutos, após esse tempo, a magia termina. Cada criatura na esfera, quando o glifo é ativado, é afetada por seu efeito, assim como uma criatura que entrar na esfera a primeira vez num turno ou termina seu turno nela. Atordoamento. Cada alvo deve realizar um teste de resistência de Sabedoria e ficará atordoada por 1 minuto se falhar na resistência. Desespero. Cada alvo deve realizar um teste de resistência de Carisma. Com uma falha na resistência, o alvo será consumido pelo desespero por 1 minuto. Durante esse período, ele não poderá atacar ou afetar qualquer criatura com habilidades, magias ou outros efeitos mágicos nocivos. Discórdia. Cada alvo deve realizar um teste de resistência de Sabedoria. Com uma falha na resistência, um alvo irá brigar e discutir com outras criaturas por 1 minuto. Durante esse período, ele será incapaz de se comunicar compreensivamente e terá desvantagem nas jogadas de ataque e testes de habilidade. Dor. Cada alvo deve realizar um teste de resistência de Constituição e ficará incapacitada com dores excruciantes por 1 minuto se falhar na resistência. Insanidade. Cada alvo deve realizar um teste de resistência de Inteligência. Com uma falha na resistência, o alvo é levado a loucura por 1 minuto. Uma criatura insana, não pode realizar ações, não entende o que as outras criaturas dizem, não pode ler e fala apenas coisas sem sentido. O Mestre controla seus movimentos, que serão erráticos. Medo. Cada alvo deve realizar um teste de resistência de Sabedoria e ficará amedrontado por 1 minuto se falhar na resistência. Enquanto estiver amedrontado, o alvo largará o que quer que esteja segurando e deve se afastar, pelo menos 9 metros do glifo em cada um dos seus turnos, se for capaz. Morte. Cada alvo deve realizar um teste de resistência de Constituição, sofrendo 10d10 de dano necrótico se falhar na resistência ou metade desse dano se passar na resistência. Sono. Cada alvo deve realizar um teste de resistência de Sabedoria e cairá inconsciente por 10 minutos se falhar na resistência. Uma criatura acorda se sofrer dano ou se alguém usar sua ação para sacudi-la e estapeá-la até ela acordar.', '1 minuto', 1, 'Até ser dissipada', '10d10', TRUE, TRUE, TRUE, 7, 'Abjuração'),
(325, 'Similaridade', 'Esta magia permite que você altere a aparência de qualquer número de criaturas à sua vista e no alcance da magia. Você dá a cada alvo uma nova aparência ilusória, à sua escolha.', '1 ação', 9, '8 horas', NULL, TRUE, TRUE, FALSE, 5, 'Ilusão'),
(326, 'Simulacro', 'Você modela uma duplicata ilusória de uma besta ou humanoide, dentro do alcance, durante todo tempo de conjuração da magia. A duplicada é uma criatura, parcialmente real, formada de gelo ou neve e pode realizar ações e, no mais, ser tratada como uma criatura normal. Ela aparenta ser igual a original, mas tem metade do máximo de pontos de vida da criatura e é formada sem qualquer equipamento. No mais, a ilusão usa todas as estatísticas da criatura que ela copiou. O simulacro é amigável a você e às criaturas que você designar. Ele obedece aos seus comandos verbais, se movendo e agindo de acordo com seus desejos, agindo no seu turno em combate. O simulacro não possui capacidade de aprender ou de se tornar mais poderoso, portanto, ele nunca subirá de nível ou ganhará outras habilidades, nem poderá recuperar espaços de magia gastos. Se o simulacro sofrer dano, você pode repara-lo em um laboratório alquímico, usando ervas e minerais raros no valor de 100 po por ponto de vida recuperado. O simulacro dura até cair a 0 pontos de vida, no momento em que ele volta a ser neve e derrete instantaneamente. Se você conjurar essa magia novamente, qualquer duplicata atualmente ativa, que você criou com essa magia, é instantaneamente destruída.', '12 horas', 1, 'Até ser dissipada', NULL, TRUE, TRUE, TRUE, 7, 'Ilusão'),
(327, 'Sinal de Esperança', 'Esta magia concede esperança e vitalidade. Escolha qualquer número de criaturas dentro do alcance da magia. Durante a duração desta magia, cada alvo terá vantagem em salvaguardas de Sabedoria e contra a morte.', '1 ação', 9, 'Concentração, até 1 minuto', NULL, TRUE, TRUE, FALSE, 3, 'Abjuração'),
(328, 'Sonho', 'Essa magia molda os sonhos de uma criatura. Escolha uma criatura que você conheça como alvo dessa magia. O alvo deve estar no mesmo plano de existência que você. Criaturas que não dormem, como elfos, não podem ser contatados por essa magia. Você, ou uma criatura voluntária que você tocar, entram em um estado de transe. Enquanto estiver me transe, o mensageiro está ciente dos seus arredores, mas não pode realizar ações ou se mover. Se o alvo estiver dormindo, o mensageiro aparece no sonho do alvo e pode conversar com o alvo enquanto ele estiver dormindo, até o limite da duração da magia. O mensageiro também pode modificar o meio ambiente do sonho, criando paisagens, objetos e outras imagens. O mensageiro pode sair do transe a qualquer momento, terminando o efeito da magia prematuramente. O alvo se lembra do sonho perfeitamente quando acorda. Se o alvo estiver acordado quando a magia for conjurada, o mensageiro saberá disso e pode, tanto terminar o transe (e a magia) quando esperar o alvo cair no sono, no momento em que o mensageiro aparecerá nos sonhos do alvo. Você pode fazer o mensageiro parecer monstruoso e aterrorizante para o alvo. Se o fizer, o mensageiro pode enviar uma mensagem de não mais que dez palavras, então o alvo deve realizar um teste de resistência de Sabedoria. Se falhar na resistência, ecos da monstruosidade fantasmagórica criarão um pesadelo que permanecerá pela duração do sono do alvo e impede o alvo de ganhar qualquer benefício do descanso. Além disso, quando o alvo acordar, ele sofrerá 3d6 de dano psíquico. Se você tiver uma parte do corpo, mecha de cabelo, recorte de unha ou porção similar do corpo do alvo, o alvo realiza seu teste de resistência com desvantagem.', '1 minuto', 9999, '8 horas', '3d6', TRUE, TRUE, TRUE, 5, 'Ilusão'),
(329, 'Sono', 'Essa magia põem as criaturas num entorpecimento mágico. Jogue 5d8; o total é a quantidade de pontos de vida de criaturas afetados pela magia. As criaturas numa área de 6 metros de raio, centrada no ponto escolhido, dentro do alcance, são afetadas em ordem ascendente dos pontos de vida atuais delas (ignorando criaturas inconscientes). Começando com as criaturas com menos pontos de vida atuais, cada criatura afetada por essa magia cai inconsciente até a magia acabar, sofrer dano ou alguém usar sua ação para sacudi-la ou esbofeteá-la até acordar. Subtraia os pontos de vida de cada criatura do total antes de seguir para a próxima criatura com menos pontos de vida atuais. Os pontos de vida atuais da criatura devem ser iguais ou menores que o valor restante para que a criatura possa ser afetada. Mortos-vivos e criaturas imunes a serem enfeitiçadas não são afetadas por essa magia. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 2º nível ou superior, jogue 2d8 adicionais para cada nível do espaço acima do 1°.', '1 ação', 36, '1 minuto', NULL, TRUE, TRUE, TRUE, 1, 'Encantamento'),
(330, 'Sugestão', 'Você sugere um curso de ação (limitado a uma sentença ou duas) e influencia magicamente uma criatura à sua vista no alcance da magia e que possa lhe ouvir e compreendê-lo. Criaturas que não podem ser enfeitiçadas são imunes a este efeito. A sugestão precisa ser dita de uma forma que faça o curso de ação parecer razoável. Pedir à criatura que se esfaqueie, jogue-se contra uma lança, imole-se ou faça algum outro ato evidentemente danoso, automaticamente cancela o efeito da magia.', '1 ação', 9, 'Concentração, até 8 horas', NULL, TRUE, FALSE, TRUE, 2, 'Encantamento'),
(331, 'Sugestão em Massa', 'Você sugere um curso de atividade (limitado a uma ou duas sentenças) e, magicamente, influencia até dozes criaturas, à sua escolha, que você possa ver dentro do alcance e que possam ouvir e compreender você. Criaturas que não podem ser enfeitiçadas são imunes a esse efeito. A sugestão deve ser formulada de modo que o curso de ação soe razoável. Dizer para a criatura se esfaquear, se arremessar em uma lança, tocar fogo em si mesma ou fazer algum outro ato obviamente nocivo anulará o efeito da magia. Cada alvo deve realizar um teste de resistência de Sabedoria. Se falhar na resistência, ele seguirá o curso de ação que você descreveu, da melhor forma possível. O curso de ação sugerido pode continuar por toda a duração. Por exemplo, você poderia sugeria a um grupo de soldados que deem todo o seu dinheiro para o primeiro mendigo que encontrarem. Se a condição não for atingida antes da magia acabar, a atividade não é realizada. Se você ou um dos seus companheiros causar dano a uma criatura afetada por essa magia, a magia termina para aquela criatura. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 7° nível, a duração será de 10 dias. Quando você usar um espaço de magia de 8° nível, a duração será de 30 dias. Quando você usar um espaço de magia de 9° nível, a duração será de 1 ano e 1 dia.', '1 ação', 18, '24 horas', NULL, TRUE, FALSE, TRUE, 6, 'Encantamento'),
(332, 'Sussurros Dissonantes', 'Você sussurra uma melodia dissonante que apenas uma criatura, à sua escolha, dentro do alcance pode ouvir, causando-lhe uma terrível dor. O alvo deve realizar um teste de resistência de Sabedoria. Se falhar na resistência, ele sofrerá 3d6 de dano psíquico e deve, imediatamente, usar sua reação, se disponível, para se mover para o mais longe possível de você. A criatura não se moverá para um terreno obviamente perigoso, como uma fogueira ou abismo. Se obtiver sucesso na resistência, o alvo sofre metade do dano e não precisa se afastar de você. Uma criatura surda obtém sucesso automaticamente na sua resistência. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 2° nível ou superior, o dano aumenta em 1d6 para cada nível do espaço acima do 1°.', '1 ação', 18, 'Instantânea', '3d6', TRUE, FALSE, FALSE, 1, 'Encantamento'),
(333, 'Taumaturgia', 'Você manifesta um pequeno milagre, um sinal de poder sobrenatural dentro do alcance da magia. Você pode criar um dos seguintes efeitos: sua voz ressoa até três vezes mais alta do que o normal durante 1 minuto; você faz chamas tremularem, clarearem, escurecerem ou mudarem de cor durante 1 minuto; você causa tremores inofensivos no solo durante 1 minuto; você cria um som instantâneo que se origina de um ponto à sua escolha, como o estrondo de um trovão, o grasnar de um corvo ou sussurros sinistros; você instantaneamente faz uma porta ou janela destrancada se abrir ou fechar; ou você altera a aparência dos seus olhos durante 1 minuto. Se conjurar esta magia múltiplas vezes, você pode ter até três dos seus efeitos de 1 minuto ativos ao mesmo tempo, e pode dispensar um deles com uma ação.', '1 ação', 9, 'Até 1 minuto', NULL, TRUE, FALSE, FALSE, 0, 'Transmutação'),
(334, 'Teia', 'Você conjura uma massa de teia espessa e pegajosa em um ponto à sua escolha e no alcance da magia. A teia preenche um cubo de 6 metros a partir daquele ponto enquanto a magia durar. A teia é considerada terreno difícil e torna a área parcialmente obscurecida. Se a teia não estiver sendo sustentada por duas massas sólidas (como paredes ou árvores), ou estiver em camadas cobrindo o chão, parede ou teto, ela colapsa sobre si mesma e a magia se encerra no início do seu próximo turno. Cada criatura que entrar ou iniciar o próprio turno na teia deve fazer uma salvaguarda de Destreza. Se falhar, a criatura fica contida enquanto estiver na teia ou até que consiga se soltar, podendo usar a própria ação para fazer uma salvaguarda de Força para se libertar.', '1 ação', 18, 'Concentração, até 1 hora', '2d4', TRUE, TRUE, TRUE, 2, 'Conjuração'),
(335, 'Telecinésia', 'Você adquire a habilidade de mover ou manipular criaturas ou objetos através do pensamento. Quando você conjura a magia e, com sua ação a cada turno, pela duração, você pode exercer sua vontade sobre uma criatura ou objeto que você possa ver, dentro do alcance, causando os efeitos apropriados abaixo. Você pode afetar o mesmo alvo rodada após rodada, ou escolher um novo a qualquer momento. Se você mudar de alvos, o alvo anterior não será mais afetado pela magia. Criatura. Você pode tentar mover uma criatura Enorme ou menor. Faça um teste de habilidade com sua habilidade de conjuração resistido por um teste Força da criatura. Se você vencer a disputa, você move a criatura até 9 metros em qualquer direção, incluindo para cima, mas não além do alcance da magia. Até o final do seu próximo turno, a criatura estará impedida pelo seu agarrão telecinético. Uma criatura erguida para cima estará suspensa no ar. Em rodadas subsequente, você pode usar sua ação para tentar manter seu agarrão telecinético na criatura repetindo o teste resistido. Objeto. Você pode tentar mover um objeto pesando até 500 quilos. Se o objeto não estiver sendo vestido ou carregado, você o move, automaticamente, até 9 metros em qualquer direção, mas não além do alcance dessa magia. Se o objeto estiver sendo vestido ou carregado por uma criatura, você deve realizar um teste de habilidade com sua habilidade de conjuração resistido por um teste de Força da criatura. Se você for bem sucedido, você arranca o objeto da criatura e o move até 9 metros, em qualquer direção, mas não além do alcance dessa magia. Você pode exercer um controle refinado sobre os objetos com seu agarrão telecinético, como manipular ferramentas simples, abrir uma porta ou um recipiente, guardar ou recuperar um item de um recipiente aberto ou derramar o conteúdo de um frasco.', '1 ação', 18, 'Concentração, até 10 minutos', NULL, TRUE, TRUE, FALSE, 5, 'Transmutação'),
(336, 'Telepatia', 'Você cria uma ligação telepática com uma criatura voluntária com quem já esteja familiarizado. O alvo deve estar no mesmo plano de existência que você; a magia se encerra se isso deixar de ser verdade. Enquanto a magia durar, você e o alvo podem compartilhar palavras, imagens, sons e outras mensagens sensoriais um com o outro através da ligação.', '1 ação', 9999, '24 horas', NULL, TRUE, TRUE, TRUE, 8, 'Evocação'),
(337, 'Teletransporte', 'Essa magia, instantaneamente, transporta você e até oito criaturas voluntárias, à sua escolha, que você possa ver dentro do alcance ou um único objeto que você possa ver no alcance, para um destino que você selecionou. Se você for afetar um objeto, ele deve ser capaz de caber inteiro dentro de um cubo de 3 metros e não pode estar sendo empunhado ou carregado por uma criatura involuntária. O destino que você escolher deve ser conhecido por você e deve ser no mesmo plano de existência que você está. Sua familiaridade com o destino determina se você chegará nele com sucesso. O Mestre rola um d100 e consulta a tabela. Familiaridade Fiasco Círculo permanente – Área Similar – 01–100 Objeto associado – – – 01–100 Muito familiar 01–05 06–13 25–100 Visto casualmente 01–33 34–43 44–53 54–100 Visto uma vez 01–43 44–53 74–100 Descrição 01–43 44–53 54–73 74–100 Descrição falsa 01–50 51–100 Familiaridade. “Círculo permanente” significa um círculo de teletransporte permanente o qual você conhece a sequência de selos. “Objeto associado” significa que você possui um objeto retirado do destino desejado nos últimos seis meses, como um livro da biblioteca do mago, roupa de cama de uma suíte real ou um pedaço de mármore da tumba secreta do lich. “Muito familiar” é um lugar que você já tenha ido muitas vezes, um lugar que você estudou cuidadosamente ou um local que você possa ver enquanto conjura a magia. “Visto casualmente” é algum lugar que você tenha visto mais de uma vez, mas que não seja muito familiar. “Visto uma vez” é um lugar que você só viu uma vez, possivelmente através de magia. “Descrição” é um lugar cuja localização e aparência você conhece através da descrição de outrem, talvez através de um mapa. “Destino falso” é um local que não existe. Talvez você tenha tentado espionar o santuário de um inimigo, mas, ao invés, viu uma ilusão ou você está tentando se teletransportar para um local familiar que não existe mais. No Alvo. Você e seu grupo (ou objeto alvo) aparecem onde você queria. Fora do Alvo. Você e seu grupo (ou objeto alvo) aparecem a uma distância aleatória fora do destino em uma direção aleatória. A distância do alvo é 1d10 x 1d10 por cento da distância que você viajou. Por exemplo, se você tentou viajar 180 quilômetros, mas apareceu fora do alvo e rolou um 5 e um 3 nos dois d10s, então você saiu do alvo 15 por cento ou 27 quilômetros. O Mestre determina a direção de fora do alvo aleatoriamente rolando um d8 e designando 1 como norte, 2 como nordeste, 3 como leste e assim por diante ao redor dos pontos cardeais. Se você seria teletransportado para uma cidade costeira, podendo cair a 27 quilômetros dela, no mar, você poderia ter problemas. Área Similar. Você e seu grupo (ou objeto alvo) aparecem em uma área diferente que, visualmente ou tematicamente, é similar a área alvo. Se você estava indo para o laboratório na sua casa, por exemplo, você pode parar em outro laboratório de mago ou em uma loja de suprimentos alquímicos que terá muitas ferramentas iguais às encontradas no seu laboratório. Geralmente, você aparecerá no local similar mais próximo, mas já que a magia não tem limite de alcance, você pode, concebivelmente, viajar para qualquer lugar no plano. Fiasco. A mágica imprevisível da magia resulta em uma jornada difícil. Cada criatura teletransportada (ou o objeto alvo) sofrem 3d10 de dano de energia e o Mestre rola novamente a tabela para ver onde você foi parar (fiascos múltiplos podem ocorrer, causando dano a cada vez).', '1 ação', 3, 'Instantânea', '3d10', TRUE, FALSE, FALSE, 7, 'Conjuração'),
(338, 'Teletransporte por Árvores', 'Você deve ter visto ou tocado a planta de destino pelo menos uma vez antes. Enquanto a magia durar, qualquer criatura pode entrar pela planta alvo e sair na planta de destino, usando 1,5 metro de deslocamento.', '1 ação', 3, '1 rodada', NULL, TRUE, TRUE, FALSE, 6, 'Conjuração'),
(339, 'Tempestade da Vingança', 'Uma agitada nuvem tempestuosa se forma, centrada num ponto que você possa ver e se espalha num raio de 108 metros. Relâmpagos riscam a área, trovões ressoam e ventos fortes silvam. Cada criatura embaixo da nuvem (a não mais de 1.500 metros abaixo da nuvem) quando ela aparece deve realizar um teste de resistência de Constituição. Com uma falha na resistência, uma criatura sofre 2d6 de dano trovejante e ficará surda por 5 minutos. A cada rodada que você mantiver a concentração nessa magia, a tempestade produzirá efeitos adicionais no seu turno. Rodada 2. Chuva ácida cai da nuvem. Cada criatura e objeto abaixo dela nuvem sofre 1d6 de dano ácido. Rodada 3. Você convoca seis relâmpagos da nuvem para atingir seis criaturas ou objetos, à sua escolha, abaixo da nuvem. Uma mesma criatura ou objeto não pode ser atingido por mais de um raio. Uma criatura atingida deve realizar um teste de resistência de Destreza. A criatura sofrerá 10d6 de dano elétrico se falhar na resistência ou metade desse dano se passar. Rodada 4. Granizo chove da nuvem. Cada criatura abaixo da nuvem sofre 2d6 de dano de concussão. Rodada 5–10. Ventos e chuva gelados atacam a área abaixo da nuvem. A área se torna terreno difícil e de escuridão densa. Cada criatura sofre 1d6 de dano de frio. Ataques com armas à distância na área são impossíveis. O vento e chuva contam como uma distração grave com os propósitos de manter a concentração em magias. Finalmente, ventos fortes (entre 30 e 75 quilômetros por hora) automaticamente dispersam nevoa, neblina e fenômenos similares na área, independentemente de serem mundanos ou mágicos.', '1 ação', 500, 'Concentração, até 1 minuto', '2d6', TRUE, TRUE, FALSE, 9, 'Conjuração'),
(340, 'Tempestade de Fogo', 'Uma tempestade feita de camadas crepitantes de chamas aparece em uma localização à sua escolha e no alcance da magia. A área da tempestade consiste em até 10 cubos de 5 metros, que você pode arranjar como quiser. Cada cubo deve ter ao menos uma face adjacente à face de outro cubo. Cada criatura na área deve fazer uma salvaguarda de Destreza. Se falhar, sofre 7d10 pontos de dano ígneo, ou metade do dano em caso de sucesso. O fogo danifica objetos na área e incendeia objetos inflamáveis que não estejam sendo usados ou carregados.', '1 ação', 45, 'Instantânea', '7d10', TRUE, TRUE, FALSE, 7, 'Evocação'),
(341, 'Tempestade de Gelo', 'Uma rajada de pedras de gelo batem no chão em um cilindro de 6 metros de raio por 12 metros de altura, centrado num ponto dentro do alcance. Cada criatura no cilindro deve realizar um teste de resistência de Destreza. Uma criatura sofre 2d8 de dano de concussão e 4d6 de dano de frio se falhar na resistência ou metade desse dano se obtiver sucesso. O granizo torna a área da tempestade em terreno difícil até o final do seu próximo turno. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 5° nível ou superior, o dano de concussão aumenta em 1d8 para cada nível do espaço acima do 4°.', '1 ação', 90, 'Instantânea', '2d8', TRUE, TRUE, TRUE, 4, 'Evocação'),
(342, 'Tentáculos Negros de Evard', 'Tentáculos negros se contorcem, preenchendo uma área de 6 metros quadrados de solo à sua vista, no alcance da magia. Enquanto a magia durar, os tentáculos transformam o solo da área em terreno difícil. Quando uma criatura entra pela primeira vez ou inicia o próprio turno na área afetada, ela deve fazer uma salvaguarda de Destreza. Se falhar, sofre 3d6 pontos de dano contundente, ficando contida pelos tentáculos até que a magia encerre.', '1 ação', 27, 'Concentração, até 1 minuto', '3d6', TRUE, TRUE, TRUE, 4, 'Conjuração'),
(343, 'Terremoto', 'Você cria um distúrbio sísmico num ponto no solo, que você possa ver dentro do alcance. Pela duração, um tremor intenso rompe o solo em um círculo com 30 metros de raio centrado no ponto e sacode criaturas e estruturas em contato com o chão na área. O solo na área torna-se terreno difícil. Cada criatura no solo que estiver se concentrando, deve realizar um teste de resistência de Constituição. Se falha na resistência, a concentração da criatura é interrompida. Quando você conjura essa magia, e ao final de cada turno que você gastar se concentrando nela, cada criatura no solo na área deve realizar um teste de resistência de Destreza. Se falhar na resistência, a criatura será derrubada no chão. Essa magia pode ter efeitos adicionais a depender do terreno na área, como determinado pelo Mestre. Fissuras. Fissuras se abrem por toda área da magia, no começo do seu próximo turno, após você conjurar a magia. Um total de 1d6 dessas fissuras se abrem em locais escolhidos pelo Mestre. Cada um tem 1d10 x 3 metros de profundidade, 3 metros de largura e se estende de uma extremidade até o lado oposto da área da magia. Uma criatura que estiver em um ponto onde uma fissura se abriu deve ser bem sucedido num teste de resistência de Destreza ou cairá dentro dela. Uma criatura que obtenha sucesso na resistência se move com a margem da fissura, à medida que ela se abre. Uma fissura que se abra abaixo de uma estrutura faz com que ela, automaticamente, desmorone (veja abaixo). Estruturas. O tremor causa 50 de dano de concussão a qualquer estrutura em contato com o solo na área, quando você conjurar a magia e, no início de cada turno até a magia terminar. Se a estrutura cair a 0 pontos de vida, ela desmorona e, potencialmente, fere criaturas próximas. Uma criatura a uma distância inferior a metade da altura da estrutura deve realizar um teste de resistência de Destreza. Se falhar na resistência, a criatura sofrerá 5d6 de dano de concussão, cairá no chão e estará soterrada nos escombros, precisando de um teste de Força (Atletismo) com CD 20, usando uma ação, para escapar. O Mestre pode ajustar a CD para cima ou para baixo, dependendo da natureza dos escombros. Se obtiver sucesso na resistência, a criatura sofre metade do dano e não estará caída ou soterrada.', '1 ação', 150, 'Concentração, até 1 minuto', '50', TRUE, TRUE, TRUE, 8, 'Evocação'),
(344, 'Terreno Alucinógeno', 'Você faz com que um terreno natural em um cubo de 45 metros no alcance da magia pareça, soe e cheire como outro tipo de terreno natural. Assim, campos abertos ou um caminho podem ser modificados para se assemelharem a um pântano, montanha, fenda ou algum outro terreno difícil ou intransitável. Estruturas manufaturadas, equipamentos e criaturas dentro da área não mudam a aparência.', '10 minutos', 90, '24 horas', NULL, TRUE, TRUE, TRUE, 4, 'Ilusão'),
(345, 'Toque Arrepiante', 'Você cria uma mão esquelética e fantasmagórica no espaço ocupado por uma criatura que se encontre no alcance da magia. Faça um ataque mágico à distância contra a criatura para atingi-la com um calafrio sepulcral. Se o ataque for bem-sucedido, ela sofre 1d8 pontos de dano necrótico e não pode recuperar pontos de vida até o início do seu próximo turno. Até lá, a mão se agarra ao alvo. Se você atacar um alvo morto-vivo, ele também terá desvantagem nas jogadas de ataque contra você até o final do seu próximo turno. O dano desta magia aumenta em 1d8 quando você alcança o 5° nível (2d8), 11° nível (3d8) e 17° nível (4d8).', '1 ação', 36, '1 rodada', '1d8', TRUE, TRUE, FALSE, 0, 'Necromancia'),
(346, 'Toque Chocante', 'Raios saltam de sua mão para transmitir um choque a uma criatura que você tentar tocar. Faça um ataque mágico corpo a corpo contra o alvo. Você tem vantagem na jogada de ataque se o alvo estiver vestindo uma armadura feita de metal. Se acertar, o alvo sofre 1d8 pontos de dano elétrico e não pode executar reações até o início do próximo turno dele. O dano desta magia aumenta em 1d8 quando você alcança o 5° nível (2d8), 11° nível (3d8) e 17° nível (4d8).', '1 ação', 1, 'Instantânea', '1d8', TRUE, TRUE, FALSE, 0, 'Evocação'),
(347, 'Toque Vampírico', 'O toque da sua mão coberta de sombras pode drenar a força vital dos outros para curar seus ferimentos. Realize um ataque corpo-a-corpo com magia contra uma criatura ao seu alcance. Se atingir, o alvo sofre 3d6 de dano necrótico e você recupera pontos de vida igual à metade do dano necrótico causado. Até a magia acabar, você pode realizar o ataque novamente, no seu turno, com uma ação. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 4° nível ou superior, o dano aumenta em 1d6 para cada nível do espaço acima do 3°.', '1 ação', 0, 'Concentração, até 1 minuto', '3d6', TRUE, TRUE, FALSE, 3, 'Necromancia'),
(348, 'Tranca Arcana', 'Você toca uma porta, janela, portão, baú, ou outro tipo de entrada que já esteja fechada, tornando-a bloqueada pela duração da magia. Você e as criaturas que designar ao realizar a conjuração podem abrir o objeto normalmente. Você também pode definir uma senha que, quando dita a até 1,5 metro do objeto, suprime esta magia durante 1 minuto. Caso contrário, o objeto fica trancado até que seja quebrado ou a magia seja dissipada ou suprimida.', '1 ação', 1, 'Até ser dissipada', NULL, TRUE, TRUE, TRUE, 2, 'Abjuração'),
(349, 'Truque de Corda', 'Você toca um pedaço de corda de até 18 metros de comprimento. Uma extremidade da corda, em seguida, sobe para o ar, até ficar perpendicular ao solo. Na extremidade superior da corda, uma entrada invisível se abre para um espaço extradimensional enquanto a magia durar. O espaço extradimensional pode ser alcançado escalando-se a corda até o topo. O espaço pode conter até oito criaturas de tamanho Médio ou menores.', '1 ação', 1, '1 hora', NULL, TRUE, TRUE, TRUE, 2, 'Transmutação'),
(350, 'Tsunami', 'Uma muralha de água aparece do nada num ponto, à sua escolha, dentro do alcance. Você pode fazer a muralha ter até 90 metros de comprimento, 90 metro de altura e 15 metros de espessura. A muralha permanece pela duração. Quando a muralha aparece, cada criatura dentro da área deve realizar um teste de resistência de Força. Se falhar na resistência, uma criatura sofrerá 6d10 de dano de concussão ou metade desse dano se passar na resistência. No início de cada um dos seus turnos, após a muralha aparecer, ela, junto com qualquer criatura nela, se afasta 15 metros de você. Qualquer criatura Enorme ou menor dentro da muralha ou no espaço que a muralha entrar quando ela se mover, deve ser bem sucedida num teste de resistência de Força ou sofrerá 5d6 de dano de concussão. Uma criatura pode sofrer esse dano apenas uma vez por rodada. No final do turno, a altura da muralha é reduzida em 15 metros e o dano que as criaturas sofrem da magia nas rodadas subsequentes é reduzido em 1d10. Quando a muralha chegar a 0 metro de altura, a magia acaba. Uma criatura pega pela muralha, pode se mover nadando. Devido à força da onda, no entanto, a criatura deve realizar um teste de Força (Atletismo) contra a CD da magia para conseguir se mover. Se ela falhar no teste, não conseguirá se mover. Uma criatura que se mova para fora da área, cairá no chão.', '1 minuto', 500, 'Concentração, até 6 rodadas', '6d10', TRUE, TRUE, FALSE, 8, 'Conjuração'),
(351, 'Velocidade', 'Escolha uma criatura voluntária, à sua vista e dentro do alcance da magia. Enquanto a magia durar, o alvo tem deslocamento dobrado, ganha +2 na CA, tem vantagem nas salvaguardas de Destreza e ganha uma ação adicional em cada um dos próprios turnos — utilizável apenas para Atacar (só com ataque armado), Correr, Desengajar, Esconder ou Usar um Objeto. Quando a magia termina, o alvo é dominado por uma onda de letargia e não pode se mover ou executar ações até o final do próximo turno dele.', '1 ação', 18, 'Concentração, até 1 minuto', NULL, TRUE, TRUE, TRUE, 3, 'Transmutação'),
(352, 'Ver o Invisível', 'Enquanto a magia durar, você vê criaturas e objetos invisíveis, como se eles fossem visíveis, além de poder ver no Plano Etéreo. Criaturas e objetos etéreos parecem fantasmagóricos e translúcidos.', '1 ação', 0, '1 hora', NULL, TRUE, TRUE, TRUE, 2, 'Adivinhação'),
(353, 'Viagem Planar', 'Você e até oito criaturas voluntárias, que estejam de mãos dadas em um círculo, são transportadas para um plano de existência diferente. Você pode especificar o destino alvo em termos gerais, como a Cidade de Bronze do Plano Elemental do Fogo ou o palácio de Dispater na segunda camada dos Nove Infernos e você aparece no ou perto do destino. Se você estiver tentando chegar a Cidade de Bronze, por exemplo, você poderia chegar na Estrada de Aço dela, em frente aos Portões de Cinzas ou contemplando a cidade do outro lado do Mar de Fogo, à critério do Mestre. Alternativamente, se você conhecer a sequência de selos do círculo de teletransporte em outro plano de existência, essa magia pode leva-lo para esse círculo. Se o círculo de teletransporte for muito pequeno para comportar as criaturas que você está transportando, elas aparecerão no espaço desocupado mais próximo do círculo. Você pode usar essa magia para banir uma criatura involuntária para outro plano. Escolha uma criatura ao seu alcance e realize um ataque corpo-a-corpo com magia contra ela. Se atingir, a criatura deve realizar um teste de resistência de Carisma. Se a criatura falhar na resistência, ela é transportada para um local aleatório no plano de existência que você especificou. Uma criatura, uma vez transportada, deve encontrar seu próprio meio de retornar para seu plano de existência atual.', '1 ação', 1, 'Instantânea', NULL, TRUE, TRUE, TRUE, 7, 'Conjuração'),
(354, 'Vidência', 'Essa magia protege uma criatura voluntária que você tocar e cria uma conexão mística entre você e o alvo até a magia acabar. Enquanto o alvo estiver a até 18 metros de você, ele recebe +1 de bônus na CA, nos testes de resistência e terá resistência a todos os danos. No entanto, a cada vez que ele sofrer dano, você sofrerá a mesma quantidade de dano. A magia acaba se você cair a 0 pontos de vida ou se você e o alvo ficarem separados a mais de 18 metros. Ela também termina se a magia for conjurada novamente em quaisquer das criaturas conectadas. Você também pode dissipar a magia com uma ação.', '10 minutos', 0, 'Concentração, até 10 minutos', NULL, TRUE, TRUE, TRUE, 5, 'Adivinhação'),
(355, 'Vínculo Protetor', 'Esta magia protege uma criatura voluntária que você toca, criando uma conexão mística entre o alvo e você enquanto a magia durar. Enquanto o alvo estiver no alcance de 18 metros do conjurador, ele ganha +1 de bônus na CA e em salvaguardas, e tem resistência contra todo tipo de dano. Além disso, cada vez que ele sofre dano, você sofre a mesma quantidade de dano. A magia se encerra se você cair a 0 ponto de vida ou se vocês se afastarem a mais de 18 metros um do outro.', '1 ação', 1, '1 hora', NULL, TRUE, TRUE, TRUE, 2, 'Abjuração'),
(356, 'Vinha Esmagadora', 'Você conjura uma vinha que brota do chão em um espaço desocupado, à sua escolha, que você possa ver dentro do alcance. Quando você conjura essa magia, você pode direcionar a vinha para que ela enlace uma criatura a até 9 metros dela que você possa ver. Essa criatura deve ser bem sucedida num teste de resistência de Destreza ou será arrastada 6 metros na direção da vinha. Até o fim da magia, você pode direcionar a vinha para enlaçar a mesma criatura ou uma diferente, com uma ação bônus, em cada um dos seus turnos.', '1 ação bônus', 9, 'Concentração, até 1 minuto', NULL, TRUE, TRUE, FALSE, 4, 'Conjuração'),
(357, 'Visão da Verdade', 'Você toca uma criatura voluntária. O alvo ganha a capacidade de ver as coisas como elas são verdadeiramente. Enquanto a magia durar, a criatura terá visão verdadeira, notará portas secretas escondidas por magia e poderá ver no Plano Etéreo em um alcance de 36 metros.', '1 ação', 1, '1 hora', NULL, TRUE, TRUE, TRUE, 6, 'Adivinhação'),
(358, 'Visão no Escuro', 'Ao tocar uma criatura voluntária você lhe concede a capacidade de enxergar no escuro. O alvo ganha visão no escuro com alcance de até 18 metros enquanto a magia durar.', '1 ação', 1, '8 horas', NULL, TRUE, TRUE, TRUE, 2, 'Transmutação'),
(359, 'Vitalidade Falsa', 'Reforçando-se com uma vitalidade necromântica ilusória, você ganha 1d4 + 4 pontos de vida temporários pela duração. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 2° nível ou superior, você ganha 5 pontos de vida temporários adicionais para cada nível do espaço de magia acima do 1°.', '1 ação', 0, '1 hora', '1d4+4', TRUE, TRUE, TRUE, 1, 'Necromancia'),
(360, 'Voo', 'Você toca uma criatura voluntária. O alvo ganha deslocamento de voo de 18 metros, pela duração. Quando a magia acabar, o alvo cai se ainda estiver no ar, a não ser que ele possa impedir a queda. Em Níveis Superiores. Quando você conjurar essa magia usando um espaço de magia de 4° nível ou superior, você pode afetar uma criatura adicional para cada nível do espaço acima do 3°.', '1 ação', 1, 'Concentração, até 10 minutos', NULL, TRUE, TRUE, TRUE, 3, 'Transmutação'),
(361, 'Zombaria Viciosa', 'Você lança uma série de insultos carregados com sutis encantamentos contra uma criatura à sua vista e no alcance da magia. Se o alvo puder ouvir você (embora ele não precise lhe entender), ele deve ser bem-sucedido em uma salvaguarda de Carisma. Se falhar, sofre 1d4 pontos de dano psíquico e terá desvantagem na próxima jogada de ataque que ele fizer antes do fim do próximo turno dele. O dano desta magia aumenta em 1d4 quando você alcança o 5° nível (2d4), o 11° nível (3d4) e o 17° nível (4d4).', '1 ação', 18, 'Instantânea', '1d4', TRUE, FALSE, FALSE, 0, 'Encantamento'),
(362, 'Zona da Verdade', 'Você cria uma zona mágica, protegendo contra enganação, numa área de esfera com 4,5 metros de raio centrada em um ponto à sua escolha, no alcance da magia. Enquanto a magia durar, quando uma criatura entra pela primeira vez ou inicia o turno na área da magia, ela deve fazer uma salvaguarda de Carisma. Se falhar, a criatura não pode falar uma mentira deliberada enquanto estiver no raio da magia. Você sabe se cada criatura é bem-sucedida ou se falhou na salvaguarda. Uma criatura afetada por esta magia está ciente dos efeitos dela e pode ser evasiva em suas respostas enquanto permanecer dentro dos limites da zona da verdade.', '1 ação', 18, '10 minutos', NULL, TRUE, TRUE, FALSE, 2, 'Encantamento');
